\echo '--- DQ Artefact: Ore Parameters ---'

do $$
declare
    v_dataset_id uuid;
begin
    select id into v_dataset_id
    from ores_dq_datasets_tbl
    where code = 'ore.parameters'
      and valid_to = ores_utility_infinity_timestamp_fn();

    if v_dataset_id is null then
        raise exception 'Dataset ore.parameters not found.';
    end if;

    delete from ores_dq_ore_parameters_artefact_tbl
    where dataset_id = v_dataset_id;

    insert into ores_dq_ore_parameters_artefact_tbl (
        dataset_id, tenant_id, id, version, scope, subtype, name, schema_name, xpath, position,
        ore_parameter_value_domain_code, is_required, label, help, description, default_text,
        format, introduced_in, removed_in
    ) values
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9d4dd39c-d765-5d2f-9845-1b203a8b803f', 0, 'Setup', '', 'implyTodaysFixings', 'ore.xsd', '/ORE/Setup/Parameter[@name=''implyTodaysFixings'']', 1, 'boolean', false, 'Imply today’s fixings', 'Whether today’s fixings are implied.', 'Decides what the run does about the fixing of the valuation date. When it is No, the fixing for the valuation date is loaded from the fixing file like any earlier fixing. When it is Yes, that fixing is not loaded and the engine implies it from the curves. Use Yes when the run prices off hypothetical market data, as in scenario analysis and stress testing, because a fixing from the real market would not match the hypothetical curves.', 'No. Today’s fixing is loaded.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f06585fd-c47a-50bf-b593-1e9b217431aa', 0, 'Setup', '', 'includeTodaysCashFlows', 'ore.xsd', '/ORE/Setup/Parameter[@name=''includeTodaysCashFlows'']', 2, 'boolean', false, 'Include today’s cash flows', 'Whether cash flows that pay today count.', 'Decides whether a cash flow that pays on the valuation date is part of the NPV or is treated as matured and excluded. It is one of two QuantLib flags that ORE exposes. A choice here applies to every analytic of the run. The simulation analytic has its own parameter of the same name, which applies to the XVA, XVA sensitivity and XVA stress analytics. Change it only when the NPV must agree with a system that treats payments on the valuation date the other way.', 'No. A cash flow that pays on the valuation date is treated as matured.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1708992e-bc24-54cc-af6a-3f540ac0d905', 0, 'Setup', '', 'includeReferenceDateEvents', 'ore.xsd', '/ORE/Setup/Parameter[@name=''includeReferenceDateEvents'']', 3, 'boolean', false, 'Include reference date events', 'Whether events on the reference date count.', 'Decides whether an event that falls on the valuation date is still counted in the NPV or is treated as matured and excluded. It is the companion of Include today’s cash flows, and the two together decide how a trade is valued on the day of its payment or event. A choice here applies to every analytic of the run, and the simulation analytic has its own parameter of the same name.', 'No. An event on the valuation date is treated as matured.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9adbb3bd-27b5-5cb4-a410-87aa7ca6885f', 0, 'Setup', '', 'enrichIndexFixings', 'ore.xsd', '/ORE/Setup/Parameter[@name=''enrichIndexFixings'']', 4, 'boolean', false, 'Enrich index fixings', 'Whether gaps in index fixings are filled.', 'Fills gaps in the history of an index. When it is Yes, a missing fixing is replaced by a fallback: the previous fixing first, and the next fixing when there is no previous one. Ignore fixing lag and Ignore fixing lead limit how far the fallback may be from the gap. Use it when the fixing file has gaps. It changes the numbers, because a trade that reads a filled fixing is valued with it.', 'No. A gap stays a gap.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1da534ec-eab3-56ad-ad5e-c82fe8376ba5', 0, 'Setup', '', 'ignoreFixingLag', 'ore.xsd', '/ORE/Setup/Parameter[@name=''ignoreFixingLag'']', 5, 'integer', false, 'Ignore fixing lag', 'A number of days. Zero turns the check off.', 'Works with Enrich index fixings. When the engine fills a gap in an index’s fixings with the previous fixing, this setting limits how old that previous fixing may be. If the previous fixing is more days older than the gap than this number, the engine does not use it as the fallback. A value of zero turns the check off, so a fixing of any age can fill the gap.', '0. The check is off.', 'A whole number of days, zero or more.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '00e61c64-dabc-5641-a971-5aa36eb37286', 0, 'Setup', '', 'ignoreFixingLead', 'ore.xsd', '/ORE/Setup/Parameter[@name=''ignoreFixingLead'']', 6, 'integer', false, 'Ignore fixing lead', 'A number of days. Zero turns the check off.', 'Works with Enrich index fixings. When the engine fills a gap in an index’s fixings with the next fixing, this setting limits how far ahead that next fixing may be. If the next fixing date leads the gap by more days than this number, the engine does not use it as the fallback. A value of zero turns the check off, so a fixing of any distance can fill the gap.', '0. The check is off.', 'A whole number of days, zero or more.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5505465e-2a64-56e5-b6d9-2083b1c54c4f', 0, 'Setup', '', 'observationModel', 'ore.xsd', '/ORE/Setup/Parameter[@name=''observationModel'']', 7, 'string', false, 'Observation model', 'How the engine handles QuantLib notifications.', 'Controls how many QuantLib observer notifications the engine uses when market data and fixings are updated and when the evaluation date moves. Notifications keep every dependent object up to date, and they cost time in a simulation. None is the normal QuantLib behaviour, where every update notifies every dependent object. The other three choices cut that cost in different ways and give a similar speed up. Disable switches all notifications off during market and fixing updates and when the evaluation date moves along a path, and the engine triggers the needed recalculations itself. Defer switches notifications off during market and fixing updates and runs the updates when notifications are on again. Unregister keeps notifications on but unregisters floating rate coupons from their indices, which removes most of them. The ORE user guide describes the setting as a control of performance during simulation.', 'None.', 'One of None, Disable, Defer, Unregister.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3421c621-f1c6-54f5-9283-93ee303c1a8d', 0, 'Setup', '', 'lazyMarketBuilding', 'ore.xsd', '/ORE/Setup/Parameter[@name=''lazyMarketBuilding'']', 8, 'boolean', false, 'Lazy market building', 'Whether the market is built on demand.', 'Decides when the engine builds the curves listed in today’s market. When it is Yes, a curve is built only when a trade or analytic asks for it, which saves time when the configuration lists curves that the portfolio never uses. When it is No, every curve in today’s market is built at the start.', 'Yes. Curves are built on demand.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b94a63f2-6b07-5541-9d6d-885c90318b8e', 0, 'Setup', '', 'buildFailedTrades', 'ore.xsd', '/ORE/Setup/Parameter[@name=''buildFailedTrades'']', 9, 'boolean', false, 'Build failed trades', 'Whether a failed trade is replaced by a dummy.', 'Decides what happens to a trade that cannot be loaded or built. When it is Yes, the engine builds a dummy trade of type Failed, with zero notional and zero NPV, so the trade still appears in the portfolio. When it is No, the failed trade is left out. Yes keeps the trade count honest, but a reader must know that a Failed trade has no value.', 'No. A failed trade is left out. The ORE application sets this default; the engine library itself defaults to Yes.', 'A flag, written Y or N, or true or false.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7eaed560-d3b3-59d6-b417-f4cfdbbfef97', 0, 'Setup', '', 'continueOnError', 'ore.xsd', '/ORE/Setup/Parameter[@name=''continueOnError'']', 10, 'boolean', false, 'Continue on error', 'Whether the run goes on after an error.', 'Decides whether the engine stops at the first error or goes on. When it is Yes, the engine does not exit on an error but tries to continue the processing, so one bad curve or trade does not lose the whole run, and the reports may be incomplete. When it is No, the run exits at the error.', 'Yes. The run goes on after an error.', 'A flag, written Y or N, or true or false.', '1.8.4.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7cbee0fa-3de8-51ba-bb10-2349e0bbeb21', 0, 'Setup', '', 'useAtParCouponsCurves', 'ore.xsd', '/ORE/Setup/Parameter[@name=''useAtParCouponsCurves'']', 11, 'boolean', false, 'At par coupons for curves', 'Par approximation or indexed ibor coupons for curves.', 'Decides how the engine models a floating rate coupon when it builds the curves. When it is Yes, it uses the par approximation of the coupon. When it is No, it uses indexed ibor coupons. The choice goes back to the QuantLib flag QL_USE_INDEXED_COUPON and its run time setting. Yes is also the default of a QuantLib build.', 'Yes. The par approximation.', 'A flag, written Y or N, or true or false.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1f7aeb5a-a7a5-5c90-aee9-2e4f3232fd1a', 0, 'Setup', '', 'useAtParCouponsTrades', 'ore.xsd', '/ORE/Setup/Parameter[@name=''useAtParCouponsTrades'']', 12, 'boolean', false, 'At par coupons for trades', 'Par approximation or indexed ibor coupons for trades.', 'Decides how the engine models a floating rate coupon when it builds the trades. When it is Yes, it uses the par approximation of the coupon. When it is No, it uses indexed ibor coupons. It is the companion of At par coupons for curves, and the two can differ. The choice goes back to the QuantLib flag QL_USE_INDEXED_COUPON and its run time setting.', 'Yes. The par approximation.', 'A flag, written Y or N, or true or false.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a21aa6fe-309c-523d-a689-75d96d4a6650', 0, 'Setup', '', 'nThreads', 'ore.xsd', '/ORE/Setup/Parameter[@name=''nThreads'']', 13, 'integer', false, 'Threads', 'A whole number of at least 1.', 'The number of threads the engine may use. More than one thread speeds up the analytics that spread their work over scenarios or paths: the sensitivity analytic, the classic exposure simulation and the AMC exposure simulation. These are the three analytics that the ORE user guide names.', '1.', 'A whole number, at least 1.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1099b6f2-189d-5735-b198-5d3f867600f3', 0, 'Setup', '', 'logMask', 'ore.xsd', '/ORE/Setup/Parameter[@name=''logMask'']', 14, 'integer', false, 'Log mask', 'A bit set, such as 31.', 'Decides which messages the engine writes to its log file. Each kind of message has a bit: 1 alert, 2 critical, 4 error, 8 warning, 16 notice, 32 debug and 64 data. Add the bits of the kinds you want. Common totals are 15 for alert to warning, 31 for the same and notice, 63 for the same and debug, and 127 for the same and data. A higher total writes more and makes a larger log. The value 255 gives the most detail.', '15. Alert, critical, error and warning.', 'A whole number. A bit set of the message kinds.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '15d0742f-c60a-5999-a941-2d7a86f16ab1', 0, 'Setup', '', 'gzipCompressionLevel', 'ore.xsd', '/ORE/Setup/Parameter[@name=''gzipCompressionLevel'']', 15, 'integer', false, 'Gzip compression level', 'A whole number from 0 to 9.', 'Sets how strongly the engine compresses the zipped cube files it writes. The value is a whole number from 0 to 9. A value of 0 means no compression, which gives the fastest write and the largest file. A value of 9 means the strongest compression, which gives the slowest write and the smallest file. A value outside 0 to 9 is an error. The default of 6 balances speed and size.', '6. A balance of speed and size.', 'A whole number from 0 to 9.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '67d6ac78-3278-5d8d-8552-dc3c95901fd8', 0, 'Setup', '', 'asofDate', 'ore.xsd', '/ORE/Setup/Parameter[@name=''asofDate'']', 16, 'date', true, 'Valuation date', 'A date. The date the run values the portfolio at.', 'Sets the valuation date of the run, also called the as of date. ORE sets the evaluation date of QuantLib to this date, reads the market data and the fixings for it and values every trade at it. Every analytic uses it. For example, 2016-02-05 values the portfolio with the market of 5 February 2016. Use the date of the market data file.', 'None. The document must carry a date.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'af4d6968-0c06-5bb2-baaf-d97280891c9b', 0, 'Setup', '', 'baseCurrency', 'ore.xsd', '/ORE/Setup/Parameter[@name=''baseCurrency'']', 17, 'string', false, 'Base currency', 'A currency code, for example EUR.', 'Names the currency in which results are stated when an analytic converts them to one currency, for example the NPV report and the exposure reports. ORE converts a result in another currency at the spot rate of the valuation date. For example, EUR states all results in euro. Analytics that carry their own base currency use that one for their own report.', 'None. ORE takes the currency of the discounting index when that one is set.', 'A currency code of three letters, for example EUR or USD.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bad3b567-f8f1-5c17-81f5-366a51e5d344', 0, 'Setup', '', 'discountingIndex', 'ore.xsd', '/ORE/Setup/Parameter[@name=''discountingIndex'']', 18, 'string', false, 'Discounting index', 'An index name, for example EUR-EONIA.', 'Names the main discounting index of the run. When the base currency is not set, ORE takes the currency of this index as the base currency. For example, EUR-EONIA sets the base currency to EUR. Set it only when the base currency is not given in the document.', 'None.', 'An index name written as currency, dash and index, for example EUR-EONIA or USD-FedFunds.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '40285069-74c5-555d-846a-f0040938da53', 0, 'Setup', '', 'dryRun', 'ore.xsd', '/ORE/Setup/Parameter[@name=''dryRun'']', 19, 'boolean', false, 'Dry run', 'A flag. Y builds the run and does not value.', 'Decides whether the valuation engine does all of its work. When it is Yes, the engine prices the trades for the first scenario sample only. It fills the other samples with the value at the valuation date plus a small made-up shift. Use Yes to test a document and its input files in a short time before a long run. The results of a dry run are not real and are not for use.', 'No. The engines value the portfolio.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cc78d431-9051-5fb3-8196-75cd495ad322', 0, 'Setup', '', 'inputPath', 'ore.xsd', '/ORE/Setup/Parameter[@name=''inputPath'']', 20, 'string', true, 'Input path', 'A path to the input directory.', 'Names the directory that ORE reads input files from. Every file name in the Setup block, for example the portfolio file and the curve configuration file, is relative to it. A relative path counts from the directory the program starts in. For example, Input reads the files from the directory Input next to the program.', 'None. The document must carry a path.', 'A path. ORE reads it relative to the directory the program starts in, or as an absolute path.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8ea41228-fd5e-5524-a852-822c7d3e8391', 0, 'Setup', '', 'outputPath', 'ore.xsd', '/ORE/Setup/Parameter[@name=''outputPath'']', 21, 'string', true, 'Output path', 'A path to the output directory.', 'Names the directory that ORE writes the reports, the log and the cubes to. Every output file name in the document is relative to it. A relative path counts from the directory the program starts in. For example, Output writes the results to the directory Output next to the program.', 'None. The document must carry a path.', 'A path. ORE reads it relative to the directory the program starts in, or as an absolute path.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a6f5b2e7-f9b8-5d4c-bc58-b042e30abf46', 0, 'Setup', '', 'inputPathMarket', 'ore.xsd', '/ORE/Setup/Parameter[@name=''inputPathMarket'']', 22, 'string', false, 'Market input path', 'A path. No release of ORE reads it.', 'No release of the ORE sources reads this parameter. Some example documents carry it to name a separate directory for the market data files. ORE ignores it, so the market data files follow the input path. Do not rely on it.', 'None. ORE ignores the parameter.', 'A path. ORE reads it relative to the directory the program starts in, or as an absolute path.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2804d9d7-ff42-52c8-818f-40735a873f86', 0, 'Setup', '', 'inputPathPortfolio', 'ore.xsd', '/ORE/Setup/Parameter[@name=''inputPathPortfolio'']', 23, 'string', false, 'Portfolio input path', 'A path. No release of ORE reads it.', 'No release of the ORE sources reads this parameter. Some example documents carry it to name a separate directory for the portfolio files. ORE ignores it, so the portfolio file follows the input path. Do not rely on it.', 'None. ORE ignores the parameter.', 'A path. ORE reads it relative to the directory the program starts in, or as an absolute path.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e2db74fe-e396-5dc2-8601-5722e347288f', 0, 'Setup', '', 'logFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''logFile'']', 24, 'string', false, 'Log file', 'A file name for the log.', 'Names the file that ORE writes its log to. The path is relative to the output path. The Logging block has a parameter of the same name, and the Logging block wins when both are present. For example, log.txt writes the log to the file log.txt in the output directory.', 'None. ORE writes the log to the file given in the Logging block, or to no file.', 'A file name or a path. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '52ff7899-d400-58c0-a872-a2e5cb7ca7aa', 0, 'Setup', '', 'marketDataFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''marketDataFile'']', 25, 'string', true, 'Market data file', 'A file name of the market quotes.', 'Names the file that holds the market quotes for the valuation date: one line for each quote with the date, the quote name and the value. ORE builds the curves and surfaces of today''s market from these quotes. You can name more than one file, separated by a comma or a semicolon. For example, market_20160205.txt holds the quotes of 5 February 2016.', 'None. The document must name the file, unless the run loads the market data some other way.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e6669e19-e57a-58c1-b7de-a23c72ca0e92', 0, 'Setup', '', 'fixingDataFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''fixingDataFile'']', 26, 'string', true, 'Fixing data file', 'A file name of the index fixings.', 'Names the file that holds the historic fixings of the indices: one line for each fixing with the date, the index name and the value. Coupons that have already fixed use these values. You can name more than one file, separated by a comma or a semicolon. For example, fixings_20160205.txt holds the fixings known on 5 February 2016. A missing fixing makes the valuation of a trade that needs it fail, unless the run implies today''s fixing or fills gaps.', 'None. The document must name the file, unless the run loads the fixings some other way.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2f27cc6d-812f-5fe1-a217-2aae197572cd', 0, 'Setup', '', 'dividendDataFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''dividendDataFile'']', 27, 'string', false, 'Dividend data file', 'A file name of the equity dividends.', 'Names the file that holds the historic dividends of equities. ORE needs them to value equity options and forwards that depend on dividends. The file is optional and the run needs none when the portfolio holds no such trade. For example, dividends_20160205.txt.', 'None. The run loads no dividends.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.5.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9fee329b-e5f1-5a8b-977c-bf6f2da29b0e', 0, 'Setup', '', 'fixingCutoff', 'ore.xsd', '/ORE/Setup/Parameter[@name=''fixingCutoff'']', 28, 'date', false, 'Fixing cut-off', 'A date. The ORE application reads it, with the spelling fixingCutoff.', 'Sets the date after which the ORE application drops fixings from the fixing file. A fixing after the cut-off date is ignored, so the run does not use data from the future. For example, 2016-02-04 ignores a fixing dated 5 February 2016. The input parameters of the library read the same choice under the name fixingCutOffDate, with a capital O. When the date is not set, the application cuts at the valuation date, or the day before it when today''s fixings are implied.', 'None. The application cuts at the valuation date.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ced0991e-bbd2-53f9-beb6-34289de2c486', 0, 'Setup', '', 'fixingCutOffDate', 'ore.xsd', '/ORE/Setup/Parameter[@name=''fixingCutOffDate'']', 29, 'date', false, 'Fixing cut-off date', 'A date. The library reads it, with the spelling fixingCutOffDate.', 'Sets the date after which the library drops fixings. A fixing after the cut-off date is ignored. For example, 2016-02-04 ignores a fixing dated 5 February 2016. The ORE application reads the same choice under the name fixingCutoff. Use this spelling when the document goes to a program built on the library.', 'None. No fixing is dropped.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b99eb7ad-c048-560d-bed6-ad351852463b', 0, 'Setup', '', 'marketDataLoaderInput', 'ore.xsd', '/ORE/Setup/Parameter[@name=''marketDataLoaderInput'']', 30, 'string', false, 'Market data loader input', 'A name of the loader for the market data.', 'Names the input of the market data loader. A program built on the library sets the loader to read market data and fixings. The value tells the loader where to read them from. Leave it empty when the market data comes from the market data file.', 'None. The run reads the market data and fixings from the files.', 'A text, written as in the example.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '33f8e18d-4ace-5c93-8c55-d5076fb3b217', 0, 'Setup', '', 'marketDataLoaderOutput', 'ore.xsd', '/ORE/Setup/Parameter[@name=''marketDataLoaderOutput'']', 31, 'string', false, 'Market data loader output', 'A name for the output of the market data loader.', 'Names the output of the market data loader. A program built on the library sets the loader to store the market data and the fixings of a run, so that another run can load the same data again. The value tells the loader where to store them. Leave it empty to store nothing.', 'None. The run stores nothing.', 'A text, written as in the example.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ddc69457-da5f-5c47-842f-d4689ac8f387', 0, 'Setup', '', 'entireMarket', 'ore.xsd', '/ORE/Setup/Parameter[@name=''entireMarket'']', 32, 'boolean', false, 'Load the entire market', 'A flag. Y loads every quote of the file.', 'Decides how much of the market data file the run loads. When it is Yes, ORE loads every quote of the file. When it is No, ORE loads only the quotes that the curve configuration asks for, which is faster. The library defaults to No. The ORE application sets Yes when it reads ore.xml, so a document run by the application loads everything.', 'No in the library. The ORE application sets Yes.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '001b9cac-102a-5d76-a01b-82c3e9a380f1', 0, 'Setup', '', 'allFixings', 'ore.xsd', '/ORE/Setup/Parameter[@name=''allFixings'']', 33, 'boolean', false, 'Load all fixings', 'A flag. Y loads every fixing of the file.', 'Decides how much of the fixing file the run loads. When it is Yes, ORE loads every fixing of the file. When it is No, ORE loads only the fixings of the indices that the portfolio and the market need. The library defaults to No. The ORE application sets Yes when it reads ore.xml. Use No to load faster with a large file.', 'No in the library. The ORE application sets Yes.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '130ba9f9-f2ea-5739-856d-cd33cf669ba1', 0, 'Setup', '', 'eomInflationFixings', 'ore.xsd', '/ORE/Setup/Parameter[@name=''eomInflationFixings'']', 34, 'boolean', false, 'End-of-month inflation fixings', 'A flag. Y loads inflation fixings at the end of the month.', 'Decides how ORE stores the fixing of an inflation index. When it is Yes, ORE stores the fixing at the end of the month it belongs to, which is how most inflation indices publish. When it is No, ORE stores the fixing at the start of the month. Change it only when the fixing file dates its inflation fixings at the start of the month.', 'Yes. ORE stores an inflation fixing at the end of its month.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd22c2fb1-3a42-57dc-905b-ed4d23d07e5a', 0, 'Setup', '', 'useMarketDataFixings', 'ore.xsd', '/ORE/Setup/Parameter[@name=''useMarketDataFixings'']', 35, 'boolean', false, 'Use fixings of the market data', 'A flag. ORE reads it and does not use it.', 'The input parameters read this parameter and keep it. No code of the ORE sources uses the value, so the choice has no effect on a run. The intent is to take the fixings from the market data file, where the file holds them, and not from the fixing file.', 'Yes. The value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ef12f0ae-d410-5f48-be21-b60f19165190', 0, 'Setup', '', 'curveConfigFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''curveConfigFile'']', 36, 'string', true, 'Curve configuration file', 'A file name of the curve configuration.', 'Names the file that says how ORE builds each curve and surface: which quotes it uses, how it interpolates and which conventions it takes. Today''s market refers to the curves in this file by identifier. For example, curveconfig.xml. You can name more than one file, separated by a comma or a semicolon, and a later file adds to an earlier one.', 'None. The document must name the file.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2c022d7d-616c-57cf-af51-2f91e50dc76c', 0, 'Setup', '', 'curveConfigOverride', 'ore.xsd', '/ORE/Setup/Parameter[@name=''curveConfigOverride'']', 37, 'string', false, 'Curve configuration override', 'Curve configuration XML. It overrides the file.', 'Holds a curve configuration inside the document. A curve in this block replaces the curve of the same identifier in the curve configuration file. Use it to change one curve for a run without a copy of the whole file.', 'None. The run uses the file only.', 'An XML element, the curve configuration, written inside the parameter.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ed3fb910-f8ed-5d12-b244-834791d0ac12', 0, 'Setup', '', 'conventionsFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''conventionsFile'']', 38, 'string', true, 'Conventions file', 'A file name of the market conventions.', 'Names the file that holds the market conventions: the day count, the calendar, the settlement lag and the business day rule of each instrument and index. The curves and the trades look their conventions up by identifier. For example, conventions.xml.', 'None. The document must name the file.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b5dc99e2-785a-57e2-bef3-5fbbf99448b4', 0, 'Setup', '', 'conventionsOverride', 'ore.xsd', '/ORE/Setup/Parameter[@name=''conventionsOverride'']', 39, 'string', false, 'Conventions override', 'Conventions XML. It overrides the file.', 'Holds conventions inside the document. A convention in this block replaces the convention of the same identifier in the conventions file. Use it to change one convention for a run without a copy of the whole file.', 'None. The run uses the file only.', 'An XML element, the conventions, written inside the parameter.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '652bca21-65d9-57ee-bbf9-7b8fdf68d6c1', 0, 'Setup', '', 'marketConfigFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''marketConfigFile'']', 40, 'string', true, 'Today''s market file', 'A file name of today''s market configuration.', 'Names the file that defines today''s market: which curve, surface or quote each market object uses, grouped into named market configurations. The Markets block picks a configuration from this file for each purpose. For example, todaysmarket.xml.', 'None. The document must name the file.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eba1caa5-4d97-52f8-92ac-3f7d5dce1ab4', 0, 'Setup', '', 'pricingEnginesFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''pricingEnginesFile'']', 41, 'string', true, 'Pricing engines file', 'A file name of the pricing engines.', 'Names the file that says which pricing engine and which model prices each product, and with which engine settings. Every trade looks up its engine here by product type. For example, pricingengine.xml.', 'None. The document must name the file.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fe3d2fc3-0420-5577-9ec7-cfd22b0c3c76', 0, 'Setup', '', 'pricingEnginesOverride', 'ore.xsd', '/ORE/Setup/Parameter[@name=''pricingEnginesOverride'']', 42, 'string', false, 'Pricing engines override', 'Pricing engine XML. It overrides the file.', 'Holds pricing engine settings inside the document. An entry in this block replaces the entry of the same product in the pricing engines file. Use it to change one engine for a run without a copy of the whole file.', 'None. The run uses the file only.', 'An XML element, the pricing engines, written inside the parameter.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '24eeb280-460e-5ae2-86d0-0a8407d1aed4', 0, 'Setup', '', 'pricingEnginesFileScenario', 'ore.xsd', '/ORE/Setup/Parameter[@name=''pricingEnginesFileScenario'']', 43, 'string', false, 'Scenario pricing engines file', 'A file name. No release of ORE reads it.', 'No release of the ORE sources reads this parameter. Some example documents carry it to name a second pricing engines file for scenario runs. ORE ignores it, so the scenario runs use the file of the pricing engines parameter.', 'None. ORE ignores the parameter.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '45764996-b490-5ae6-825f-c52a90d15006', 0, 'Setup', '', 'portfolioFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''portfolioFile'']', 44, 'string', true, 'Portfolio file', 'A file name of the portfolio.', 'Names the file that holds the trades the run values. You can name more than one file, separated by a comma or a semicolon, and ORE joins their trades. A name that is a directory loads the files inside it. For example, portfolio.xml.', 'None. The document must name the file.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f3aba04f-f89e-51f9-8382-4d2cc50c2965', 0, 'Setup', '', 'portfolioRecurseIntoSubDirectories', 'ore.xsd', '/ORE/Setup/Parameter[@name=''portfolioRecurseIntoSubDirectories'']', 45, 'boolean', false, 'Portfolio sub-directories', 'A flag. No release of ORE reads it.', 'No release of the ORE sources reads this parameter. Some example documents carry it to load the portfolio files of the sub-directories of a directory. ORE ignores it, so name each directory or file yourself.', 'No. ORE ignores the parameter.', 'A flag, written Y or N, or true or false.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4481fb5e-f81a-5dc2-9bed-480d68c5edc8', 0, 'Setup', '', 'counterpartyFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''counterpartyFile'']', 46, 'string', false, 'Counterparty file', 'A file name of the counterparty information.', 'Names the file that holds the counterparty data some capital analytics need, for example the credit quality and the SA-CCR and CVA parameters of each counterparty. For example, counterparty.xml. Leave it out when no analytic of the run uses counterparty data.', 'None. The run loads no counterparty data.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ff23189c-c992-58e0-890a-41d6ca892b17', 0, 'Setup', '', 'calendarAdjustment', 'ore.xsd', '/ORE/Setup/Parameter[@name=''calendarAdjustment'']', 47, 'string', false, 'Calendar adjustment file', 'A file name of the calendar adjustments.', 'Names the file that lists holidays and business days to add to named calendars. Use it to correct a calendar of QuantLib, for example to add a closure the library does not know. For example, calendaradjustment.xml.', 'None. ORE uses the calendars as they are.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.5.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '572b0086-f069-5332-9995-8aa04ea39e30', 0, 'Setup', '', 'currencyConfiguration', 'ore.xsd', '/ORE/Setup/Parameter[@name=''currencyConfiguration'']', 48, 'string', false, 'Currency configuration file', 'A file name of extra currencies.', 'Names the file that adds currencies to the ones ORE knows. The file adds only currencies that are not yet in QuantLib or QuantExt, and it never changes one that is. The example file lists all ISO currencies and a few unofficial codes. For example, currencies.xml.', 'None. ORE knows its built-in currencies only.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '14c60105-f2a3-59dc-a396-58fe1395a1bc', 0, 'Setup', '', 'referenceDataFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''referenceDataFile'']', 49, 'string', false, 'Reference data file', 'A file name of the reference data.', 'Names the file that holds reference data: the details of the bonds, the credit names and the other objects a trade refers to by identifier. A trade that holds only an identifier needs this file. For example, referencedata.xml.', 'None. The run loads no reference data.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.5.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2f2c8735-9118-5329-86e0-0565382e5010', 0, 'Setup', '', 'referenceDataOverride', 'ore.xsd', '/ORE/Setup/Parameter[@name=''referenceDataOverride'']', 50, 'string', false, 'Reference data override', 'Reference data XML. It overrides the file.', 'Holds reference data inside the document. An entry in this block replaces the entry of the same identifier in the reference data file. Use it to change one object for a run without a copy of the whole file.', 'None. The run uses the file only.', 'An XML element, the reference data, written inside the parameter.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9766ea1f-e8b0-5046-b5af-13ad0dcb6635', 0, 'Setup', '', 'iborFallbackConfig', 'ore.xsd', '/ORE/Setup/Parameter[@name=''iborFallbackConfig'']', 51, 'string', false, 'Ibor fallback file', 'A file name of the Ibor fallback rules.', 'Names the file that says how a discontinued Ibor index falls back to a risk free rate: the replacement index, the spread and the switch date. Trades on a discontinued index use it. For example, iborFallbackConfig.xml.', 'None. ORE uses the fallback rules built into the program.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'af3f755d-9ffb-5250-b9b0-da97192cea9c', 0, 'Setup', '', 'iborFallbackOverride', 'ore.xsd', '/ORE/Setup/Parameter[@name=''iborFallbackOverride'']', 52, 'boolean', false, 'Ibor fallback override', 'A flag. Y switches the Ibor fallbacks on.', 'Decides whether ORE applies the Ibor fallback rules before their switch dates. When it is Yes, ORE moves every switch date to one year before the valuation date, so every index that has a fallback has already switched. When it is No, ORE applies a fallback from its own switch date.', 'No. ORE applies a fallback from its switch date.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f76be579-933f-5a12-ae30-0cd887f28afb', 0, 'Setup', '', 'baselTrafficLightConfig', 'ore.xsd', '/ORE/Setup/Parameter[@name=''baselTrafficLightConfig'']', 53, 'string', false, 'Basel traffic light file', 'A file name of the traffic light zones.', 'Names the file that sets the Basel traffic light zones for backtests: how many exceptions place a result in the green, yellow and red zones. The market risk backtest analytic reads it. Leave it out when no run does a backtest.', 'None. The backtest uses no zones.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.13.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b63ea6a1-3304-5006-80c0-9d9ecc8c262c', 0, 'Setup', '', 'scriptLibrary', 'ore.xsd', '/ORE/Setup/Parameter[@name=''scriptLibrary'']', 54, 'string', false, 'Script library file', 'A file name of the script library.', 'Names the file that holds the scripts of scripted trades. A scripted trade picks its payoff script by name from this library. Leave it out when the portfolio has no scripted trade.', 'None. The run loads no scripts.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f0a031e3-e2ec-5f13-8cc2-88b625c65acf', 0, 'Setup', '', 'nameMappingInputFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''nameMappingInputFile'']', 55, 'string', false, 'Name mapping file', 'A file name of the SIMM name mapping.', 'Names the file that maps the names of issuers and underlyings to the names the SIMM expects. The CRIF analytics read it. The same parameter in the block of an analytic wins, and this one is the last place ORE looks.', 'None. The run maps no names.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7570b21f-463a-5476-8d59-f6d05fcf0bd1', 0, 'Setup', '', 'bucketMappingInputFile', 'ore.xsd', '/ORE/Setup/Parameter[@name=''bucketMappingInputFile'']', 56, 'string', false, 'Bucket mapping file', 'A file name of the SIMM bucket mapping.', 'Names the file that maps each issuer and underlying to its SIMM bucket. The CRIF analytics read it. The same parameter in the block of an analytic wins, and this one is the last place ORE looks.', 'None. The run maps no buckets.', 'A file name or a path. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b80cbc2a-2717-5aa3-9d98-363f26ad162b', 0, 'Setup', '', 'allowModelBuilderFallbacks', 'ore.xsd', '/ORE/Setup/Parameter[@name=''allowModelBuilderFallbacks'']', 57, 'boolean', false, 'Allow model builder fallbacks', 'A flag. ORE reads it and does not use it.', 'The input parameters read this parameter and keep it. No code of the ORE sources uses the value, so the choice has no effect on a run. The intent is to let a model builder use a fallback when its calibration fails.', 'Yes. The value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a3aca273-93ec-5873-bc95-e57f4c4c995e', 0, 'Setup', '', 'enableScenarioInformation', 'ore.xsd', '/ORE/Setup/Parameter[@name=''enableScenarioInformation'']', 58, 'boolean', false, 'Scenario information', 'A flag. Y keeps the information on scenarios.', 'Decides whether ORE records extra information on each scenario while it runs the valuation engine, for example which risk factor each scenario shifts. The run takes more memory and time when it is Yes. Switch it on only when a report needs that information.', 'No. ORE records nothing.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e6fe9e8d-56f9-5b37-8061-f446415a0836', 0, 'Setup', '', 'includePastCashflows', 'ore.xsd', '/ORE/Setup/Parameter[@name=''includePastCashflows'']', 59, 'boolean', false, 'Include past cash flows', 'A flag. Y keeps cash flows before the valuation date.', 'Decides whether the cash flow report lists the cash flows that paid before the valuation date. When it is Yes, the report lists them. When it is No, the report lists only the cash flows from the valuation date on. The cash flow analytic has a parameter of the same name, and the Setup block wins when both are present.', 'No. The report holds the future cash flows only.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b6204d0e-c31e-5058-8570-bc04b4750c91', 0, 'Setup', '', 'reportNaString', 'ore.xsd', '/ORE/Setup/Parameter[@name=''reportNaString'']', 60, 'string', false, 'Report not-available text', 'A text for a value that is not available.', 'Sets the text that a report writes in a field that has no value. For example, #N/A is the text a spreadsheet shows for a missing value. Set another text when a program that reads the report needs a different mark.', '#N/A', 'A text.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '678cc334-347e-5a10-88b7-65ccafed0d59', 0, 'Setup', '', 'csvSeparator', 'ore.xsd', '/ORE/Setup/Parameter[@name=''csvSeparator'']', 61, 'string', false, 'CSV separator', 'A single character that separates fields.', 'Sets the character that separates the fields of a CSV report. A semicolon helps when a spreadsheet uses the comma as the decimal sign. The text must be one character. For example, ; writes semicolon separated reports.', 'A comma.', 'One character.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bac6c63d-22a5-5d31-a21a-724f740c56ad', 0, 'Setup', '', 'csvCommentReportHeader', 'ore.xsd', '/ORE/Setup/Parameter[@name=''csvCommentReportHeader'']', 62, 'string', false, 'CSV comment character', 'A single character. It starts the header line of a report.', 'Sets the character that starts the header line of a CSV report. ORE writes this character in front of the header, so a reader can treat the header as a comment. The text must be one character. For example, # writes #TradeId,NPV as the header.', 'A hash mark, #.', 'One character.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3367475b-4ca2-51fa-ae15-01b83b48a92c', 0, 'Setup', '', 'reportBufferSize', 'ore.xsd', '/ORE/Setup/Parameter[@name=''reportBufferSize'']', 63, 'integer', false, 'Report buffer size', 'A number of rows kept in memory.', 'Sets how many rows ORE keeps in memory for each block of an in-memory report. A buffer keeps the memory use low for a large report. A value of 0 keeps the whole report in one block. For example, 100000 stores a report in blocks of 100000 rows.', '0. The whole report stays in memory.', 'A whole number of zero or more.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ea6d5bb6-aec9-59d4-b251-aaa2ad3d679f', 0, 'Setup', '', 'additionalResults', 'ore.xsd', '/ORE/Setup/Parameter[@name=''additionalResults'']', 64, 'boolean', false, 'Write additional results', 'A flag. Y writes the additional results report.', 'Decides whether the NPV analytic writes the additional results of each trade, for example the legs, the curves and the model values that the pricing engine reports. The additionalResults block is the place for the same choice. The Setup spelling is the older one. Use Yes to look inside a price.', 'No. ORE writes no additional results.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6cb5ab5e-c479-5ca4-a5d7-6ccb985bf614', 0, 'Setup', '', 'accrualDate', 'ore.xsd', '/ORE/Setup/Parameter[@name=''accrualDate'']', 65, 'string', false, 'Accrual date', 'A date. No release of ORE reads it.', 'No release of the ORE sources reads this parameter. Some example documents carry it. ORE ignores it. Do not rely on it.', 'None. ORE ignores the parameter.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3b8a2eab-5ff5-542f-9432-462b889881e1', 0, 'Setup', '', 'dateCalendar', 'ore.xsd', '/ORE/Setup/Parameter[@name=''dateCalendar'']', 66, 'string', false, 'Date calendar', 'A calendar name. No release of ORE reads it.', 'No release of the ORE sources reads this parameter. Some example documents carry it. ORE ignores it. Do not rely on it.', 'None. ORE ignores the parameter.', 'A calendar name, for example TARGET.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '82e91942-2074-5a66-8182-fbd1dbf9e14d', 0, 'Setup', '', 'dateConvention', 'ore.xsd', '/ORE/Setup/Parameter[@name=''dateConvention'']', 67, 'string', false, 'Date convention', 'A convention name. No release of ORE reads it.', 'No release of the ORE sources reads this parameter. Some example documents carry it. ORE ignores it. Do not rely on it.', 'None. ORE ignores the parameter.', 'A business day convention, for example Following.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1b153b12-0ad3-5ed3-8491-808f055e6ee9', 0, 'Setup', '', 'defaultMappingToIdentity', 'ore.xsd', '/ORE/Setup/Parameter[@name=''defaultMappingToIdentity'']', 68, 'boolean', false, 'Default mapping to identity', 'A flag. No release of ORE reads it.', 'No release of the ORE sources reads this parameter. Some example documents carry it. ORE ignores it. Do not rely on it.', 'None. ORE ignores the parameter.', 'A flag, written Y or N, or true or false.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c5bb10bb-544f-5a06-a690-577f49a51158', 0, 'Setup', '', 'useAnalytics', 'ore.xsd', '/ORE/Setup/Parameter[@name=''useAnalytics'']', 69, 'boolean', false, 'Use analytics', 'A flag. The latest release no longer reads it.', 'Earlier releases read this parameter to switch the analytics on. Later releases switch an analytic on with its own active parameter, and they do not read this one. A document that carries it runs the same.', 'None. The latest release ignores the parameter.', 'A flag, written Y or N, or true or false.', '1.8.9.0', '1.8.9.1'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bfe149c8-84f1-521e-98bd-f51d9bc37a23', 0, 'Logging', '', 'logFile', 'ore.xsd', '/ORE/Logging/Parameter[@name=''logFile'']', 1, 'string', false, 'Log file', 'A file name for the log.', 'Names the file that ORE writes its log to. The path is relative to the output path. This parameter wins over the parameter of the same name in the Setup block. For example, log.txt writes the log to the file log.txt in the output directory.', 'None. ORE uses the log file of the Setup block.', 'A file name or a path. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e16f1ee5-6df1-5426-a0da-34dfa968a12f', 0, 'Logging', '', 'logMask', 'ore.xsd', '/ORE/Logging/Parameter[@name=''logMask'']', 2, 'integer', false, 'Log detail', 'A number that selects the kinds of message to log.', 'Selects which messages ORE writes to the log. Each kind of message has one bit: Alert is 1, Critical is 2, Error is 4, Warning is 8, Notice is 16, Debug is 32 and Data is 64. ORE writes a message when its bit is set in the mask. For example, 31 writes alerts, criticals, errors, warnings and notices. 255 writes everything, the most detail and the largest file. This parameter wins over the parameter of the same name in the Setup block.', 'None. ORE uses the mask of the Setup block.', 'A whole number from 0 to 255.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '05992408-261f-583c-9ea4-72f93aaf24b9', 0, 'Logging', '', 'progressLogFile', 'ore.xsd', '/ORE/Logging/Parameter[@name=''progressLogFile'']', 3, 'string', false, 'Progress log file', 'A file name for the progress log.', 'Names the file that ORE writes the progress log to. The progress log holds short messages in JSON that say how far a run has come, so a program can show progress. The name can hold a Boost pattern such as %N, which is the number of the file after a rotation. For example, my_log_progress_%N.json.', 'log_progress.json in the output path.', 'A file name or a path. ORE writes the file in the output path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9bc893f5-43fa-5d7c-9676-52a60654b356', 0, 'Logging', '', 'progressLogRotationSize', 'ore.xsd', '/ORE/Logging/Parameter[@name=''progressLogRotationSize'']', 4, 'integer', false, 'Progress log rotation size', 'The size in bytes at which the progress log starts a new file.', 'Sets the size a progress log file can grow to. When a file reaches it, ORE starts the next file. For example, 10485760 is 10 MiB. A value of 0 sets no limit.', '0. The size has no limit.', 'A whole number of bytes, for example 104857600 for 100 MiB.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e72e3da4-699e-514e-b772-e655e99923d3', 0, 'Logging', '', 'progressLogToConsole', 'ore.xsd', '/ORE/Logging/Parameter[@name=''progressLogToConsole'']', 5, 'boolean', false, 'Progress log to console', 'A flag. Y also writes the progress log to the console.', 'Decides whether ORE writes the progress log to the standard output as well as to its file. Use Yes when a program starts ORE and reads its output to show progress.', 'No. ORE writes the progress log to its file only.', 'A flag, written Y or N, or true or false.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9018fc10-2bba-52db-8b7c-b4fca07e4ae4', 0, 'Logging', '', 'structuredLogFile', 'ore.xsd', '/ORE/Logging/Parameter[@name=''structuredLogFile'']', 6, 'string', false, 'Structured log file', 'A file name for the structured log.', 'Names the file that ORE writes the structured log to. The structured log holds messages about the data of a run, for example a trade that failed to build, in a form a program can read. The name can hold a Boost pattern such as %N, which is the number of the file after a rotation. For example, my_structured_logs_%N.txt.', 'log_structured.json in the output path.', 'A file name or a path. ORE writes the file in the output path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7e0c4470-4f13-5a96-950b-212cfa4f6948', 0, 'Logging', '', 'structuredLogRotationSize', 'ore.xsd', '/ORE/Logging/Parameter[@name=''structuredLogRotationSize'']', 7, 'integer', false, 'Structured log rotation size', 'The size in bytes at which the structured log starts a new file.', 'Sets the size a structured log file can grow to. When a file reaches it, ORE starts the next file. For example, 10485760 is 10 MiB. A value of 0 sets no limit.', '0. The size has no limit.', 'A whole number of bytes, for example 104857600 for 100 MiB.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '02e206e5-6e28-5067-8fd1-c7585bc4d07e', 0, 'Markets', '', 'pricing', 'ore.xsd', '/ORE/Markets/Parameter[@name=''pricing'']', 1, 'string', false, 'Pricing market', 'A market configuration name.', 'Names the market configuration that prices the portfolio: the NPV, the cash flows and the pricing step of the other analytics. The configuration is defined in the today''s market file. For example, collateral_eur discounts with the curves of euro collateral.', 'default. ORE uses the configuration named default.', 'The name of a market configuration of the today''s market file, for example collateral_eur.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a1ea0961-4014-5af9-9a41-443fb58e528a', 0, 'Markets', '', 'simulation', 'ore.xsd', '/ORE/Markets/Parameter[@name=''simulation'']', 2, 'string', false, 'Simulation market', 'A market configuration name.', 'Names the market configuration that the simulation uses to project the market. A cross currency adjusted discount curve is the usual choice, because it prices FX products correctly. For example, collateral_eur.', 'default. ORE uses the configuration named default.', 'The name of a market configuration of the today''s market file, for example collateral_eur.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '54720cb1-c48f-5fb3-808a-647816272af9', 0, 'Markets', '', 'lgmcalibration', 'ore.xsd', '/ORE/Markets/Parameter[@name=''lgmcalibration'']', 3, 'string', false, 'Interest rate calibration market', 'A market configuration name.', 'Names the market configuration that calibrates the interest rate models of the simulation, the LGM models. Local OIS discounting is the usual choice. For example, collateral_inccy discounts each currency with its own OIS curve.', 'default. ORE uses the configuration named default.', 'The name of a market configuration of the today''s market file, for example collateral_eur.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '61fed4a4-4eb3-5461-bb27-22e069c440f9', 0, 'Markets', '', 'fxcalibration', 'ore.xsd', '/ORE/Markets/Parameter[@name=''fxcalibration'']', 4, 'string', false, 'FX calibration market', 'A market configuration name.', 'Names the market configuration that calibrates the FX models of the simulation. For example, collateral_eur.', 'default. ORE uses the configuration named default.', 'The name of a market configuration of the today''s market file, for example collateral_eur.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b2e3592c-c257-50da-96c2-dc1611f06446', 0, 'Markets', '', 'eqcalibration', 'ore.xsd', '/ORE/Markets/Parameter[@name=''eqcalibration'']', 5, 'string', false, 'Equity calibration market', 'A market configuration name.', 'Names the market configuration that calibrates the equity models of the simulation. For example, collateral_inccy.', 'default. ORE uses the configuration named default.', 'The name of a market configuration of the today''s market file, for example collateral_eur.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c5e4df26-9ce7-5977-9e74-f6b92febbac0', 0, 'Markets', '', 'infcalibration', 'ore.xsd', '/ORE/Markets/Parameter[@name=''infcalibration'']', 6, 'string', false, 'Inflation calibration market', 'A market configuration name.', 'Names the market configuration that calibrates the inflation models of the simulation. For example, collateral_inccy.', 'default. ORE uses the configuration named default.', 'The name of a market configuration of the today''s market file, for example collateral_eur.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '37c3ea19-3398-5a06-ac6f-148005f09a9e', 0, 'Markets', '', 'crcalibration', 'ore.xsd', '/ORE/Markets/Parameter[@name=''crcalibration'']', 7, 'string', false, 'Credit calibration market', 'A market configuration name.', 'Names the market configuration that calibrates the credit models of the simulation. For example, collateral_inccy.', 'default. ORE uses the configuration named default.', 'The name of a market configuration of the today''s market file, for example collateral_eur.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1dc4ff30-ff80-5302-ab5e-65cb29d21399', 0, 'Markets', '', 'sensitivity', 'ore.xsd', '/ORE/Markets/Parameter[@name=''sensitivity'']', 8, 'string', false, 'Sensitivity market', 'A market configuration name.', 'Names the market configuration that the sensitivity analysis uses to build the market it shifts. For example, collateral_eur.', 'default. ORE uses the configuration named default.', 'The name of a market configuration of the today''s market file, for example collateral_eur.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '942915fc-b580-5a9c-bbce-40b3b3b69a6b', 0, 'Markets', '', 'bondpricing', 'ore.xsd', '/ORE/Markets/Parameter[@name=''bondpricing'']', 9, 'string', false, 'Bond pricing market', 'A market configuration name. No release of ORE reads it.', 'No release of the ORE sources reads this parameter. Some example documents carry it to pick a market configuration for bonds. ORE ignores it, so bonds use the pricing market. Do not rely on it.', 'None. ORE ignores the parameter.', 'The name of a market configuration of the today''s market file, for example collateral_eur.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f22ba43f-2f0a-5c2c-a842-8f88d84d6057', 0, 'analytic', 'npv', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npv'']/Parameter[@name=''active'']', 1, 'boolean', true, 'Run the NPV analytic', 'A flag. Y runs the analytic.', 'Switches the NPV analytic on or off. When it is on, the run prices every trade of the portfolio at the valuation date and writes the NPV of each trade to the NPV report. Use N to keep the entry in the document without running it. Every analytic has this parameter.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd4af937e-6ac0-5bde-813e-a4abc0d6f86b', 0, 'analytic', 'npv', 'baseCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npv'']/Parameter[@name=''baseCurrency'']', 2, 'string', false, 'Base currency', 'A currency code, for example EUR.', 'Names the currency in which the NPV report states every NPV. ORE converts the NPV of a trade in another currency at the spot rate of the valuation date. The Setup block has a parameter of the same name, and ORE reads that one first. This parameter is the older place for the same choice and ORE reads it only when the Setup block has none. For example, EUR states all NPVs in euro.', 'The base currency of the Setup block. When that is also missing, the currency of the discounting index.', 'A currency code of three letters, for example EUR.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a5572cd7-0cdc-56ca-88e7-ec4be1ae4f73', 0, 'analytic', 'npv', 'outputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npv'']/Parameter[@name=''outputFileName'']', 3, 'string', false, 'NPV report file', 'A file name.', 'Names the file that holds the NPV report: one row for each trade with its NPV, its currency and its NPV in the base currency. Change it when one run writes several reports and you need to tell the files apart. For example, npv.csv writes the report to npv.csv in the output path.', 'npv.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a9d8e5b5-89b9-5030-a38e-3a4a8c000805', 0, 'analytic', 'npv', 'extendedResults', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npv'']/Parameter[@name=''extendedResults'']', 4, 'boolean', false, 'Extended results', 'A flag. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it with the value N, so it appears in many run documents. Leave it as the document has it, because a value has no effect on the run. To get more output from the NPV analytic, use Write additional results.', 'No. ORE ignores the parameter, so nothing changes with either value.', 'A flag, written Y or N, or true or false.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1392e22d-7b53-542e-88a4-edf575f3c1f1', 0, 'analytic', 'npv', 'additionalResults', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npv'']/Parameter[@name=''additionalResults'']', 5, 'boolean', false, 'Write additional results', 'A flag. Y writes the report.', 'Decides whether the run writes the additional results of the pricing engines. These are values that an engine computes on the way to the NPV, for example the annuity, the forward rate and the standard deviation of a swaption. Switch it on to check how an engine reached an NPV. This is the older place for the choice. The newer way is the additional results analytic with its own Active parameter, and ORE reads this parameter only when that analytic does not set it.', 'No. The run does not write the additional results.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5db1707a-30f4-586f-ae9f-8b81e303fa95', 0, 'analytic', 'npv', 'additionalResultsReportPrecision', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npv'']/Parameter[@name=''additionalResultsReportPrecision'']', 6, 'integer', false, 'Additional results precision', 'A whole number of decimal places.', 'Sets the number of decimal places of the numbers in the additional results report. A higher value shows more of each result and makes the file larger. For example, 12 writes a result such as 0.016641350123. This is the older place for the choice. The additional results analytic has a parameter of the same name, and ORE reads this one only when that analytic does not set it.', '6', 'A whole number of zero or more.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b8b7ee2c-b081-5070-9613-833bd35dcf49', 0, 'analytic', 'npv', 'outputCurves', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npv'']/Parameter[@name=''outputCurves'']', 7, 'boolean', false, 'Write curves with the NPV', 'A flag. Y also runs the curves analytic.', 'Is an older way to switch on the curves report from inside the NPV analytic. When it is Y, the run writes the yield curves as the curves analytic does. ORE reads it only when the curves analytic is not active. For a new document, set Active in the curves analytic instead.', 'No. The NPV analytic does not write the curves report.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd26d6185-6af3-51a7-b5a2-e6ce7962b7c1', 0, 'analytic', 'npv', 'nameMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npv'']/Parameter[@name=''nameMappingInputFile'']', 8, 'string', false, 'Name mapping file', 'A file name.', 'Names the file that maps the names in the portfolio to the names that the CRIF report uses. The CRIF report needs this mapping. ORE reads the file name from the first of these blocks that has one: crif, saccr, simm, npv and Setup. This is the fourth place. The Setup block is the best place, because it serves all of the analytics.', 'None. When no block names a file, ORE uses the names as they are.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c6d9335a-2bb3-5d23-9581-b1bd2f5ddac7', 0, 'analytic', 'npv', 'bucketMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npv'']/Parameter[@name=''bucketMappingInputFile'']', 9, 'string', false, 'Bucket mapping file', 'A file name.', 'Names the file that maps risk factors to the SIMM buckets of the CRIF report. ORE reads the file name from the first of these blocks that has one: crif, saccr, simm, npv and Setup. This is the fourth place. The Setup block is the best place, because it serves all of the analytics.', 'None. When no block names a file, ORE uses the standard SIMM buckets.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c2e6d188-797d-51b4-8312-43823b2a645b', 0, 'analytic', 'cashflow', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''cashflow'']/Parameter[@name=''active'']', 10, 'boolean', true, 'Run the cash flow analytic', 'A flag. Y runs the analytic.', 'Switches the cash flow analytic on or off. When it is on, the run writes a report with every future cash flow of every trade: the pay date, the amount, the currency, the coupon, the accrual and the fixing. Use it to check the cash flows that sit behind an NPV.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b0a6c57a-c086-5502-b534-71d36b0d62f8', 0, 'analytic', 'cashflow', 'outputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''cashflow'']/Parameter[@name=''outputFileName'']', 11, 'string', false, 'Cash flow report file', 'A file name.', 'Names the file that holds the cash flow report: one row for each cash flow with the trade, the pay date, the amount, the currency and the flow type. Change it when one run writes several reports and you need to tell the files apart. For example, flows.csv writes the report to flows.csv in the output path. The default is cashflow.csv.', 'cashflow.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7c35df9d-fdb1-5801-bb96-ed9f108b21de', 0, 'analytic', 'cashflow', 'includePastCashflows', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''cashflow'']/Parameter[@name=''includePastCashflows'']', 12, 'boolean', false, 'Include past cash flows', 'A flag. Y adds the cash flows before the valuation date.', 'Decides whether the report also lists cash flows with a pay date before the valuation date. Past cash flows are useful to check fixings and accruals of the current period. They make the report longer. This is the older place for the choice. The Setup block has a parameter of the same name, and ORE reads that one first.', 'No. The report lists only the cash flows from the valuation date on.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '016a3dd7-8d0c-53a7-a828-4232ef28bc59', 0, 'analytic', 'cashflow', 'cashFlowHorizon', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''cashflow'']/Parameter[@name=''cashFlowHorizon'']', 13, 'date', false, 'Cash flow horizon', 'A date.', 'Sets the last pay date that the cash flow NPV analytic counts. The analytic adds up the present value of the cash flows of each trade that pay after the valuation date and on or before this date. Use it to see how much of an NPV falls due in the near term. For example, 2027-12-31 counts the cash flows up to the end of 2027. The cash flow NPV analytic has a parameter of the same name.', 'None. Without a horizon the analytic counts no cash flow, so every present value is 0.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'da232b3e-61e3-5b33-867a-fb29622fd0c7', 0, 'analytic', 'cashflow', 'portfolioFilterDate', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''cashflow'']/Parameter[@name=''portfolioFilterDate'']', 14, 'date', false, 'Portfolio filter date', 'A date.', 'Sets the date that decides which trades the run keeps. ORE removes every trade that matures before this date. This applies to all analytics of the run, not only to the cash flow analytic. For example, 2027-01-01 removes all trades that mature before the start of 2027.', 'The valuation date. ORE removes the trades that have matured.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f94cb57b-9b05-524d-9012-8c2d96993357', 0, 'analytic', 'curves', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''curves'']/Parameter[@name=''active'']', 15, 'boolean', true, 'Run the curves analytic', 'A flag. Y runs the analytic.', 'Switches the curves analytic on or off. When it is on, the run exports the discount factors of the yield curves that it builds from the market data, as set in the todaysmarket file, on the dates of the grid. Use it to check the curves behind an NPV, or to hand the curves to another system. Use N to keep the entry in the document without running it.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ac1de680-08af-5600-a7c9-06e9cf10d546', 0, 'analytic', 'curves', 'configuration', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''curves'']/Parameter[@name=''configuration'']', 16, 'string', false, 'Market configuration', 'The name of a market configuration.', 'Selects the set of curves that the analytic exports. The todaysmarket file groups the curves in named configurations, for example one for discounting with collateral in euro and one for discounting in the local currency of each trade, and this parameter picks one. For example, default exports the curves of the default configuration. The name must exist in the todaysmarket file.', 'default', 'The name of a configuration in the todaysmarket file.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1db696ad-2717-5c6c-aa00-f29d53745bec', 0, 'analytic', 'curves', 'grid', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''curves'']/Parameter[@name=''grid'']', 17, 'string', false, 'Time grid', 'A number of steps and a step length, or a list of tenors.', 'Sets the dates at which the analytic exports the discount factors. Write it as a number of steps followed by the length of a step, or as a list of tenors. ORE builds the grid from the valuation date and rolls it with the calendar of this analytic. For example, 240,1M gives 240 monthly steps from the valuation date, and 1W,1M,2M,3M gives the four dates one week, one month, two months and three months out.', '240,1M. That is 240 monthly steps, 20 years.', 'Either a number of steps, a comma and a period such as 1M, or a comma-separated list of periods.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8e12773e-d0b4-577d-855d-0f0d9bd97a60', 0, 'analytic', 'curves', 'outputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''curves'']/Parameter[@name=''outputFileName'']', 18, 'string', false, 'Curves report file', 'A file name.', 'Names the file that holds the exported discount factors. The file has one row for each date of the grid and one column for each curve. Change it when one run writes several reports and you need to tell the files apart. For example, curves.csv writes the report to curves.csv in the output path.', 'curves.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b2c7f47b-fcc6-5b53-8456-525cdeaf3412', 0, 'analytic', 'curves', 'outputTodaysMarketCalibration', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''curves'']/Parameter[@name=''outputTodaysMarketCalibration'']', 19, 'boolean', false, 'Write the market calibration report', 'A flag. Y writes the calibration report.', 'Decides whether the run also writes a report on how it built the market objects of the valuation date. The report shows the calibration of each curve and surface. Switch it on to find out why a curve has the shape it has, or to find a build that failed.', 'No. The run does not write the calibration report.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b6e46924-cf4a-5fb3-9a7a-bcea2cd40a3a', 0, 'analytic', 'curves', 'calendar', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''curves'']/Parameter[@name=''calendar'']', 20, 'string', false, 'Grid calendar', 'A calendar name.', 'Names the calendar that ORE uses to roll the dates of the grid to business days. Change it when the curves belong to a market with other holidays than the euro area. For example, UK rolls the grid dates to business days of the United Kingdom.', 'TARGET', 'A calendar name such as TARGET or UK.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b61c50ad-8834-50b0-bfe8-90fb05bc5e7e', 0, 'analytic', 'curves', 'todaysMarketCalibrationPrecision', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''curves'']/Parameter[@name=''todaysMarketCalibrationPrecision'']', 21, 'integer', false, 'Calibration report precision', 'A whole number of decimal places.', 'Sets the number of decimal places of the numbers in the market calibration report. A higher value shows more of each number and makes the file larger. It has an effect only when the market calibration report is on. The NPV analytic has a similar parameter for its additional results.', '8', 'A whole number of zero or more.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '09130e10-5bb1-554a-8210-56a54d2e2b52', 0, 'analytic', 'simulation', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''active'']', 22, 'boolean', true, 'Run the exposure simulation', 'A flag. Y runs the simulation.', 'Switches the exposure simulation on or off. When it is on, the run evolves the market with a Monte Carlo simulation and values every trade of the portfolio at each date of the simulation grid on each path. The result is an NPV cube. The XVA, PFE and other exposure analytics use this cube. Use N to keep the entry in the document without running it.', 'No. The simulation does not run.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '78a1fadc-d190-51fa-b5ad-1d24edd2c131', 0, 'analytic', 'simulation', 'amc', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amc'']', 23, 'boolean', false, 'Use American Monte Carlo', 'A flag. Y uses American Monte Carlo for the trade types listed.', 'Decides whether ORE values some trade types with American Monte Carlo (AMC) instead of the classic simulation. AMC regresses the trade value on the simulated state and is much faster for products with early exercise. The parameter AMC trade types lists the trade types that AMC covers. The classic simulation values the other trades, and ORE joins the two cubes.', 'No. The classic simulation values all trades.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e2b990a5-e514-5fd5-bd92-5db276571942', 0, 'analytic', 'simulation', 'amcTradeTypes', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcTradeTypes'']', 24, 'string', false, 'AMC trade types', 'A comma-separated list of trade types.', 'Lists the trade types that ORE values with American Monte Carlo when AMC is on. The allowed types are Swap, Swaption, FxForward, FxOption, ForwardBond, FxTaRF, ScriptedTrade and CompositeTrade. The classic simulation values every other trade of the portfolio. For example, Swap,Swaption,FxOption.', 'None. With AMC on and no list, no trade type is covered by AMC.', 'A comma-separated list of trade type names.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fb34dbb8-3130-5136-8cb8-556eb5c7a7f5', 0, 'analytic', 'simulation', 'simulationConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''simulationConfigFile'']', 25, 'string', false, 'Simulation configuration file', 'A file name.', 'Names the XML file that sets up the simulation. The file holds three things: the simulated market (which curves, volatilities and rates evolve), the model (the cross asset model and its calibration) and the scenario generator (the date grid, the number of samples and the random number generator). ORE reads all three from this one file, unless the parameters Cross asset model data or Scenario generator data name another file. For example, simulation.xml.', 'None. The simulation needs this file, so a run without it fails.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f096156e-57c8-5d3f-aee5-d51fcc23228b', 0, 'analytic', 'simulation', 'pricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''pricingEnginesFile'']', 26, 'string', false, 'Pricing engines file for the simulation', 'A file name.', 'Names the XML file that sets the pricing engines for the valuations on the simulated scenarios. These can differ from the engines of the valuation date, for example faster approximations, because the simulation values every trade on every date and path. The cost of an engine matters much more here than in the NPV run. For example, pricingengine.xml.', 'The pricing engines file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '07d98682-9520-525c-9682-f148676777a4', 0, 'analytic', 'simulation', 'amcPricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcPricingEnginesFile'']', 27, 'string', false, 'Pricing engines file for AMC', 'A file name.', 'Names the XML file that sets the pricing engines for the trades that American Monte Carlo (AMC) values. These engines differ from the classic ones, because they are the AMC pricers: they value a trade on the simulated paths with a regression and not with a full revaluation on each path. A trade type that this file does not cover stays with the classic engine. For example, pricingengine_amc.xml.', 'The pricing engines file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4d1836fe-6f47-5270-ab25-d5654320fc59', 0, 'analytic', 'simulation', 'baseCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''baseCurrency'']', 28, 'string', false, 'Base currency for the cube', 'A currency code, for example EUR.', 'Names the currency in which ORE converts all NPVs before it writes them to the trade-level cube and the netting set cube. Exposures and XVA are then stated in this currency. Choose the currency of the reports that you will produce, because the cube cannot change it later. For example, EUR stores all cube values in euro. The Setup block has a parameter of the same name.', 'The base currency of the Setup block.', 'A currency code of three letters, for example EUR.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6e50b6e5-6631-5503-b4e7-75bf40aa0820', 0, 'analytic', 'simulation', 'storeScenarios', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''storeScenarios'']', 29, 'boolean', false, 'Store scenarios', 'A flag. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it with the value N. To write the scenarios, use Scenario dump file or Write scenarios.', 'No. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f0560ea0-2ff7-53c3-8ffd-5e12fd441531', 0, 'analytic', 'simulation', 'cubeFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''cubeFile'']', 30, 'string', false, 'Cube file', 'A file name.', 'Names the file that holds the NPV cube of the simulation: the value of every trade on every date and every path. Setting it also switches the cube output on. The XVA and PFE analytics can read the file back with their own Cube file parameter, so a later run does not need to simulate again. Example files use cube.csv.gz and cube.dat.', 'None. When Write cube is on, the name is cube.csv.gz.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e17da9d9-7972-565a-aff9-6b755c5b286b', 0, 'analytic', 'simulation', 'aggregationScenarioDataFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''aggregationScenarioDataFileName'']', 31, 'string', false, 'Aggregation scenario data file', 'A file name.', 'Names the file that holds the market data that the XVA post processing needs, for example the simulated FX rates and index fixings that the variation margin calculation uses. The simulation configuration file lists the data to store. For example, scenariodata.csv.gz.', 'None. When Write cube is on, the name is scenariodata.csv.gz.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a64d034c-8017-5d1d-82fc-555430d60de5', 0, 'analytic', 'simulation', 'aggregationScenarioDataDump', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''aggregationScenarioDataDump'']', 32, 'string', false, 'Aggregation scenario data dump', 'A file name. ORE no longer reads it.', 'Named a CSV file for a dump of the aggregation scenario data. ORE stopped reading it in 1.8.9.1. Use Aggregation scenario data file to name the file that holds this data.', 'None. ORE ignores the parameter.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.3.0', '1.8.9.1'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2aa2cb13-732f-577f-8134-0d1f74bb538f', 0, 'analytic', 'simulation', 'allowPartialScenarios', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''allowPartialScenarios'']', 33, 'boolean', false, 'Allow partial scenarios', 'A flag. Y accepts scenarios that touch only part of the market.', 'Decides whether the simulated market accepts scenarios that do not set every risk factor of the simulation market. When it is N, ORE checks that each scenario covers all of the market and stops if a risk factor is missing. Switch it on when you read scenarios from a file that covers only part of the market.', 'No. ORE checks that scenarios cover the whole market.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a47640b1-6263-5c27-8aa8-634484d14917', 0, 'analytic', 'simulation', 'scenariodump', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''scenariodump'']', 34, 'string', false, 'Scenario dump file', 'A file name.', 'Names the file that receives the raw market scenarios of the simulation: the discount factors of the yield curves and the other simulated values, for each date and path. Setting it also switches the output on. Use it to inspect the scenarios or to feed them to another tool. Filter risk keys limits the content. For example, scenariodump.csv.', 'None. When Write scenarios is on, the name is scenario.csv.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6a9075ed-bed0-5b38-9b77-12ed03315c85', 0, 'analytic', 'simulation', 'amcCg', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcCg'']', 35, 'string', false, 'Computation graph engine mode', 'One of Disabled, CubeGeneration or Full.', 'Selects the use of the computation graph (CG) engine for AMC. Disabled keeps the normal AMC. CubeGeneration builds the NPV cube with the CG engine and leaves the XVA post processing to the normal code. Full also computes the XVA with the CG engine. The CG engine allows sensitivities by algorithmic differentiation and dynamic initial margin.', 'Disabled', 'One of Disabled, CubeGeneration or Full.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9112e377-f622-5d41-8f6d-717b24d38fb5', 0, 'analytic', 'simulation', 'xvaCgUseExternalComputeDevice', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgUseExternalComputeDevice'']', 36, 'boolean', false, 'CG use an external compute device', 'A flag. Y runs the graph on an external device.', 'Decides whether the CG engine runs the computation graph on an external compute device, for example a GPU, instead of the CPU. A device pays off for a graph that is evaluated on many paths. The parameter CG external compute device names the device. The default is No, so the engine runs on the CPU.', 'No. The engine runs on the CPU.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2813aeb2-3fde-5a98-9aa8-b170b529fcba', 0, 'analytic', 'simulation', 'xvaCgExternalDeviceCompatibilityMode', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgExternalDeviceCompatibilityMode'']', 37, 'boolean', false, 'CG device compatibility mode', 'A flag. Y uses the compatibility mode.', 'Decides whether the CG engine runs the external device in its compatibility mode. Switch it on when the device does not run the normal mode correctly, for example when a driver rejects the kernels of the normal mode. The compatibility mode can be slower. Example files set it together with the name of the device.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fb69a607-7603-5759-97a8-d72fd155794d', 0, 'analytic', 'simulation', 'xvaCgUseDoublePrecisionForExternalCalculation', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgUseDoublePrecisionForExternalCalculation'']', 38, 'boolean', false, 'CG double precision on the device', 'A flag. Y uses double precision.', 'Decides whether the external device calculates with double precision numbers instead of single precision. Double precision is more exact and slower, and some devices do not support it. Single precision is enough for many exposure profiles, and double precision is the safe choice when you compare results with a CPU run. ORE uses it only when the CG engine uses an external device.', 'No. The device uses single precision.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ee71560e-825e-52e0-8bec-cb5595408402', 0, 'analytic', 'simulation', 'xvaCgExternalComputeDevice', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgExternalComputeDevice'']', 39, 'string', false, 'CG external compute device', 'The name of a compute device.', 'Names the device that the CG engine uses when it runs on an external compute device. The name has the form framework, vendor and device, separated by slashes. For example, OpenCL/Apple/Apple M2 Max, or BasicCpu/Default/Default for a plain CPU back end.', 'None. Without a name, ORE uses no external device.', 'Three names separated by slashes, for example OpenCL/Apple/Apple M2 Max.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd4bc2d13-a393-5131-a4f7-aa222c044422', 0, 'analytic', 'simulation', 'amcCgPricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcCgPricingEnginesFile'']', 40, 'string', false, 'Pricing engines file for the CG engine', 'A file name.', 'Names the XML file that sets the pricing engines for the computation graph (CG) engine. The CG engine builds a graph of the calculation of each trade and then evaluates it on all paths, so it needs engines that can produce such a graph. A trade type without such an engine cannot run in the CG engine. For example, pricingengine_amccg.xml.', 'The pricing engines file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7beffa24-5591-5893-ae6b-b157d8b5cd86', 0, 'analytic', 'simulation', 'xvaCgDynamicIM', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgDynamicIM'']', 41, 'boolean', false, 'CG dynamic initial margin', 'A flag. Y computes dynamic initial margin with the CG engine.', 'Decides whether the CG engine also computes the initial margin along each path. The DIM model DynamicIM of the XVA analytic needs this, because that model reads the margin from the CG run. It makes the run longer and the memory use higher. Leave it off when the XVA analytic uses another DIM model or does not compute MVA.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c956bd2e-994f-5e22-88a1-22695404b4bd', 0, 'analytic', 'simulation', 'xvaCgDynamicIMStepSize', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgDynamicIMStepSize'']', 42, 'integer', false, 'CG dynamic IM step size', 'A whole number of time steps.', 'Sets how often the CG engine computes dynamic initial margin: on every n-th time step of the grid. A value of 1 computes it on every step. With a larger value the run is faster, and ORE copies the margin of the last computed step to the steps in between. For example, 4 computes it on every fourth step.', '1', 'A whole number of one or more.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '45573019-6997-54a4-8895-2f156d197fed', 0, 'analytic', 'simulation', 'xvaCgRegressionOrder', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgRegressionOrder'']', 43, 'integer', false, 'CG regression order', 'A whole number.', 'Sets the order of the polynomial that the CG engine uses in the regression for the exposures. A higher order fits the value of a trade better on each date and needs more paths to stay stable, because the fit has more coefficients. The default is 4. For example, 2 gives a quadratic fit that is steady with few paths. Raise it for trades with a strong non-linear payoff.', '4', 'A whole number of one or more.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '486fb243-538e-5499-b5ea-90cdcaa9e834', 0, 'analytic', 'simulation', 'xvaCgRegressionOrderDynamicIm', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgRegressionOrderDynamicIm'']', 44, 'integer', false, 'CG regression order for dynamic IM', 'A whole number.', 'Sets the order of the regression polynomial that the CG engine uses for dynamic initial margin. It works like the CG regression order and applies to the margin only, so you can fit the margin with another order than the exposure. The default is 4. A lower order is steadier with few paths, and a higher order follows a non-linear margin better.', '4', 'A whole number of one or more.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1719fa70-81f9-5303-a320-e5ee04efa2fe', 0, 'analytic', 'simulation', 'xvaCgTradeLevelBreakDown', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgTradeLevelBreakDown'']', 45, 'boolean', false, 'CG trade level breakdown', 'A flag. Y keeps the results for each trade.', 'Decides whether the CG engine produces the exposure results for each trade as well as for each netting set. The default is Yes. Switch it off when you need only the netting set results, because the trade level results take memory and time for a large portfolio. Reports that need the trade level, such as the allocation of the XVA to trades, then have no data.', 'Yes. The engine keeps the results for each trade.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e5ca8997-bf9f-5442-b7cc-46a561deaa78', 0, 'analytic', 'simulation', 'xvaCgUseRedBlocks', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgUseRedBlocks'']', 46, 'boolean', false, 'CG use red blocks', 'A flag. Y uses red blocks.', 'Decides whether the CG engine puts the part of the graph that belongs to one trade into a red block while it builds the graph. It is on by default. Switch it off to build the graph without red blocks, for example to check a result.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ccce0269-8f7f-5f59-9d05-2405dfea67d2', 0, 'analytic', 'simulation', 'storeFlows', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''storeFlows'']', 47, 'boolean', false, 'Store cash flows in the cube', 'A flag. Y stores the cash flows.', 'Decides whether the cube also stores the cumulative cash flows between the simulation dates. Some dynamic initial margin and variation margin models need them in the XVA post processing, because the exposure depends on the cash that a trade pays between two dates. The cube gets larger when this is on. Leave it off when no model of the run needs the flows.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8eda576f-226d-56b4-83f4-0f42c90ddc8d', 0, 'analytic', 'simulation', 'storeSensis', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''storeSensis'']', 48, 'boolean', false, 'Store sensitivities along the paths', 'A flag. Y stores the sensitivities.', 'Decides whether the simulation stores the analytical sensitivities of the trades along each path, in the netting set cube. Some dynamic initial margin models need them. The parameters Curve sensitivity grid and Vega sensitivity grid set the points. The run stops if it stores sensitivities and neither grid is set.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7c6af8bb-acd7-5214-86a5-8f6d38d9dcd4', 0, 'analytic', 'simulation', 'curveSensiGrid', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''curveSensiGrid'']', 49, 'string', false, 'Curve sensitivity grid', 'A comma-separated list of numbers of years.', 'Lists the points on the yield curves for which the simulation stores sensitivities when Store sensitivities along the paths is on. Each number is a tenor in years. For example, 1,2,3,5,7,10,15,20 stores the sensitivity to eight points of each curve. More points give a finer hedge and a larger cube.', 'None.', 'A comma-separated list of numbers of years, for example 1,2,3,5,7,10.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5c0b287a-2c70-5722-ac62-c192f84d3c2d', 0, 'analytic', 'simulation', 'vegaSensiGrid', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''vegaSensiGrid'']', 50, 'string', false, 'Vega sensitivity grid', 'A comma-separated list of numbers of years.', 'Lists the option expiries for which the simulation stores vega sensitivities when Store sensitivities along the paths is on. Each number is an expiry in years. For example, 1,2,3,5,7,10,15,20 stores the vega at eight expiries. More points give a finer hedge and a larger cube.', 'None.', 'A comma-separated list of numbers of years, for example 1,2,3,5,7,10.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4214e5fa-62aa-52c6-b20c-9fd9883755f2', 0, 'analytic', 'simulation', 'storeSurvivalProbabilities', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''storeSurvivalProbabilities'']', 51, 'boolean', false, 'Store survival probabilities', 'A flag. Y stores the survival probabilities.', 'Decides whether the cube stores the survival probabilities of the counterparties on each simulation date. The dynamic credit XVA calculation needs them, because the default probability then changes along the path. The cube gets larger when this is on. Leave it off when the credit curves are static.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '606b273a-025d-5af7-996e-8848cebf66e4', 0, 'analytic', 'simulation', 'simulationModelFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''simulationModelFile'']', 52, 'string', false, 'Simulation model file', 'A file name. ORE ignores it.', 'ORE does not read this parameter in any release. Example files of an older layout carry it. ORE reads the model from the simulation configuration file.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0488505a-522d-5dab-900c-2db7bc798dcc', 0, 'analytic', 'simulation', 'simulationMarketFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''simulationMarketFile'']', 53, 'string', false, 'Simulation market file', 'A file name. ORE ignores it.', 'ORE does not read this parameter in any release. Example files of an older layout carry it. ORE reads the simulated market from the simulation configuration file.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '231edb99-5efb-5f45-a901-5d1b14a77b83', 0, 'analytic', 'simulation', 'simulationParamFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''simulationParamFile'']', 54, 'string', false, 'Simulation parameter file', 'A file name. ORE ignores it.', 'ORE does not read this parameter in any release. Example files of an older layout carry it. ORE reads the scenario generator from the simulation configuration file.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e452ea5d-501d-5e66-baab-8a5ee2218f16', 0, 'analytic', 'simulation', 'computeCube', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''computeCube'']', 55, 'boolean', false, 'Compute the cube', 'A flag. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it with the value Y. The simulation always computes the cube when it runs.', 'Yes. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '29298c1e-1593-5a3c-9ad1-b4b195b22da0', 0, 'analytic', 'simulation', 'additionalScenarioDataFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''additionalScenarioDataFileName'']', 56, 'string', false, 'Additional scenario data file', 'A file name. ORE no longer reads it.', 'Named the file for the additional market data of the simulation. ORE stopped reading it in 1.8.3.0. Use Aggregation scenario data file to name the file that holds this data.', 'None. ORE ignores the parameter.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', '1.8.3.0'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b940a74c-6def-5c69-9247-5803fce39cfa', 0, 'analytic', 'simulation', 'storeCreditStateNPVs', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''storeCreditStateNPVs'']', 57, 'integer', false, 'Store NPVs by credit state', 'A whole number of credit states.', 'Sets the number of credit states for which the cube also stores the NPV of each trade. A value of zero stores none. The credit migration and the dynamic credit XVA calculations need these values. For example, 8 stores the NPV for 8 credit states.', '0. The cube stores no NPVs by credit state.', 'A whole number of zero or more.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f1f946f1-8f93-5a6b-91b7-395cfce2b77b', 0, 'analytic', 'simulation', 'observationModel', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''observationModel'']', 58, 'string', false, 'Observation model for the simulation', 'The name of an observation model, for example Disable.', 'Controls how many QuantLib observer notifications the simulation uses when market data and fixings are updated and when the evaluation date moves along a path. Notifications cost time in a simulation. None is the normal QuantLib behaviour. Disable switches the notifications off and lets the engine trigger the recalculations. Defer holds the updates back until notifications are on again. Unregister keeps notifications on but unregisters floating rate coupons from their indices. Disable and Unregister give a similar speed up. The Setup block has a parameter of the same name, and this one overrides it for the simulation.', 'The observation model of the Setup block, which is None by default.', 'One of None, Disable, Defer or Unregister.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '57c4fbc1-194b-50a1-82c4-fb7a93f68c37', 0, 'analytic', 'simulation', 'includeTodaysCashFlows', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''includeTodaysCashFlows'']', 59, 'boolean', false, 'Include today''s cash flows in the simulation', 'A flag. Y counts the cash flows of the valuation date.', 'Decides whether the simulation counts a cash flow that pays on the valuation date itself, or treats it as matured. Set it to Y when a payment of the day must be part of the exposure. The Setup block has a parameter of the same name, and this one overrides it for the simulation.', 'The choice of the Setup block. When that is missing too, No: a cash flow of the valuation date is treated as matured.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1fbe2dba-43eb-5d4c-b0ac-c7a26cfc24d2', 0, 'analytic', 'simulation', 'filterRiskKeys', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''filterRiskKeys'']', 60, 'string', false, 'Risk factor types in the dump', 'A comma-separated list of risk factor types.', 'Limits the scenario dump to the listed types of risk factor. Without it the dump holds every risk factor of the simulation market and can be very large. Write the types as a comma-separated list. For example, DiscountCurve writes the discount factors only, and DiscountCurve,FXSpot adds the spot rates of the currencies.', 'None. The dump holds all risk factors.', 'A comma-separated list of risk factor key types such as DiscountCurve.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '64ec6abd-087b-5420-b6fd-011f1ff6761b', 0, 'analytic', 'simulation', 'xvaCgSensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgSensitivityConfigFile'']', 61, 'string', false, 'CG sensitivity configuration file', 'A file name.', 'Names the XML file that sets which sensitivities the CG engine computes: the risk factors and the shifts. The CG engine computes the sensitivities from the graph, so the cost of each extra risk factor is small. Without the file the CG engine computes no sensitivities. For example, xvasensiconfig.xml. The file has the layout of the sensitivity configuration file.', 'None. The CG engine computes no sensitivities.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '631c6143-e0d3-5e00-831d-93697309fd27', 0, 'analytic', 'simulation', 'xvaCgBumpSensis', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgBumpSensis'']', 62, 'boolean', false, 'CG bump and revalue sensitivities', 'A flag. Y bumps and revalues instead of using differentiation.', 'Decides how the CG engine computes the CVA sensitivities. When it is Y, the engine bumps each risk factor and revalues, which is slow and easy to check. When it is N, the engine uses algorithmic differentiation, which is fast and gives all sensitivities in one pass. Use Y to check the differentiated sensitivities against bumped ones.', 'No. The engine uses algorithmic differentiation.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c2df247f-3e58-54e7-ad3f-027ee44c574d', 0, 'analytic', 'simulation', 'xvaCgRegressionCacheSize', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgRegressionCacheSize'']', 63, 'integer', false, 'CG regression cache size', 'A whole number.', 'Sets the size of the cache of regression results that the CG engine uses. A larger cache can save repeated regressions when many trades share the same regressors, and it uses more memory. The default is 512. Lower it on a machine with little memory, and raise it for a large portfolio with many similar trades.', '512', 'A whole number of one or more.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f1ceadb9-a43b-5042-bf43-37ceaf606dab', 0, 'analytic', 'simulation', 'disableEvaluationDateObservation', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''disableEvaluationDateObservation'']', 64, 'boolean', false, 'Disable evaluation date observation', 'A flag. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it with the value Y. To reduce the cost of notifications, use the observation model.', 'None. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6730c874-f8b6-5100-8377-73c37f4118d4', 0, 'analytic', 'simulation', 'scenarioFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''scenarioFile'']', 65, 'string', false, 'Scenario input file', 'A file name.', 'Names a file with ready-made market scenarios. When it is set, the simulation reads its scenarios from the file and does not generate them with the model. Use it to value a portfolio on scenarios that an earlier run wrote. For example, ../Output/scenarios.csv.', 'None. The simulation generates its own scenarios.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd7aff2ba-ec3d-5e88-ade7-97d1c5b243e6', 0, 'analytic', 'simulation', 'amcPathDataOutput', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcPathDataOutput'']', 66, 'string', false, 'AMC path data output file', 'A file name.', 'Names the file that receives the path data of the AMC run, that is the simulated states of the model on each path and date. A later run can read the file with the AMC path data input parameter and so skip the simulation. Use it when you run the same simulation for several portfolios. For example, amcBuffer.dat writes the data to amcBuffer.dat in the output path.', 'None. The run does not write the path data.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '423320e5-b613-527d-be60-d2cb2c7a3644', 0, 'analytic', 'simulation', 'amcIndividualTrainingOutput', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcIndividualTrainingOutput'']', 67, 'boolean', false, 'AMC individual training output', 'A flag. Y writes the trained regression of each trade.', 'Decides whether the AMC run writes the trained regression of each trade to a file, so that a later run can reuse it. Training is the costly step of AMC, so reuse saves time when the same trades are valued again on the same paths. The files take disk space for each trade. Switch it on for a stable portfolio that runs every day.', 'No. The run does not write the regressions.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7c3168bd-1106-5524-9a74-9bedb05f5d29', 0, 'analytic', 'simulation', 'amcIndividualTrainingInput', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcIndividualTrainingInput'']', 68, 'boolean', false, 'AMC individual training input', 'A flag. ORE does not read this setting from the simulation block.', 'Is meant to make the AMC run read the trained regression of each trade from a file. ORE reads the parameter from a block with the wrong name, xsimulationva, so a value in the simulation block has no effect in release 1.8.17.0.', 'No. The value in the simulation block has no effect.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8c5dd208-e222-5426-93b8-67687a0450e9', 0, 'analytic', 'simulation', 'includeReferenceDateEvents', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''includeReferenceDateEvents'']', 69, 'boolean', false, 'Include reference date events in the simulation', 'A flag. Y counts the events of the valuation date.', 'Decides whether the simulation counts an event that falls on the valuation date, for example an exercise, a fixing or a payment. The Setup block has a parameter of the same name, and this one overrides it for the simulation. Use it when the exposure on the first date must agree with the NPV, because the two must treat the same-day cash flow in the same way.', 'The choice of the Setup block. When that is missing too, No: an event of the valuation date is treated as matured.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd2305ef3-386a-5293-9066-152d9bcb12a0', 0, 'analytic', 'simulation', 'xvaCgRegressionReportTimeStepsDynamicIM', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgRegressionReportTimeStepsDynamicIM'']', 70, 'string', false, 'CG regression report time steps', 'A comma-separated list of time step numbers.', 'Lists the time steps for which the CG engine writes a report of the dynamic initial margin regression. Use it to check the quality of the fit on a few dates, because a report on every date would be very large. For example, 1,2,3 writes the report for the first three steps. Without a value the engine writes no regression report.', 'None. The engine writes no regression report.', 'A comma-separated list of whole numbers.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7e80a6a9-6bd9-5c13-ac59-00ebd9e224ed', 0, 'analytic', 'simulation', 'xvaCgUsePythonIntegration', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgUsePythonIntegration'']', 71, 'boolean', false, 'CG Python integration', 'A flag. Y uses the Python integration.', 'Decides whether the CG regression calls Python code for the conditional expectations, through the Python integration of ORE. Use it to try a regression method that you write in Python, for example a machine learning model. Switch it on only when that integration is installed, because a run without it fails.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5fa5085e-c461-561e-a194-7bd67971a02c', 0, 'analytic', 'simulation', 'xvaCgUsePythonIntegrationDynamicIm', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgUsePythonIntegrationDynamicIm'']', 72, 'boolean', false, 'CG Python integration for dynamic IM', 'A flag. Y uses the Python integration for the margin.', 'Decides whether the CG engine calls Python code for the dynamic initial margin. It works like the CG Python integration parameter and applies to the margin only. Switch it on only when that integration is installed, because a run without it fails.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4eee40b3-1170-505c-9a4a-66b2ab31f0b5', 0, 'analytic', 'simulation', 'xvaCgTradeLevelBreakdown', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgTradeLevelBreakdown'']', 73, 'boolean', false, 'CG trade level breakdown (misspelt)', 'A flag. ORE ignores this spelling.', 'Is a spelling of the CG trade level breakdown parameter that ORE does not read. ORE reads only the spelling with a capital D in Break Down: xvaCgTradeLevelBreakDown. Example files use both spellings, so a document with this spelling does not change the run.', 'Not applicable. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '15c57cb9-36eb-576a-b00d-c160e62763c5', 0, 'analytic', 'simulation', 'storeExerciseValues', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''storeExerciseValues'']', 74, 'boolean', false, 'Store exercise values in the cube', 'A flag. Y stores the exercise values.', 'Decides whether the cube also stores the exercise value of each trade on each date. Switch it on when a later analytic needs the value of an option if it is exercised, for example to check the exercise decision of a Bermudan swaption. The cube gets larger when this is on.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eeab3c07-54fa-5c2b-9749-b0bc279e715b', 0, 'analytic', 'simulation', 'xvaCgEnableCgOptimization', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgEnableCgOptimization'']', 75, 'boolean', false, 'CG graph optimisation', 'A flag. Y optimises the graph.', 'Decides whether the CG engine optimises the computation graph while it builds the graph. The optimisation removes steps that do not change the result, so the graph is smaller and the evaluation is faster, at the cost of a longer build. Switch it on to try it on a large portfolio. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '97233f19-490b-5fda-a0f4-c5b120a5f111', 0, 'analytic', 'simulation', 'amcPathDataInput', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcPathDataInput'']', 76, 'string', false, 'AMC path data input file', 'A file name.', 'Names a file with the path data of an earlier AMC run, that is the simulated states of the model on each path and date. The run reads the path data from the file and does not simulate again. Use it together with the output parameter to repeat an AMC valuation on the same paths, for example for a second portfolio. The paths must come from the same model and the same grid.', 'None. The run computes the path data.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3a444621-a67e-5465-8976-0515f3a9573d', 0, 'analytic', 'simulation', 'amcUseGpuRegression', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcUseGpuRegression'']', 77, 'boolean', false, 'Use the GPU for the AMC regression', 'A flag. Y runs the regression on the GPU.', 'Decides whether the AMC regression runs its QR step on a GPU through cuSOLVER. It is an opt-in for runs with a large portfolio on a machine with a supported GPU, where the regression is the main cost. The results do not change, so you can compare a run with the GPU and a run without it. A machine without a supported GPU fails when this is on.', 'No. The regression runs on the CPU.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c3e99550-0eb4-5fe0-9278-8cec0ec15e9d', 0, 'analytic', 'simulation', 'crossAssetModelData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''crossAssetModelData'']', 78, 'string', false, 'Cross asset model file', 'A file name.', 'Names an XML file for the cross asset model, if the model sits in another file than the rest of the simulation setup. Use it to share one calibrated model between several runs. When the parameter is missing, ORE reads the model from the simulation configuration file.', 'The simulation configuration file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ace87339-4070-59b7-a928-6554a243e50d', 0, 'analytic', 'simulation', 'scenarioGeneratorData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''scenarioGeneratorData'']', 79, 'string', false, 'Scenario generator file', 'A file name.', 'Names an XML file for the scenario generator, if it sits in another file than the rest of the simulation setup. The scenario generator sets the date grid, the number of samples and the random number generator. Use it to run the same model on a different grid or sample size. When the parameter is missing, ORE reads the scenario generator from the simulation configuration file.', 'The simulation configuration file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '04588f7c-473e-5a2a-b1a0-58215fff7349', 0, 'analytic', 'simulation', 'maxScenario', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''maxScenario'']', 80, 'integer', false, 'Maximum number of scenarios', 'A whole number of paths.', 'Caps the number of Monte Carlo paths. When the scenario generator asks for more samples than this number, ORE uses this number. It never raises the number of samples. Use a small value for a quick test run. For example, 100 runs at most 100 paths.', 'None. The scenario generator decides.', 'A whole number of zero or more.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'beb7ec4a-b217-5dbf-8b78-446cd0ec6018', 0, 'analytic', 'simulation', 'writeCube', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''writeCube'']', 81, 'boolean', false, 'Write the cube', 'A flag. Y writes the cube files.', 'Decides whether the run writes the NPV cube, the scenario data, the netting set cube and the counterparty cube to files. A value in Cube file switches the output on by itself. Use this flag to write the files with the standard names. The files are cube.csv.gz, scenariodata.csv.gz, nettingsetcube.csv.gz and cptycube.csv.gz.', 'No. The run writes no cube unless Cube file is set.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f2c87bbb-23e4-5e45-9782-542be3fe65aa', 0, 'analytic', 'simulation', 'writeScenarios', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''writeScenarios'']', 82, 'boolean', false, 'Write the scenarios', 'A flag. Y writes the scenario dump.', 'Decides whether the run writes the raw scenarios to a file with the standard name scenario.csv. A scenario file holds the value of each risk factor on each date and path, so it is large. Use it to check the simulation on a small test case. A value in Scenario dump file switches the output on by itself and sets the name.', 'No. The run writes no scenarios unless Scenario dump file is set.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b0fc9c90-6971-5001-ba0a-ed8a4dcacf6e', 0, 'analytic', 'simulation', 'nettingSetId', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''nettingSetId'']', 83, 'string', false, 'Netting set', 'A netting set id. ORE reads it and does not use it.', 'Is read by ORE in release 1.8.17.0 and not used by any later step. A value has no effect.', 'None. ORE ignores the parameter, so a value has no effect.', 'A netting set id.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a71be339-6fa5-5036-8aa9-7989eb4b9453', 0, 'analytic', 'simulation', 'xvaCgRegressionVarianceCutoff', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgRegressionVarianceCutoff'']', 84, 'double', false, 'CG regression variance cutoff', 'A number between 0 and 1.', 'Switches on a principal component analysis of the regressors in the CG regression and sets its variance cutoff. The analysis rotates the regressors, and the regression drops the directions with a variance below the cutoff. Use it when the regressors are strongly correlated. For example, 0.01.', 'None. The regression uses the regressors as they are.', 'A number, written with a decimal point.', '1.8.13.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b2f5a6a4-1970-5557-ab04-1f694ef4e225', 0, 'analytic', 'simulation', 'xvaCgRegressionVarianceCutoffDynamicIm', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''xvaCgRegressionVarianceCutoffDynamicIm'']', 85, 'double', false, 'CG regression variance cutoff for dynamic IM', 'A number between 0 and 1.', 'Sets the variance cutoff of the regression that the CG engine uses for dynamic initial margin. It works like the CG regression variance cutoff and applies to the margin only. A regressor whose variance is below the cutoff adds noise and no information, so the regression drops it. Without a value the regression uses the regressors as they are.', 'None. The regression uses the regressors as they are.', 'A number, written with a decimal point.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5c61ca38-70ef-59b6-977c-5bcc620c462b', 0, 'analytic', 'simulation', 'cubeNpvOverlay', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''cubeNpvOverlay'']', 86, 'boolean', false, 'Correct the cube with the first NPV', 'A flag. Y corrects the cube entries.', 'Decides whether ORE corrects every raw NPV of the cube by the difference between the NPV of the valuation date from the pricing analytic and the NPV of the valuation date from the simulation. Use it when the simulation engines give a slightly different NPV today than the pricing engines.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9b24c8e9-f022-5768-8603-b0c0c2cfa653', 0, 'analytic', 'simulation', 'pricingEnginesOverride', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''pricingEnginesOverride'']', 87, 'string', false, 'Pricing engines override', 'A file name.', 'Names an XML file with pricing engine settings that replace the matching settings of the pricing engines file for the simulation. Use it to change a few engines and keep the rest. ORE applies the file on top of the pricing engines that the simulation uses.', 'None. The engines stay as the pricing engines file sets them.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '42e0a037-3a65-5705-a66b-d207fde6ed8a', 0, 'analytic', 'simulation', 'amcPricingEnginesOverride', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcPricingEnginesOverride'']', 88, 'string', false, 'Pricing engines override for AMC', 'A file name.', 'Names an XML file with pricing engine settings that replace the matching settings of the AMC pricing engines file. Use it to change a few engines for one run, for example the number of training paths of one product, and keep the rest of the file as it is. The file has the same layout as the pricing engines file, and it needs only the entries that change.', 'None. The engines stay as the AMC pricing engines file sets them.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9bc036ed-9bf5-58d3-b08e-4ebe4bb6bcb9', 0, 'analytic', 'simulation', 'amcCgPricingEnginesOverride', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simulation'']/Parameter[@name=''amcCgPricingEnginesOverride'']', 89, 'string', false, 'Pricing engines override for the CG engine', 'A file name.', 'Names an XML file with pricing engine settings that replace the matching settings of the CG pricing engines file. Use it to change a few engines for one run and keep the rest of the file as it is. The file has the same layout as the pricing engines file, and it needs only the entries that change.', 'None. The engines stay as the CG pricing engines file sets them.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b6b792ab-a071-5a50-a950-d2165d0aeee3', 0, 'analytic', 'xva', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''active'']', 90, 'boolean', true, 'Run the XVA analytic', 'A flag. Y runs the analytic.', 'Switches the XVA analytic on or off. When it is on, the run post-processes an NPV cube: it nets the trades, applies the collateral agreement and computes the exposure profiles, and then the value adjustments that the flags below select. The cube comes from the simulation analytic of the same run or from a file.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '37cd2354-549c-5b71-a3fd-6a0e7b5ea2e5', 0, 'analytic', 'xva', 'csaFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''csaFile'']', 91, 'string', false, 'Netting set definitions file', 'A file name.', 'Names the XML file with the netting set definitions: the CSA details such as the margining frequency, the thresholds, the minimum transfer amounts and the margin period of risk. The post-processing reads the file, so you can change the CSA terms and see their effect on the results without a new simulation. ORE looks for the file name in the xva block, then in the pfe block and last in the Setup block. For example, netting.xml.', 'The netting set definitions file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bb9713bc-ab0b-507b-a768-c7799f6fb62a', 0, 'analytic', 'xva', 'cubeFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''cubeFile'']', 92, 'string', false, 'Cube file', 'A file name.', 'Names the NPV cube file that the XVA analytic reads, if the run has no simulation. The file is usually the cube that an earlier simulation wrote, so you can run the post-processing again without a new simulation. ORE looks for the file in the output path of the Setup block. For example, cube.csv.gz.', 'None. When the run has a simulation, the analytic uses its cube.', 'A file name. ORE looks for the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '89712089-51f9-5ba5-8000-4a2db14f3763', 0, 'analytic', 'xva', 'scenarioFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''scenarioFile'']', 93, 'string', false, 'Scenario data file', 'A file name.', 'Names the file with the scenario data that the simulation wrote for the post-processing, such as simulated index fixings and FX rates. Variation margin and dynamic initial margin need it, because they must recompute a margin amount on each path and date. Use it when the post-processing runs apart from the simulation, together with the cube file. For example, scenariodata.csv.gz.', 'None. When the run has a simulation, the analytic uses its scenario data.', 'A file name. ORE looks for the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd1bc37b2-a1d5-58a2-a2f0-703ede69b91a', 0, 'analytic', 'xva', 'baseCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''baseCurrency'']', 94, 'string', false, 'Base currency', 'A currency code, for example EUR.', 'Names the currency in which the analytic states every NPV, exposure and value adjustment. ORE converts an amount in another currency at the spot rate of the valuation date. Use the currency in which the desk or the capital report measures its risk. For example, EUR states all values in euro. The Setup block has a parameter of the same name, which this one overrides for this analytic.', 'The base currency of the Setup block.', 'A currency code of three letters, for example EUR.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '90cbedb5-40b8-52c9-8d13-415f38effbc0', 0, 'analytic', 'xva', 'exposureProfiles', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''exposureProfiles'']', 95, 'boolean', false, 'Write exposure profiles', 'A flag. Y writes the profiles for each netting set.', 'Decides whether the analytic writes an exposure report for each netting set: the expected positive and negative exposure and the potential future exposure, for each date. The profiles show how the exposure builds up and runs off over the life of the trades, so they are the main result to read for a credit limit or a capital check. The XVA analytic has the same parameter.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '81a4b2f5-4466-5526-ae00-25dba95e2162', 0, 'analytic', 'xva', 'exposureProfilesByTrade', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''exposureProfilesByTrade'']', 96, 'boolean', false, 'Write exposure profiles by trade', 'A flag. Y writes the stand-alone profiles for each trade.', 'Decides whether the analytic writes an exposure report for each trade on its own, without the netting. With many trades this makes many files, unless Write individual exposure reports is off. The XVA analytic has the same parameter.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.4.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '76e37747-a163-5ae1-8f1a-1f58838d5a1c', 0, 'analytic', 'xva', 'quantile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''quantile'']', 97, 'double', false, 'PFE confidence level', 'A number between 0 and 1.', 'Sets the confidence level of the potential future exposure (PFE) in the exposure reports. The PFE is the quantile of the positive exposure distribution on each date, so a higher level gives a larger number. For example, 0.95 reports the 95th percentile, and 0.99 reports the 99th, which a limit system often uses. The XVA analytic has the same parameter.', '0.95', 'A number, written with a decimal point.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5f1990a0-704f-515e-bd2f-a9af63de71da', 0, 'analytic', 'xva', 'calculationType', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''calculationType'']', 98, 'string', false, 'Margin settlement type', 'NoLag, Symmetric, AsymmetricCVA or AsymmetricDVA.', 'Decides how ORE settles margin calls. Symmetric settles the margin of both parties after the margin period of risk. AsymmetricCVA settles the margin that we request from the counterparty with the delay and the margin that the counterparty requests from us at once. AsymmetricDVA is the reverse. NoLag turns the delay off and works together with a close-out grid in the simulation. Without a close-out grid, use one of the three others. With one, use NoLag. When there is no close-out grid, the results are correct only if the simulation grid is equally spaced with steps equal to the margin period of risk. The XVA analytic has the same parameter.', 'NoLag', 'One of NoLag, Symmetric, AsymmetricCVA or AsymmetricDVA.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '445114a6-8b16-5512-8978-a12899d04286', 0, 'analytic', 'xva', 'cva', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''cva'']', 99, 'boolean', false, 'Compute CVA', 'A flag. Y computes the credit value adjustment.', 'Switches the credit value adjustment (CVA) on or off. CVA prices the loss that the default of the counterparty causes on the positive exposure, so it is the main charge of the analytic. The analytic needs the default curve of each counterparty in the market data. Set it to N when the run is for another adjustment only, for example the funding value adjustment, because the CVA takes time to compute for a large portfolio.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6322cf84-7d06-5a10-a5bd-cfa4a4b0bfa3', 0, 'analytic', 'xva', 'rawCubeOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''rawCubeOutputFile'']', 100, 'string', false, 'Raw cube report file', 'A file name.', 'Names the file for the trade NPV cube as a text file with one row for each trade, date and sample. Setting it switches the report on. Leave it out to skip the file. The file is for further analysis and can be very large. The XVA analytic has the same parameter.', 'None. The analytic does not write the file.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '88ef576e-8e37-52f6-8764-0b4c1642cc87', 0, 'analytic', 'xva', 'netCubeOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''netCubeOutputFile'']', 101, 'string', false, 'Net cube report file', 'A file name.', 'Names the file for the aggregated NPV cube as a text file with one row for each netting set, date and sample, after the collateral. Setting it switches the report on. Leave it out to skip the file. The XVA analytic has the same parameter.', 'None. The analytic does not write the file.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1d2a309b-ad2d-54a7-8392-7db3c7a7fc28', 0, 'analytic', 'xva', 'dim', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dim'']', 102, 'boolean', false, 'Compute DIM', 'A flag. Y computes the dynamic initial margin.', 'Switches the dynamic initial margin (DIM) calculation on or off. DIM projects the initial margin of each netting set along each path, as a margin model such as the SIMM would compute it on that path. The parameter DIM model selects the method. The margin value adjustment needs the result. The calculation is costly, so switch it on only when the run needs the margin.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a2e2d9da-16de-5ecf-9e98-7ce3f8b83eda', 0, 'analytic', 'xva', 'dimModel', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimModel'']', 103, 'string', false, 'DIM model', 'Regression, Flat, DeltaVaR, DeltaGammaNormalVaR, DeltaGammaVaR, DynamicIM or SimmAnalytic.', 'Selects the method for the dynamic initial margin. Regression regresses the change of the netting set value over the margin period on the value at the start. Flat projects the initial margin of the valuation date unchanged along each path, and needs the collateral balances file. DeltaVaR, DeltaGammaNormalVaR and DeltaGammaVaR use stored sensitivities and need the simulation to store them. SimmAnalytic uses stored sensitivities and the SIMM formula. DynamicIM needs the CG engine with its dynamic IM switch on. The run stops if the value is none of these. ORE uses it only when DIM is on.', 'Regression', 'One of Regression, Flat, DeltaVaR, DeltaGammaNormalVaR, DeltaGammaVaR, DynamicIM or SimmAnalytic.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8b8c5d72-c266-53a1-8cd9-a3ea42fe2e2b', 0, 'analytic', 'xva', 'dimQuantile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimQuantile'']', 104, 'double', false, 'DIM quantile', 'A number between 0 and 1.', 'Sets the quantile of the margin movement that the DIM covers. A higher quantile gives a larger margin. For example, 0.99 covers the 99th percentile, which is the usual level of a margin model. ORE uses it only when DIM is on. Change it to follow the margin model of the agreement, for example 0.995.', '0.99', 'A number, written with a decimal point.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'efeddc24-b1d5-51f7-8a19-2c3e1c5bf9aa', 0, 'analytic', 'xva', 'dimHorizonCalendarDays', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimHorizonCalendarDays'']', 105, 'integer', false, 'DIM horizon in calendar days', 'A whole number of days.', 'Sets the length of the margin period of risk that the DIM covers, in calendar days. The margin has to cover the movement of the portfolio over this period. The default is 14 calendar days, which is about ten business days, the period of the standard SIMM.', '14', 'A whole number of zero or more.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3347c36f-e0b6-55e6-94f9-d300b893bb99', 0, 'analytic', 'xva', 'dimRegressionOrder', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimRegressionOrder'']', 106, 'integer', false, 'DIM regression order', 'A whole number.', 'Sets the order of the regression polynomial of the DIM model Regression. The regression relates the clean change of the netting set value over the period to the value at the start of the period. A higher order follows a non-linear relation better and needs more paths to stay stable. ORE uses it only when DIM is on. For example, 2 fits a quadratic curve.', '0', 'A whole number of zero or more.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1cfc7872-5f7d-5ec3-b049-4ab2c38994f2', 0, 'analytic', 'xva', 'allocationMethod', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''allocationMethod'']', 107, 'string', false, 'Exposure allocation method', 'None, Marginal, RelativeXVA, RelativeFairValueGross or RelativeFairValueNet.', 'Selects how ORE allocates the netting set exposure and the value adjustments to the trades in the netting set. None gives no allocation. Marginal uses the marginal method of Pykhtin and Rosen. The other three split the amount in proportion to the XVA of the trade, to its gross fair value or to its net fair value. The XVA analytic has the same parameter.', 'None', 'One of None, Marginal, RelativeXVA, RelativeFairValueGross or RelativeFairValueNet.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e28339db-7231-5a3d-9e9c-e1fc7b8abf8b', 0, 'analytic', 'xva', 'marginalAllocationLimit', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''marginalAllocationLimit'']', 108, 'double', false, 'Marginal allocation limit', 'A number.', 'Sets a cutoff for the marginal allocation. The marginal method breaks down when the value of the netting set is close to zero while its exposure is not. Below this absolute value, ORE splits the exposure equally among the trades. The parameter has an effect only when the allocation method is Marginal. The XVA analytic has the same parameter.', '1.0', 'A number, written with a decimal point.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '47a850db-5264-59d5-88e4-04b60e6ede88', 0, 'analytic', 'xva', 'exerciseNextBreak', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''exerciseNextBreak'']', 109, 'boolean', false, 'Exercise at the next break', 'A flag. Y ends each trade at its next break date.', 'Decides whether ORE ends all trades at their next break date before it aggregates them. Use it to model a counterparty relationship in which each party can end a trade at its break dates. A trade that ends early adds no exposure after its break, so the profiles are lower than with the full maturity. The default is No, so every trade runs to maturity. The XVA analytic has the same parameter.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '11292f66-d740-5ac1-bd5b-c8f35c3294d9', 0, 'analytic', 'xva', 'dva', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dva'']', 110, 'boolean', false, 'Compute DVA', 'A flag. Y computes the debit value adjustment.', 'Switches the debit value adjustment (DVA) on or off. DVA is the gain from our own default on the negative exposure: the counterparty may lose when we default. Many firms report it, and some leave it out of the price of a trade. Set the DVA name too, so that ORE can find our own default curve and recovery rate. The DVA calculation needs that name.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bc4da7c1-5976-5041-a929-ba6aac129267', 0, 'analytic', 'xva', 'dvaName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dvaName'']', 111, 'string', false, 'DVA name', 'A credit name.', 'Names the credit entity that ORE uses to look up our own default probability curve and recovery rate for the DVA. The name must be in the market data, in the same form as the name of a counterparty. For example, BANK uses the default curve of the entity BANK. The DVA needs the name.', 'None. A DVA calculation needs a name.', 'A credit name as it appears in the market data, for example BANK.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd66aa2ee-0a85-5556-8d73-60a83d429e89', 0, 'analytic', 'xva', 'fva', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''fva'']', 112, 'boolean', false, 'Compute FVA', 'A flag. Y computes the funding value adjustment.', 'Switches the funding value adjustment (FVA) on or off. FVA prices the cost of funding the part of the exposure that no collateral covers: we borrow to fund a positive exposure and we lend what a negative exposure releases. It needs a borrowing curve and a lending curve, and both come from the market data. The cost depends on the spread of these curves over the overnight rate, so a small spread gives a small FVA.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9182ffd7-fecb-5dbd-8d19-a613f0b8c6cb', 0, 'analytic', 'xva', 'fvaBorrowingCurve', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''fvaBorrowingCurve'']', 113, 'string', false, 'FVA borrowing curve', 'The name of a yield curve.', 'Names the yield curve at which we borrow, for the FVA. This spelling is the older one, and ORE reads it only when the parameter Borrowing curve is missing. The curve must be in the market data, and its spread over the overnight rate is what makes the funding cost. For example, BANK_EUR_BORROW. Use the newer parameter in a new document.', 'None. An FVA calculation needs a curve.', 'The name of a yield curve in the market data.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c6c1332b-62b0-5260-9a09-647749bac2a3', 0, 'analytic', 'xva', 'fvaLendingCurve', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''fvaLendingCurve'']', 114, 'string', false, 'FVA lending curve', 'The name of a yield curve.', 'Names the yield curve at which we lend, for the FVA. This spelling is the older one, and ORE reads it only when the parameter Lending curve is missing. The curve must be in the market data. A negative exposure releases funding that we lend at this curve. For example, BANK_EUR_LEND. Use the newer parameter in a new document.', 'None. An FVA calculation needs a curve.', 'The name of a yield curve in the market data.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dff50129-be08-5686-97d4-fb204e7311f6', 0, 'analytic', 'xva', 'colva', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''colva'']', 115, 'boolean', false, 'Compute COLVA', 'A flag. Y computes the collateral value adjustment.', 'Switches the collateral value adjustment (COLVA) on or off. COLVA prices the difference between the rate that the collateral earns under the credit support annex and the overnight rate, on the expected collateral balance. It matters for netting sets with large collateral and a collateral rate that differs from the overnight rate. The collateral model of the netting set definitions sets the collateral rate.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ea7164b8-c2be-51a0-a2ac-587e91613d2c', 0, 'analytic', 'xva', 'collateralSpread', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''collateralSpread'']', 116, 'double', false, 'Collateral spread', 'A number. ORE no longer reads it.', 'Set the difference between the collateral rate and the overnight rate for the COLVA, as an absolute number: one basis point is 0.0001. ORE stopped reading it in 1.8.3.0. Today the collateral model of the netting set definitions sets the collateral rate.', 'None. ORE ignores the parameter, so a value has no effect.', 'A number, written with a decimal point.', '1.8.0.7 or earlier', '1.8.3.0'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '71ef17b0-60ab-58e0-8a52-2a24820dcffa', 0, 'analytic', 'xva', 'collateralFloor', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''collateralFloor'']', 117, 'boolean', false, 'Compute the collateral floor', 'A flag. Y computes the collateral floor value.', 'Switches the calculation of the collateral floor on or off. Some credit support annexes floor the rate that the collateral earns, for example at zero when the overnight rate is negative. The calculation values that floor as an option on the collateral rate, and ORE adds its value to the COLVA. Switch it on for netting sets whose agreement has a floor.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bb390dac-a5a0-5e5b-9267-58a13758c2df', 0, 'analytic', 'xva', 'dimScaling', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimScaling'']', 118, 'double', false, 'DIM scaling', 'A number.', 'Sets a factor that ORE applies to the DIM values of the Regression and DeltaVaR family models. The factor applies to all netting sets, and ORE then ignores the initial margin of the collateral balances. When the parameter is missing, ORE derives a factor for each netting set from the initial margin of the collateral balances file divided by the model DIM at the valuation date. That initial margin must be above zero, or the run stops. A value of 1.0 applies no scaling. It has no effect for SimmAnalytic and DynamicIM. ORE uses it only when DIM is on.', 'None. ORE derives the factor from the collateral balances.', 'A number, written with a decimal point.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cab8a35c-deaa-5aec-8b9a-1d1740786444', 0, 'analytic', 'xva', 'dimEvolutionFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimEvolutionFile'']', 119, 'string', false, 'DIM evolution file', 'A file name.', 'Names the file for the evolution of the zero-order DIM and the average of the n-th order DIM over time. Use it to see how the margin runs off as the trades mature. For example, dim_evolution.csv. The analytic writes the file only when it has a name. ORE uses it only when DIM is on.', 'None. The analytic does not write the file.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '990d7135-6aa9-575e-994e-275723114ff8', 0, 'analytic', 'xva', 'dimRegressionFiles', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimRegressionFiles'']', 120, 'string', false, 'DIM regression snapshot files', 'A comma-separated list of file names.', 'Names the files for snapshots of the DIM regression, one file for each grid point that DIM output grid points lists. A snapshot shows the data and the fit of the regression at a date, so you can check the quality of the fit. For example, dim_regression_1.csv,dim_regression_2.csv. ORE uses it only when DIM is on.', 'None. The analytic does not write the files.', 'A comma-separated list of file names.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '41e8fafb-ee6e-5dcf-81a8-4115e9b21ce0', 0, 'analytic', 'xva', 'dimOutputNettingSet', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimOutputNettingSet'']', 121, 'string', false, 'DIM snapshot netting set', 'A netting set id.', 'Names the netting set for which the analytic writes the DIM regression snapshot. The snapshot is large, so the analytic writes it for one netting set only. For example, CPTY_A writes the snapshot of the netting set CPTY_A. ORE uses it only when DIM is on and the regression files are named.', 'None.', 'A netting set id.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0197af9f-641e-5cc4-a5ce-91c5af586fcc', 0, 'analytic', 'xva', 'dimOutputGridPoints', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimOutputGridPoints'']', 122, 'integer', false, 'DIM snapshot grid points', 'A comma-separated list of whole numbers.', 'Lists the points of the time grid for which the analytic writes a DIM regression snapshot. Each number is the index of a grid date, counted from zero. For example, 1,10 writes the snapshots of the second and the eleventh date. One file is written for each point. ORE uses it only when DIM is on.', 'None.', 'A comma-separated list of whole numbers.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '21e52ece-d404-546a-941c-68ea6f7a5b61', 0, 'analytic', 'xva', 'dimLocalRegressionEvaluations', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimLocalRegressionEvaluations'']', 123, 'integer', false, 'DIM local regression evaluations', 'A whole number.', 'Sets the number of points at which ORE evaluates a local (Nadaraya-Watson) regression to validate the polynomial regression. The local regression needs many samples to give a meaningful result, and each evaluation costs time, so keep the number small. A value of zero turns the check off. ORE uses it only when DIM is on.', '0', 'A whole number of zero or more.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1e003738-99e8-5024-a4d1-ecec85bb5f2b', 0, 'analytic', 'xva', 'dimLocalRegressionBandwidth', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimLocalRegressionBandwidth'']', 124, 'double', false, 'DIM local regression bandwidth', 'A number of standard deviations.', 'Sets the bandwidth of the local regression that validates the polynomial regression of the DIM, in standard deviations of the NPV. A wider band uses more paths for each local fit and gives a smoother check. The default is 0.25. ORE uses it only when DIM is on and the DIM model uses regression.', '0.25', 'A number, written with a decimal point.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '90814b1d-6daa-5308-bd03-d8f35b17be10', 0, 'analytic', 'xva', 'mva', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''mva'']', 125, 'boolean', false, 'Compute MVA', 'A flag. Y computes the margin value adjustment.', 'Switches the margin value adjustment (MVA) on or off. MVA prices the funding cost of the initial margin that we post over the life of the trades. It takes the projected initial margin from the dynamic initial margin model that the DIM model parameter selects, so DIM must be on. The result depends on the margin model, so compare MVA only between runs that use the same model.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bf90294c-f7e7-5a83-b99f-9b59a5c69796', 0, 'analytic', 'xva', 'dimRegressors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimRegressors'']', 126, 'string', false, 'DIM regressors', 'A comma-separated list of names.', 'Lists the variables that the DIM regression uses as regressors, for a regression in one or more dimensions. The names must match the entries of the aggregation scenario data in the simulation configuration file, that is its currencies and indices. When the list is empty, the regression uses the NPV as its only regressor. For example, EUR-EURIBOR-3M,USD-LIBOR-3M,USD. ORE uses it only when DIM is on.', 'None. The regression uses the NPV.', 'A comma-separated list of currency codes and index names.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dd5388da-a94a-5f35-88c1-8110d9ceb05e', 0, 'analytic', 'xva', 'collateralBalancesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''collateralBalancesFile'']', 127, 'string', false, 'Collateral balances file', 'A file name.', 'Names the XML file with the current variation margin and initial margin balances for each netting set. The analytic uses them as the margin at the valuation date, and the flat DIM model and the scaling of the DIM model use the initial margin. ORE looks for the file name in the xva block, then in the pfe block and last in the Setup block. For example, collateralbalances.xml.', 'The collateral balances file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5d462de5-cbe6-5555-bf3c-a8612646ab9c', 0, 'analytic', 'xva', 'useXvaRunner', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''useXvaRunner'']', 128, 'boolean', false, 'Use the XVA runner', 'A flag. ORE no longer reads it.', 'Selected an older way to run the XVA calculation. ORE stopped reading it in 1.8.9.1.', 'None. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.6.0', '1.8.9.1'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e60737e0-c60d-53b3-ae6e-7bd16451db0d', 0, 'analytic', 'xva', 'dynamicCredit', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dynamicCredit'']', 129, 'boolean', false, 'Dynamic credit', 'A flag. Y uses the survival probabilities along each path.', 'Decides whether ORE uses the survival probabilities of each simulation path when it computes the increments of CVA, DVA, FVA and MVA from the exposures. When it is N, ORE takes the survival probabilities from the curves of the valuation date. The simulation must store the survival probabilities.', 'No. ORE uses the survival probabilities of the valuation date.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '520cc5ce-66ae-5a82-8c1b-8a617df1b346', 0, 'analytic', 'xva', 'fvaFundingCurve', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''fvaFundingCurve'']', 130, 'string', false, 'FVA funding curve', 'The name of a yield curve. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it. Use Borrowing curve and Lending curve to name the curves of the FVA.', 'None. ORE ignores the parameter, so a value has no effect.', 'The name of a yield curve in the market data.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1626de5e-4dd1-5d56-b246-0b05bd6923a6', 0, 'analytic', 'xva', 'fvaInvestmentCurve', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''fvaInvestmentCurve'']', 131, 'string', false, 'FVA investment curve', 'The name of a yield curve. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it. Use Borrowing curve and Lending curve to name the curves of the FVA.', 'None. ORE ignores the parameter, so a value has no effect.', 'The name of a yield curve in the market data.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2274169a-f11e-54ad-a954-a3607e1bb8fc', 0, 'analytic', 'xva', 'colvaSpread', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''colvaSpread'']', 132, 'double', false, 'COLVA spread', 'A number. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it. The collateral model of the netting set definitions sets the collateral rate.', 'None. ORE ignores the parameter, so a value has no effect.', 'A number, written with a decimal point.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5d221cb6-54ed-5c22-b8f2-3d6b511a456a', 0, 'analytic', 'xva', 'eoniaFloor', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''eoniaFloor'']', 133, 'boolean', false, 'EONIA floor', 'A flag. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it. To floor the collateral rate, use Compute the collateral floor.', 'None. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c4e04b8a-a8bd-5d88-8c5f-a464c7525ac5', 0, 'analytic', 'xva', 'hyperCube', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''hyperCube'']', 134, 'boolean', false, 'Hyper cube', 'A flag. ORE no longer reads it.', 'Selected the use of the hyper cube in an older version of the XVA calculation. ORE stopped reading it in 1.8.9.1.', 'None. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', '1.8.9.1'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd2be61b6-7177-56b9-b73e-2b50658be51b', 0, 'analytic', 'xva', 'creditMigration', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''creditMigration'']', 135, 'boolean', false, 'Credit migration', 'A flag. Y runs the credit migration analytic.', 'Switches the credit migration calculation on or off. It computes the distribution of the portfolio value under rating migrations of the counterparties, so it shows the loss that a downgrade causes before any default. It needs a simulation that stores the NPVs for each credit state, and the credit migration configuration file.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5fae26a8-5572-53c7-bcd1-49f49c4db113', 0, 'analytic', 'xva', 'creditMigrationDistributionGrid', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''creditMigrationDistributionGrid'']', 136, 'string', false, 'Credit migration distribution grid', 'A comma-separated list of numbers.', 'Sets the grid on which ORE reports the distribution of the portfolio value in the credit migration calculation. Write three numbers: the lowest value, the highest value and the number of points between them. For example, -2E7,1E7,300 reports the distribution from minus twenty million to ten million on 300 points. ORE uses it only when credit migration is on.', 'None.', 'A comma-separated list of numbers.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1ccd3a68-9b97-521b-842b-93491b25cc2d', 0, 'analytic', 'xva', 'creditMigrationTimeSteps', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''creditMigrationTimeSteps'']', 137, 'string', false, 'Credit migration time steps', 'A comma-separated list of whole numbers.', 'Lists the time steps of the simulation grid at which ORE reports the credit migration distribution. Each number is the index of a grid date. For example, 12,24 reports the distribution at the twelfth and the twenty-fourth step. ORE uses it only when credit migration is on.', 'None.', 'A comma-separated list of whole numbers.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5fe92299-f291-5794-9352-f3a01f01eb5f', 0, 'analytic', 'xva', 'creditMigrationConfig', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''creditMigrationConfig'']', 138, 'string', false, 'Credit migration configuration file', 'A file name.', 'Names the XML file with the credit simulation parameters: the rating states and the migration matrices. The credit migration calculation reads the matrix that gives the chance of a move from one rating to another over a period. For example, creditmigration.xml. ORE uses it only when credit migration is on.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '223e79dc-2281-5264-bfda-990bc87dba1a', 0, 'analytic', 'xva', 'creditMigrationOutputFiles', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''creditMigrationOutputFiles'']', 139, 'string', false, 'Credit migration output files', 'A file name stem.', 'Sets the stem of the output files of the credit migration. ORE appends an underscore and the time step to the stem to name each file. For example, migration gives migration_12.csv for the twelfth step. ORE uses it only when credit migration is on.', 'None.', 'A file name stem without extension.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'db274212-1464-5055-a1a1-363bad629b43', 0, 'analytic', 'xva', 'flipViewXVA', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''flipViewXVA'']', 140, 'boolean', false, 'Flip the view of the XVA', 'A flag. Y computes the XVA from the counterparty''s view.', 'Decides whether ORE switches the perspective of the XVA calculation to that of the counterparty. ORE then reverses the NPVs and the netting sets. It looks for the borrowing and lending curves under the name of the counterparty plus a postfix, which the next two parameters set.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dcdce6e8-2d11-5c99-8e63-8942477fc1fc', 0, 'analytic', 'xva', 'flipViewBorrowingCurvePostfix', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''flipViewBorrowingCurvePostfix'']', 141, 'string', false, 'Flip view borrowing curve postfix', 'A text.', 'Sets the text that ORE appends to the name of the counterparty to find the borrowing curve when the view is flipped. A flipped view prices the XVA from the point of view of the counterparty, so it needs the curves of the counterparty. For example, _BORROW looks for the curve CPTY_A_BORROW. ORE uses it only when Flip the view is on.', '_BORROW', 'A text.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fadfc582-57dd-5dfd-b8d2-0e4b54ffd04a', 0, 'analytic', 'xva', 'flipViewLendingCurvePostfix', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''flipViewLendingCurvePostfix'']', 142, 'string', false, 'Flip view lending curve postfix', 'A text.', 'Sets the text that ORE appends to the name of the counterparty to find the lending curve when the view is flipped. A flipped view prices the XVA from the point of view of the counterparty, so it needs the curves of the counterparty. For example, _LEND looks for the curve CPTY_A_LEND. ORE uses it only when Flip the view is on.', '_LEND', 'A text.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f2dedc69-9d6d-5485-81a6-3a32323105df', 0, 'analytic', 'xva', 'timeAveragedNettedExposureOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''timeAveragedNettedExposureOutputFile'']', 143, 'string', false, 'Time averaged exposure report file', 'A file name.', 'Names the file for the time averaged netted exposure of each netting set. The report averages the expected exposure over time, which is the number that some capital rules use. For example, timeaveraged.csv. Setting the parameter switches the report on.', 'None. The analytic does not write the file.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0ecfb4bc-d2a1-5596-ae1a-a3927391d53c', 0, 'analytic', 'xva', 'firstMporCollateralAdjustment', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''firstMporCollateralAdjustment'']', 144, 'boolean', false, 'First MPoR collateral adjustment', 'A flag. Y adjusts the collateral in the first margin period.', 'Decides whether ORE corrects the collateral in the first margin period of risk for a mismatch between the variation margin balance and the NPV at the valuation date. Switch it on when you start from real balances that do not equal the NPV.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '916f16df-2522-5dda-8b9d-c5f260628efb', 0, 'analytic', 'xva', 'outputCrossAssetModelData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''outputCrossAssetModelData'']', 145, 'boolean', false, 'Write the cross asset model', 'A flag. Y writes the model data.', 'Decides whether the analytic writes the cross asset model data of the run to the file crossassetmodel_xva.xml in the output path. The file holds the calibrated parameters of the model. Use it to check the model that the run used, or to reuse a calibration in another run.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '210695d4-1b21-5a76-bd74-8d24910305dc', 0, 'analytic', 'xva', 'correlationInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''correlationInputFile'']', 146, 'string', false, 'Correlation input file', 'A file name.', 'Names a file with correlation data for the risk factor pairs. The analytic reads the correlations from the file. The name correlationUri is an older name for the same parameter. ORE looks for the file in the input path of the Setup block.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c057914e-83b1-5cae-81a5-a82cc1f88b09', 0, 'analytic', 'xva', 'scenarioCorrSimulation', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''scenarioCorrSimulation'']', 147, 'string', false, 'Correlation scenario simulation file', 'A file name.', 'Names the XML file with the simulation market for the correlation calculation. The name scenarioSimulationUri is an older name for the same parameter. The correlation calculation reads this parameter from the xva block when generate correlations is on.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cf4a3340-1745-5e86-9450-bd170b52b477', 0, 'analytic', 'xva', 'simulationConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''simulationConfigFile'']', 148, 'string', false, 'Simulation configuration file', 'A file name.', 'Names the XML file with the simulation configuration for the calculation that ORE runs from the xva block. For example, simulation.xml. The correlation calculation reads this parameter from the xva block when generate correlations is on.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c3507d80-eea5-5236-9bca-bf6efcf25b10', 0, 'analytic', 'xva', 'historicalScenarioFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''historicalScenarioFile'']', 149, 'string', false, 'Historical scenario file', 'A file name.', 'Names the file with the historical market scenarios for the correlation calculation. The name scenarioFile is an older name for the same parameter. The correlation calculation reads this parameter from the xva block when generate correlations is on.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a3a0a89a-2848-5ce2-a7b3-f19789c169f6', 0, 'analytic', 'xva', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''sensitivityConfigFile'']', 150, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file with the sensitivity configuration, that is the risk factors and the shifts, for the correlation calculation. The correlation calculation reads this parameter from the xva block when generate correlations is on.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2471d0b4-411a-5966-a310-8a2cc54fd99a', 0, 'analytic', 'xva', 'historicalPeriod', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''historicalPeriod'']', 151, 'string', false, 'Historical period', 'Two dates or a list of dates.', 'Sets the period of the history that the correlation calculation uses. The names lookbackPeriod, benchmarkVarPeriod and benchmarkPeriod are other names for the same parameter. The correlation calculation reads this parameter from the xva block when generate correlations is on.', 'None. The correlation calculation needs it.', 'Dates as the correlation analytic reads them.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e607c835-ecb6-5e6b-a275-700968d09bd2', 0, 'analytic', 'xva', 'mporDays', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''mporDays'']', 152, 'integer', false, 'MPoR days', 'A whole number of days.', 'Sets the number of days of the horizon over which the correlation calculation measures the moves of the risk factors. The name horizonDays is another name for the same parameter. The correlation calculation reads this parameter from the xva block when generate correlations is on.', '10', 'A whole number of zero or more.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5d49b70a-c4a4-5688-9a73-e42fad90b4a1', 0, 'analytic', 'xva', 'mporCalendar', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''mporCalendar'']', 153, 'string', false, 'MPoR calendar', 'A calendar name.', 'Names the calendar that the correlation calculation uses to count the days of the horizon. The name horizonCalendar is another name for the same parameter. The correlation calculation reads this parameter from the xva block when generate correlations is on.', 'The calendar of the base currency.', 'A calendar name such as TARGET or UK.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cc838ac2-07de-54a3-baf1-f9425e3bf55f', 0, 'analytic', 'xva', 'deterministicInitialMarginFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''deterministicInitialMarginFile'']', 154, 'string', false, 'Deterministic initial margin file', 'A file name.', 'Names a file with the initial margin of each netting set as a time series. The analytic uses these amounts for the initial margin instead of a model, so the margin does not change with the paths. Use it when a clearing house or a risk system supplies the margin. ORE looks for the file in the input path of the Setup block.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.9.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '49be9cf5-86ab-54c2-b837-73f60fb68fa7', 0, 'analytic', 'xva', 'fullInitialCollateralisation', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''fullInitialCollateralisation'']', 155, 'boolean', false, 'Full initial collateralisation', 'A flag. Y sets the collateral at the start to the NPV.', 'Decides what the collateral balance is at the valuation date. When it is Y, ORE sets the balance of each netting set to its NPV, so that the expected exposure, the expected negative exposure and the PFE are all zero at the start. When it is N, ORE sets the balance to zero.', 'No. The collateral balance at the start is zero.', 'A flag, written Y or N, or true or false.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dae889ea-20dd-5d3a-a713-c6102586cd4b', 0, 'analytic', 'xva', 'dimDistributionCoveredStdDevs', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimDistributionCoveredStdDevs'']', 156, 'double', false, 'DIM distribution range', 'A number of standard deviations, or inf.', 'Sets the range of the DIM distribution report: ORE covers this many standard deviations around the mean of the data. A wider range shows more of the tails and spreads the grid over a larger interval. The default is 5.0. The value inf covers all of the data. ORE uses it only when DIM is on.', '5.0', 'A number, or the word inf.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '01955e2e-1b8a-5cf0-a31d-88a235598c08', 0, 'analytic', 'xva', 'dimDistributionGridSize', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''dimDistributionGridSize'']', 157, 'integer', false, 'DIM distribution grid size', 'A whole number.', 'Sets the number of points of the grid of the DIM distribution report. A larger grid gives a finer picture of the distribution of the margin and a larger file. The default is 50. ORE uses it only when DIM is on. For example, 100 doubles the resolution.', '50', 'A whole number of zero or more.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ca01ce2e-3e21-500b-82a2-38f0b693198b', 0, 'analytic', 'xva', 'borrowingCurve', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''borrowingCurve'']', 158, 'string', false, 'Borrowing curve', 'The name of a yield curve.', 'Names the yield curve at which we borrow, for the FVA. The curve must be in the market data. The FVA charges the difference between this curve and the overnight rate on the positive uncollateralised exposure, so a wider spread gives a larger charge. For example, BANK_EUR_BORROW. The FVA needs both this curve and the lending curve.', 'None. An FVA calculation needs a curve.', 'The name of a yield curve in the market data.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c2b0c6eb-9341-5992-9eaa-1cb2720adf26', 0, 'analytic', 'xva', 'lendingCurve', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''lendingCurve'']', 159, 'string', false, 'Lending curve', 'The name of a yield curve.', 'Names the yield curve at which we lend, for the FVA. The curve must be in the market data. The FVA credits the difference between this curve and the overnight rate on the negative uncollateralised exposure. For example, BANK_EUR_LEND. The FVA needs both this curve and the borrowing curve.', 'None. An FVA calculation needs a curve.', 'The name of a yield curve in the market data.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0c0da5d3-f5f8-55db-80f7-e14041508f3a', 0, 'analytic', 'xva', 'generateCorrelations', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''generateCorrelations'']', 160, 'boolean', false, 'Generate correlations', 'A flag. Y runs the correlation analytic.', 'Decides whether the XVA analytic first runs the correlation analytic and uses its result as the correlations of the simulation model. Use it when the correlations should come from the data of the run and not from a file. The correlation analytic reads its parameters from the xva block when it runs this way. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ddc3d356-a72c-5f5f-ae95-2a73a6335111', 0, 'analytic', 'xva', 'useDoublePrecisionCubes', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''useDoublePrecisionCubes'']', 161, 'boolean', false, 'Double precision cubes', 'A flag. Y uses double precision.', 'Decides whether the XVA analytic builds its cubes with double precision numbers. Single precision uses half the memory. Switch to double precision when the single precision rounding is too large for your netting sets. The XVA analytic has the same parameter.', 'No. The cubes use single precision.', 'A flag, written Y or N, or true or false.', '1.8.13.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bd24eb54-a480-557a-ba19-da2688e32526', 0, 'analytic', 'xva', 'mporCashFlowMode', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''mporCashFlowMode'']', 162, 'string', false, 'MPoR cash flow mode', 'NonePay, BothPay, WePay, TheyPay or Unspecified.', 'Sets the assumption about who pays the cash flows inside the margin period of risk. NonePay assumes no payment, BothPay assumes that both parties pay, WePay that only we pay, and TheyPay that only the counterparty pays. With Unspecified, ORE assumes NonePay if the simulation uses a sticky close-out date and BothPay otherwise.', 'Unspecified', 'One of NonePay, BothPay, WePay, TheyPay or Unspecified.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b6e5289b-d22b-5f83-a782-7faadcb4ec97', 0, 'analytic', 'xva', 'exposureProfilesUseCloseOutValues', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''exposureProfilesUseCloseOutValues'']', 163, 'boolean', false, 'Exposure profiles use close-out values', 'A flag. Y uses the close-out values.', 'Decides whether the exposure profiles use the close-out value of a trade, which is its value at the end of the margin period of risk, instead of its value at the default date. It needs a simulation with a close-out grid. The XVA analytic has the same parameter.', 'No. The profiles use the values at the default date.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '193fbd03-953e-5be9-b792-0be8d870b34a', 0, 'analytic', 'xva', 'writeIndividualExposureReports', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''writeIndividualExposureReports'']', 164, 'boolean', false, 'Write individual exposure reports', 'A flag. Y writes one report for each trade and netting set.', 'Decides whether the analytic writes one exposure report for each trade and for each netting set. When it is N, the analytic writes one report for all trades and one for all netting sets. Switch it off for a large portfolio to avoid a very large number of files. The XVA analytic has the same parameter.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '87188190-c6c8-5c79-b0e2-e23354548525', 0, 'analytic', 'xva', 'kva', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''kva'']', 165, 'boolean', false, 'Compute KVA', 'A flag. Y computes the capital value adjustment.', 'Switches the capital value adjustment (KVA) on or off. KVA prices the cost of the regulatory capital that the counterparty credit risk needs over the life of the trades, as the capital hurdle times the capital discounted at the capital discount rate. The KVA parameters set the capital model. Switch it on when a price must carry the cost of capital as well as the cost of credit and funding.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.4.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b725dc1e-8b8f-5eb2-a7ef-f16fc731f82c', 0, 'analytic', 'xva', 'kvaCapitalDiscountRate', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''kvaCapitalDiscountRate'']', 166, 'double', false, 'KVA capital discount rate', 'A rate, for example 0.10.', 'Sets the rate at which ORE discounts the cost of capital in the KVA. A higher rate gives a smaller KVA, because the future cost of capital counts for less. The default is 0.10, which is ten percent. ORE uses it only when KVA is on. For example, 0.08 discounts the cost of capital at eight percent.', '0.10', 'A number, written with a decimal point.', '1.8.4.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9c0dd44a-900c-527e-8e48-322bd55cbcf6', 0, 'analytic', 'xva', 'kvaAlpha', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''kvaAlpha'']', 167, 'double', false, 'KVA alpha', 'A number.', 'Sets the multiplier alpha of the regulatory exposure at default in the KVA calculation. The regulatory exposure at default is alpha times the expected positive exposure, and the Basel rules fix alpha at 1.4. Change it only to test a different rule. ORE uses it only when KVA is on.', '1.4', 'A number, written with a decimal point.', '1.8.4.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '344d7e46-7b0a-54d6-8bc2-3b7470a60cad', 0, 'analytic', 'xva', 'kvaRegAdjustment', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''kvaRegAdjustment'']', 168, 'double', false, 'KVA regulatory adjustment', 'A number.', 'Sets the regulatory adjustment factor that turns the capital requirement into risk weighted assets in the KVA calculation. The default is 12.5, the inverse of the eight percent capital ratio. Change it only to follow a different capital ratio. ORE uses it only when KVA is on. For example, 10 follows a ratio of ten percent.', '12.5', 'A number, written with a decimal point.', '1.8.4.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '62bcc9a6-d0c6-5042-b67c-cd178364fe1e', 0, 'analytic', 'xva', 'kvaCapitalHurdle', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''kvaCapitalHurdle'']', 169, 'double', false, 'KVA capital hurdle', 'A rate, for example 0.012.', 'Sets the return on capital that the KVA charges, the capital hurdle rate. The default is 0.012, which is 1.2 percent. A higher hurdle gives a larger KVA, because each unit of capital must earn more. ORE uses it only when KVA is on. For example, 0.02 charges two percent.', '0.012', 'A number, written with a decimal point.', '1.8.4.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a4a2b8e1-109c-5d55-9e99-819fd64996ec', 0, 'analytic', 'xva', 'kvaOurPdFloor', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''kvaOurPdFloor'']', 170, 'double', false, 'KVA floor on our default probability', 'A probability.', 'Sets the lowest default probability that the KVA uses for us. A very safe name has a default probability near zero, which would make the capital charge too low, so the floor lifts it. The default is 0.03. ORE uses it only when KVA is on. For example, 0.0003 sets a floor of three basis points.', '0.03', 'A number, written with a decimal point.', '1.8.4.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3407b7be-5ca4-5542-96de-a7a81664e5dd', 0, 'analytic', 'xva', 'kvaTheirPdFloor', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''kvaTheirPdFloor'']', 171, 'double', false, 'KVA floor on their default probability', 'A probability.', 'Sets the lowest default probability that the KVA uses for the counterparty. A very safe counterparty has a default probability near zero, which would make the capital charge too low, so the floor lifts it. The default is 0.03. ORE uses it only when KVA is on. For example, 0.0003 sets a floor of three basis points.', '0.03', 'A number, written with a decimal point.', '1.8.4.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f0277cc4-98f7-5cf0-8334-1033ccbba5f0', 0, 'analytic', 'xva', 'kvaOurCvaRiskWeight', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''kvaOurCvaRiskWeight'']', 172, 'double', false, 'KVA CVA risk weight for us', 'A number.', 'Sets the CVA risk weight that the KVA applies to our own credit in the capital part of the calculation. A higher weight gives a larger capital charge and so a larger KVA. The default is 0.05. ORE uses it only when KVA is on. For example, 0.03 lowers the charge.', '0.05', 'A number, written with a decimal point.', '1.8.4.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7081da6f-a06a-5ef6-a205-775ed4bf01fc', 0, 'analytic', 'xva', 'kvaTheirCvaRiskWeight', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''kvaTheirCvaRiskWeight'']', 173, 'double', false, 'KVA CVA risk weight for them', 'A number.', 'Sets the CVA risk weight that the KVA applies to the credit of the counterparty in the capital part of the calculation. A higher weight gives a larger capital charge and so a larger KVA. The default is 0.05. ORE uses it only when KVA is on. For example, 0.08 raises the charge for a counterparty of lower quality.', '0.05', 'A number, written with a decimal point.', '1.8.4.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b17c2a90-6806-580b-8deb-38e5a8ad2004', 0, 'analytic', 'xva', 'cvaSensi', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''cvaSensi'']', 174, 'boolean', false, 'CVA sensitivities', 'A flag. Y computes the CVA sensitivities.', 'Decides whether the analytic computes the sensitivity of the CVA to the credit spreads of the counterparties, one number for each tenor of the grid. Use it to hedge the credit risk of the CVA with credit default swaps. The CVA sensitivity grid sets the tenors and the shift size sets the bump. The calculation bumps each spread and runs the CVA again, so the run takes longer.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c30e7d4c-00fb-5a08-b6f4-9baaeec2412b', 0, 'analytic', 'xva', 'cvaSensiGrid', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''cvaSensiGrid'']', 175, 'string', false, 'CVA sensitivity grid', 'A comma-separated list of periods.', 'Lists the tenors of the credit spread curve for which the analytic computes the CVA sensitivity. The analytic bumps the spread at each tenor and reports the change of the CVA. For example, 6M,1Y,2Y,3Y,5Y,10Y gives six sensitivities for each counterparty. More tenors give a finer hedge and a longer run. ORE uses it only when CVA sensitivities are on.', 'None.', 'A comma-separated list of periods such as 1Y,5Y.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fb2183c3-dfd4-590a-a23a-ca03c73393bd', 0, 'analytic', 'xva', 'cvaSensiShiftSize', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''cvaSensiShiftSize'']', 176, 'double', false, 'CVA sensitivity shift size', 'A number.', 'Sets the size of the bump of the credit spread in the CVA sensitivity calculation. The default is 0.0001, which is one basis point. A smaller bump follows the slope of the CVA more closely, and a larger bump is steadier when the result is noisy. ORE uses it only when CVA sensitivities are on.', '0.0001', 'A number, written with a decimal point.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd76e962b-6f61-5cb2-afea-d0748f60f075', 0, 'analytic', 'xva', 'rawCubeOutput', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''rawCubeOutput'']', 177, 'boolean', false, 'Write the raw cube report', 'A flag. Y writes the report.', 'Decides whether the analytic writes the trade NPV cube as a text report. The cube holds the NPV of each trade on each date and path, so the file is very large for a real portfolio. Use it to check a small test case. A value in Raw cube report file also switches the report on and sets its name. Without a name the file is rawcube.csv.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd1329dbc-1bc8-5e78-8f3a-d4c292fea976', 0, 'analytic', 'xva', 'netCubeOutput', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''netCubeOutput'']', 178, 'boolean', false, 'Write the net cube report', 'A flag. Y writes the report.', 'Decides whether the analytic writes the aggregated NPV cube as a text report. The net cube holds the netted and collateralised exposure of each netting set on each date and path. It is smaller than the raw cube. A value in Net cube report file also switches the report on and sets its name. Without a name the file is netcube.csv.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '056488bf-128e-5ac6-b55c-c5b9a77c7940', 0, 'analytic', 'xva', 'nettingSetCubeFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''nettingSetCubeFile'']', 179, 'string', false, 'Netting set cube file', 'A file name.', 'Names the netting set cube file that the XVA analytic reads when the run has no simulation of its own. It is the file that an earlier simulation wrote, so the XVA step can run again without the cost of the simulation. Use it to try other XVA settings on the same exposures, for example another set of CVA flags or another DIM quantile. For example, nettingSetCube.csv.gz reads the cube from that file in the output path. The cube must come from the same portfolio and the same valuation date.', 'None.', 'A file name. ORE looks for the file in the output path of the Setup block.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eeaf29c5-2d44-524f-9fc3-b6912791e3c2', 0, 'analytic', 'xva', 'cptyCubeFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xva'']/Parameter[@name=''cptyCubeFile'']', 180, 'string', false, 'Counterparty cube file', 'A file name.', 'Names the counterparty cube file that the XVA analytic reads when the run has no simulation. The cube holds the survival probabilities for the dynamic credit calculation. It is the file that an earlier simulation wrote. For example, cptyCube.csv.gz.', 'None.', 'A file name. ORE looks for the file in the output path of the Setup block.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f6c6032a-44da-59cf-b5c8-88be257c269f', 0, 'analytic', 'xvaSensitivity', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaSensitivity'']/Parameter[@name=''active'']', 181, 'boolean', true, 'Run the XVA sensitivity analytic', 'A flag. Y runs the analytic.', 'Switches the XVA sensitivity analytic on or off. When it is on, the run computes the sensitivities of the value adjustments and the exposures by bump and revalue: it shifts each risk factor and runs the XVA calculation again. The analytic has no settings of its own for the exposure and the XVA. It reuses those of the simulation and XVA analytics, which you can switch off.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '79c7ca67-a945-5a02-ac66-3b1d748f98ad', 0, 'analytic', 'xvaSensitivity', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaSensitivity'']/Parameter[@name=''marketConfigFile'']', 182, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market under which the analytic computes its results. The analytic needs only the part under Market. The analytic replaces the market of the valuation date in the exposure simulation with this simulation market. For example, simulation.xml. The simulation market behaves differently from the market of the valuation date for some risk factors, for example it can use other curve tenors or only the at-the-money swaption volatilities. To reduce the difference, switch on UseSpreadedTermStructures in the scenario setup and simulate the swaption volatility.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3ea2bb05-b591-5f1b-a5b0-6385af424fb1', 0, 'analytic', 'xvaSensitivity', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaSensitivity'']/Parameter[@name=''sensitivityConfigFile'']', 183, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file that sets the sensitivity calculation: the risk factors, the shift types and sizes, and the par conversion. The analytic uses the same file format as the sensitivity analytic, so a file can serve both. A risk factor that the file does not list gets no XVA sensitivity. For example, sensitivity.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '21cc364a-5b49-51fc-a244-a35761d7335f', 0, 'analytic', 'xvaSensitivity', 'outputSensitivityThreshold', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaSensitivity'']/Parameter[@name=''outputSensitivityThreshold'']', 184, 'double', false, 'Sensitivity output threshold', 'A number.', 'Sets the smallest absolute value that the analytic writes. It drops every finite difference below the number from the output files. A larger value gives smaller files and hides the noise of the finite differences. The default is 0.000001. For example, 0.01 keeps only the sensitivities that change the XVA by one cent or more.', '0.000001', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'feac5c17-df90-5e88-8d44-f9b08ad884b8', 0, 'analytic', 'xvaSensitivity', 'parSensitivity', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaSensitivity'']/Parameter[@name=''parSensitivity'']', 185, 'boolean', false, 'Par sensitivities', 'A flag. Y also writes par sensitivities.', 'Decides whether the analytic converts the raw sensitivities of the XVA into sensitivities to par rates and writes them in an extra report. Par sensitivities relate to the quotes that a desk hedges with, for example the par rate of a swap, so they are the numbers a trader uses. The sensitivity configuration file must have par conversion sections. The default is Yes.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2e4339df-fec8-5983-b7d6-95ddec194fd9', 0, 'analytic', 'xvaSensitivity', 'outputJacobi', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaSensitivity'']/Parameter[@name=''outputJacobi'']', 186, 'boolean', false, 'Write the Jacobi matrices', 'A flag. Y writes the matrices.', 'Decides whether the analytic writes the Jacobi matrix and its inverse, which convert between raw and par sensitivities, to files. Use the files to check the par conversion, or to convert other raw sensitivities yourself. The two file name parameters set the names. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a413f38c-4949-5f97-8c7a-381d55dee8c8', 0, 'analytic', 'xvaSensitivity', 'jacobiOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaSensitivity'']/Parameter[@name=''jacobiOutputFile'']', 187, 'string', false, 'Jacobi matrix file', 'A file name.', 'Names the file for the Jacobi matrix, which converts a raw shift into the par shifts of the quotes. It has an effect only when Write the Jacobi matrices is on. The default is xva_sensi_jacobi.csv, written in the output path. Change it when one run writes more than one set of reports.', 'xva_sensi_jacobi.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '92b24f0d-8d33-5975-8242-decda3127dc6', 0, 'analytic', 'xvaSensitivity', 'jacobiInverseOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaSensitivity'']/Parameter[@name=''jacobiInverseOutputFile'']', 188, 'string', false, 'Inverse Jacobi matrix file', 'A file name.', 'Names the file for the inverse Jacobi matrix, which converts a par shift into the raw shifts of the market. It has an effect only when Write the Jacobi matrices is on. The default is xva_sensi_jacobi_inverse.csv, written in the output path. Change it when one run writes more than one set of reports.', 'xva_sensi_jacobi_inverse.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7eb566f0-adba-5c4d-84d2-7633e4945928', 0, 'analytic', 'xvaSensitivity', 'outputPrecision', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaSensitivity'']/Parameter[@name=''outputPrecision'']', 189, 'integer', false, 'Sensitivity output precision', 'A whole number of decimal places.', 'Sets the number of decimal places of the numbers in the XVA sensitivity reports. A higher number shows more of each value and makes the files larger. The default is 4. For example, 8 shows small sensitivities such as 0.00001234 in full.', '4', 'A whole number of zero or more.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5b121aab-592d-5fb3-8e02-1ebc181df332', 0, 'analytic', 'xvaExplain', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaExplain'']/Parameter[@name=''active'']', 190, 'boolean', true, 'Run the XVA explain analytic', 'A flag. Y runs the analytic.', 'Switches the XVA explain analytic on or off. When it is on, the run computes the change of the value adjustments that the market moves between two dates imply: the XVA with the market data of the second date minus the XVA with the market data of the first, both at the exposure of the first date. The output has the value adjustments under each shifted risk factor and a CVA explain report. The analytic has no settings of its own for the exposure and the XVA. It reuses those of the simulation and XVA analytics, which you can switch off.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '09df5923-ff7d-539b-9973-636c48a795a4', 0, 'analytic', 'xvaExplain', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaExplain'']/Parameter[@name=''marketConfigFile'']', 191, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market under which the analytic computes its results. The analytic needs only the part under Market. The analytic replaces the market of the valuation date in the exposure simulation with this simulation market. For example, simulation.xml. The simulation market behaves differently from the market of the valuation date for some risk factors, for example it can use other curve tenors or only the at-the-money swaption volatilities. To reduce the difference, switch on UseSpreadedTermStructures in the scenario setup and simulate the swaption volatility.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4c66b58d-718a-5a7d-94a2-c8f539eddd0f', 0, 'analytic', 'xvaExplain', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaExplain'']/Parameter[@name=''sensitivityConfigFile'']', 192, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file that lists the risk factors to explain. For each risk factor of the file, ORE computes the change of its par rate between the first date and the second date. It builds a shift scenario from the change and computes the CVA change that the shift implies. For example, sensitivity_stress.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '10dd799a-557d-5a57-8053-2b94c5b90e53', 0, 'analytic', 'xvaExplain', 'writeCubes', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaExplain'']/Parameter[@name=''writeCubes'']', 193, 'boolean', false, 'Write the cubes', 'A flag. ORE ignores it in the xvaExplain block.', 'The user guide lists this parameter for the XVA explain analytic, but ORE reads it only for the XVA stress analytic. A value here has no effect in release 1.8.17.0.', 'No. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '21390819-2b6d-53a2-a065-ceb3ea749898', 0, 'analytic', 'xvaExplain', 'shiftThreshold', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaExplain'']/Parameter[@name=''shiftThreshold'']', 194, 'double', false, 'Par rate shift threshold', 'A number.', 'Sets the smallest par rate shift that the analytic uses. It ignores every shift below this number, so a small move of the market does not enter the explanation. The default is 0, so the analytic ignores no shift. For example, 1e-4 ignores shifts smaller than one basis point.', '0. The analytic ignores no shift.', 'A number, written with a decimal point.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '845ce624-e4e1-558c-8dda-45069fae45ea', 0, 'analytic', 'xvaExplain', 'mporDays', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaExplain'']/Parameter[@name=''mporDays'']', 195, 'integer', false, 'Days to the second date', 'A whole number of days.', 'Sets the number of days from the valuation date to the second evaluation date. The analytic derives the second date from the valuation date plus this number of days, and rolls it to a business day with the calendar. The parameter MPoR date sets the date directly. For example, 1 explains the move of one day.', '10', 'A whole number of zero or more.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1c228400-4d91-52d4-b5c6-ee241945ac88', 0, 'analytic', 'xvaExplain', 'mporCalendar', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaExplain'']/Parameter[@name=''mporCalendar'']', 196, 'string', false, 'Calendar of the second date', 'A calendar name.', 'Names the calendar that ORE uses to make sure that the second evaluation date is a business day. If the date falls on a holiday of the calendar, ORE moves it. Use the calendar of the market of the portfolio. For example, EUR. When it is missing, ORE takes the calendar of the base currency.', 'The calendar of the base currency.', 'A calendar name such as TARGET, EUR or UK.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '31b0d6b1-ad2e-505d-b417-2431bc73554a', 0, 'analytic', 'xvaExplain', 'stressConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaExplain'']/Parameter[@name=''stressConfigFile'']', 197, 'string', false, 'Stress configuration file', 'A file name. ORE ignores it in the xvaExplain block.', 'The user guide lists this parameter for the XVA explain analytic, but the analytic reads the risk factors from the sensitivity configuration file. A value here has no effect in release 1.8.17.0.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e0e8a5f4-0ceb-5137-b98f-9de456ad1984', 0, 'analytic', 'xvaExplain', 'mporDate', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaExplain'']/Parameter[@name=''mporDate'']', 198, 'date', false, 'Second evaluation date', 'A date.', 'Sets the second evaluation date directly, instead of deriving it from the number of days. The analytic explains the change of the XVA between the valuation date and this date. For example, 2026-03-02. When it is missing, ORE derives the date from the number of days and the calendar.', 'None. ORE derives the date from the number of days.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2976adee-5dc8-5997-9dee-a60c7ee2906f', 0, 'analytic', 'bacva', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''bacva'']/Parameter[@name=''active'']', 199, 'boolean', true, 'Run the BA-CVA analytic', 'A flag. Y runs the analytic.', 'Switches the basic approach for the CVA capital (BA-CVA) on or off. The calculation uses the SA-CCR analytic under it to compute the exposures at default, and then applies the supervisory formula of the basic approach. It needs the netting set definitions and the collateral balances.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '47ab3666-413a-52ac-bf79-466ceb2bfcec', 0, 'analytic', 'bacva', 'simmVersion', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''bacva'']/Parameter[@name=''simmVersion'']', 200, 'double', false, 'SIMM version', 'A SIMM version, for example 2.6.', 'Names the version of the SIMM that the calculation uses for the name and bucket mapping of commodity hedging sets. Use the version that the firm has adopted, for example 2.6. The run stops if the version is empty. The parameter is mandatory.', 'None. The parameter is mandatory.', 'A SIMM version such as 2.4, 2.5A, 2.6 or 2.7.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4b6fa9a0-290b-50bc-acd3-cef26886a683', 0, 'analytic', 'bacva', 'csaFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''bacva'']/Parameter[@name=''csaFile'']', 201, 'string', false, 'Netting set definitions file', 'A file name.', 'Names the XML file with the netting set definitions, as in the XVA analytics. The file holds the margin agreements, such as the threshold and the minimum transfer amount, that the exposure at default depends on. For example, netting.xml. The analytic needs this file here or in the Setup block.', 'None. The analytic needs this file, here or in the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '94fbb872-7ec9-5421-a7a5-47c9f63f4992', 0, 'analytic', 'bacva', 'collateralBalancesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''bacva'']/Parameter[@name=''collateralBalancesFile'']', 202, 'string', false, 'Collateral balances file', 'A file name.', 'Names the XML file with the variation margin and initial margin balances of the valuation date. The SA-CCR analytic under the analytic reads the file. The balances reduce the exposure at default of each netting set. For example, collateralbalances.xml.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '41e05bd3-eb46-5f68-9285-e5086e219608', 0, 'analytic', 'bacva', 'nameMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''bacva'']/Parameter[@name=''nameMappingInputFile'']', 203, 'string', false, 'Name mapping file', 'A file name.', 'Names the file that maps the names in the portfolio to the SIMM names for the hedging sets, for example a trade name to an issuer. Use it when the names of the portfolio differ from the names of the SIMM. Without it ORE uses the names as they are.', 'None. ORE uses the names as they are.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3f25fc2a-daa3-5249-a665-f661b45053e2', 0, 'analytic', 'bacva', 'bucketMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''bacva'']/Parameter[@name=''bucketMappingInputFile'']', 204, 'string', false, 'Bucket mapping file', 'A file name.', 'Names the file that maps risk factors to the SIMM buckets for the hedging sets. The bucket decides the risk weight that the hedging set gets. Without it ORE uses the standard buckets.', 'None. ORE uses the standard SIMM buckets.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a1fc4246-d9f7-5993-ab9f-1f2c0ae7ae55', 0, 'analytic', 'xvaStress', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaStress'']/Parameter[@name=''active'']', 205, 'boolean', true, 'Run the XVA stress analytic', 'A flag. Y runs the analytic.', 'Switches the XVA stress analytic on or off. When it is on, the run computes the value adjustments and exposures under each stress scenario and writes them next to the base results. Use it to see how the XVA reacts to a market shock. The analytic has no settings of its own for the exposure and the XVA. It reuses those of the simulation and XVA analytics, which you can switch off. For speed, use AMC in the simulation.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '112b009c-eaf4-5b2f-bb71-5d5c7602192b', 0, 'analytic', 'xvaStress', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaStress'']/Parameter[@name=''marketConfigFile'']', 206, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market under which the analytic computes its results. The analytic needs only the part under Market. The analytic replaces the market of the valuation date in the exposure simulation with this simulation market. For example, simulation.xml. The simulation market behaves differently from the market of the valuation date for some risk factors, for example it can use other curve tenors or only the at-the-money swaption volatilities. To reduce the difference, switch on UseSpreadedTermStructures in the scenario setup and simulate the swaption volatility.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '60f57532-80a1-508e-8a16-0a04bf225e86', 0, 'analytic', 'xvaStress', 'stressConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaStress'']/Parameter[@name=''stressConfigFile'']', 207, 'string', false, 'Stress configuration file', 'A file name.', 'Names the XML file with the stress scenarios in the format of the NPV stress test. The analytic runs the XVA calculation once for each scenario in the file and reports the XVA of each. For example, stresstest.xml. The analytic needs this file.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6393e4e4-6328-57cc-a6d8-a87b24d4899d', 0, 'analytic', 'xvaStress', 'writeCubes', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaStress'']/Parameter[@name=''writeCubes'']', 208, 'boolean', false, 'Write the cubes under each scenario', 'A flag. Y writes the cubes.', 'Decides whether the analytic writes the raw cube and the net cube for each stress scenario. The files can be very large, because a cube is written for each scenario. Use it to inspect the exposures of one scenario. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7357d102-2911-53e4-a005-a9f84cd6cd14', 0, 'analytic', 'xvaStress', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaStress'']/Parameter[@name=''sensitivityConfigFile'']', 209, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file that sets the sensitivity calculation, in particular the par conversion that a par stress test needs. The conversion turns a shift of par rates into the equivalent shift of the model. Without it, ORE supports no par stress test and the stress file must be in the raw domain. For example, sensitivity_stress.xml.', 'None. Par stress tests are not supported.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4dcc3b76-709b-5671-8a07-d1550b53e527', 0, 'analytic', 'xvaStress', 'scenarioOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''xvaStress'']/Parameter[@name=''scenarioOutputFile'']', 210, 'string', false, 'Stress scenario output file', 'A file name.', 'Names the file for the report of the XVA stress scenarios: the XVA under the base market and under each stress scenario, and their differences. The default is xva_stress.csv, written in the output path.', 'xva_stress.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dd0a66a8-e092-5faf-9431-f87d39064c63', 0, 'analytic', 'sacva', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''active'']', 211, 'boolean', true, 'Run the SA-CVA analytic', 'A flag. Y runs the analytic.', 'Switches the standardised approach for the CVA capital (SA-CVA) on or off. The calculation is based on CVA sensitivities. ORE can compute them on the fly, with the XVA sensitivity analytic and the simulation and XVA analytics under it, or read them from a file. The run stops if no sensitivity file is given and the XVA sensitivity analytic is missing.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4a63b741-379e-5d7d-a21b-13fdb5b80f01', 0, 'analytic', 'sacva', 'csaFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''csaFile'']', 212, 'string', false, 'Netting set definitions file', 'A file name.', 'Names the XML file with the netting set definitions. ORE looks for the file name in the sacva block, then in the bacva block and last in the Setup block. The SA-CVA analytic passes the value on to the simulation analytic that runs under it.', 'The netting set definitions file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'de00ebb4-5220-58c1-942d-ee4a7a216b15', 0, 'analytic', 'sacva', 'counterpartyFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''counterpartyFile'']', 213, 'string', false, 'Counterparty file', 'A file name.', 'Names the XML file with the counterparty information that the SA-CVA calculator needs, such as the credit quality and the sector of each counterparty. ORE looks for the file name in the sacva block, then in the bacva block and last in the Setup block. A value here replaces the others.', 'The counterparty file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8d96757f-a44e-5f51-baef-55c47c1e9221', 0, 'analytic', 'sacva', 'simulationConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''simulationConfigFile'']', 214, 'string', false, 'Simulation configuration file', 'A file name.', 'Names the XML file with the simulation configuration for the exposure simulation under the analytic. The SA-CVA analytic passes the value on to the simulation analytic that runs under it, so the file sets the model, the grid and the number of samples of that simulation.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '52003c28-ff7e-5b70-993b-f350505b9b8c', 0, 'analytic', 'sacva', 'scenarioGeneratorData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''scenarioGeneratorData'']', 215, 'string', false, 'Scenario generator file', 'A file name.', 'Names the XML file with the scenario generator for the simulation under the analytic. Without it the simulation uses its own defaults, for example 1000 samples. The SA-CVA analytic passes the value on to the simulation analytic that runs under it.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3c49a9d3-121e-5a44-b849-abc1b6fa5319', 0, 'analytic', 'sacva', 'crossAssetModelData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''crossAssetModelData'']', 216, 'string', false, 'Cross asset model file', 'A file name.', 'Names the XML file with the cross asset model for the simulation under the analytic. The SA-CVA analytic passes the value on to the simulation analytic that runs under it. Use it when the model sits in another file than the simulation configuration file.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c822e725-04b9-5010-975b-d0486c977772', 0, 'analytic', 'sacva', 'dimModel', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''dimModel'']', 217, 'string', false, 'DIM model', 'A DIM model name, for example DeltaVaR.', 'Selects the dynamic initial margin model for the XVA analytic under the SA-CVA analytic, and switches DIM on. The names are those of the DIM model parameter of the XVA analytic. Without a value the XVA analytic under SA-CVA uses no DIM, and the run is faster.', 'None. The XVA analytic under SA-CVA uses no DIM.', 'One of the DIM models of the XVA analytic.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8a62898e-428f-530a-9284-e4f25d1a2cb0', 0, 'analytic', 'sacva', 'dimScaling', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''dimScaling'']', 218, 'double', false, 'DIM scaling', 'A number.', 'Sets the scaling factor for the DIM values of the XVA analytic under the SA-CVA analytic. The factor scales the projected margin so that it agrees with the margin that the firm posts today. When it is missing, the XVA analytic derives the factor from the initial margin of the collateral balances file.', 'None.', 'A number, written with a decimal point.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '56fdf5ba-1bef-5d6b-8d02-fcf526f28362', 0, 'analytic', 'sacva', 'collateralBalancesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''collateralBalancesFile'']', 219, 'string', false, 'Collateral balances file', 'A file name.', 'Names the XML file with the current variation margin and initial margin balances. ORE passes it on to the XVA analytic under the SA-CVA analytic, which derives the DIM scaling from it when DIM scaling is missing. For example, collateralbalances.xml.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cf27a91c-2dd2-526b-946b-bf46d0d19786', 0, 'analytic', 'sacva', 'storeSensis', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''storeSensis'']', 220, 'boolean', false, 'Store sensitivities along the paths', 'A flag. Y stores the sensitivities.', 'Decides whether the simulation under the SA-CVA analytic stores sensitivities along the paths, which the DIM model needs. The SA-CVA analytic passes the value on to the simulation analytic that runs under it. Storing makes the cube larger and the run longer. Switch it on only when a DIM model is set.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '07934b76-2ca4-593b-b548-02945452559a', 0, 'analytic', 'sacva', 'xvaSensiSimMarketParams', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''xvaSensiSimMarketParams'']', 221, 'string', false, 'XVA sensitivity simulation market', 'A file name.', 'Names the XML file with the simulation market for the XVA sensitivity analytic that runs under the SA-CVA analytic. The file says which risk factors the market holds and on which tenors, so it decides the points of the CVA sensitivities.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f6fe474d-d33b-5f4f-be58-094a49908666', 0, 'analytic', 'sacva', 'xvaSensiScenarioData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''xvaSensiScenarioData'']', 222, 'string', false, 'XVA sensitivity scenario file', 'A file name.', 'Names the XML file with the sensitivity scenarios for the XVA sensitivity analytic that runs under the SA-CVA analytic. The file sets the shift of each risk factor, so it decides the size of the bumps behind the CVA sensitivities.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c79664c8-eb83-5e81-a8ec-a535598f190f', 0, 'analytic', 'sacva', 'saCvaNetSensitivitiesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''saCvaNetSensitivitiesFile'']', 223, 'string', false, 'Net sensitivities file', 'A file name.', 'Names a file with net sensitivities that ORE passes directly to the SA-CVA calculator. When it is set, ORE computes no sensitivities, so the run is fast. Use it when another system supplies the CVA sensitivities. For example, sacva_sensitivity.csv.', 'None. ORE computes the sensitivities or reads the CVA sensitivities file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '63357fb1-f14d-5fbb-89ee-36473446456a', 0, 'analytic', 'sacva', 'cvaSensitivitiesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''cvaSensitivitiesFile'']', 224, 'string', false, 'CVA sensitivities file', 'A file name.', 'Names a file with CVA sensitivities, the output of the XVA sensitivity analytic. ORE maps and aggregates them before the calculation. ORE reads it only when no net sensitivities file is given. For example, xva_par_sensitivity_cva.csv.', 'None. ORE computes the sensitivities.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f7a97a57-8c63-5c33-b45f-b6990aaf0f2b', 0, 'analytic', 'sacva', 'nameMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''nameMappingInputFile'']', 225, 'string', false, 'Name mapping file', 'A file name.', 'Names the file that maps the names in the portfolio to the names that the SA-CVA calculator uses, for example the name of an issuer to its sector and bucket. Use it when the names of the portfolio differ from the names of the calculator. Without it ORE uses the names as they are.', 'None. ORE uses the names as they are.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5eb614d7-24a6-51f8-965b-7f6cb1d02452', 0, 'analytic', 'sacva', 'curveSensiGrid', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''curveSensiGrid'']', 226, 'string', false, 'Curve sensitivity grid', 'A comma-separated list of numbers of years.', 'Lists the points on the yield curves for which the simulation stores sensitivities. Each number is a tenor in years. The SA-CVA analytic passes the value on to the simulation analytic that runs under it. For example, 1,2,3,5,7,10,15,20 stores the sensitivity to eight points of each curve.', 'None.', 'A comma-separated list of numbers of years.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '53dd7e1b-9f9f-5ce4-916b-7855d2150e8a', 0, 'analytic', 'sacva', 'vegaSensiGrid', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sacva'']/Parameter[@name=''vegaSensiGrid'']', 227, 'string', false, 'Vega sensitivity grid', 'A comma-separated list of numbers of years.', 'Lists the option expiries for which the simulation stores vega sensitivities. The SA-CVA analytic passes the value on to the simulation analytic that runs under it. Each number is an expiry in years. For example, 1,2,3,5,7,10,15,20.', 'None.', 'A comma-separated list of numbers of years.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4f0d0ad5-788f-585c-af64-715487e83d19', 0, 'analytic', 'zeroToParShift', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParShift'']/Parameter[@name=''active'']', 228, 'boolean', true, 'Run the zero to par shift conversion', 'A flag. Y runs the analytic.', 'Switches the zero to par shift conversion on or off. The analytic converts the zero rate shifts of a stress test into the par rate shifts that give the same market, and writes them to a file.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '48981566-19ff-5e0a-ad90-0c7351eae018', 0, 'analytic', 'zeroToParShift', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParShift'']/Parameter[@name=''marketConfigFile'']', 229, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market under which the analytic computes its results. The simulation market lists the risk factors that ORE can shift, for example the discount curves, the FX spots and the volatility surfaces, and the tenors of each. The analytic needs only the part under Market and ignores the model and the scenario generator. A risk factor that this file leaves out cannot be shifted. For example, simulation.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bd02007f-f8cb-52ba-aa4e-ff4d9fa4acd9', 0, 'analytic', 'zeroToParShift', 'stressConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParShift'']/Parameter[@name=''stressConfigFile'']', 230, 'string', false, 'Stress configuration file', 'A file name.', 'Names the XML file with the stress scenarios. Each scenario lists the shifts of the risk factors, for example a parallel move of a yield curve by 100 basis points. The same file also decides whether the stress is in the raw domain, which shifts the zero rates, or in the par domain, which shifts the par rates. For example, stresstest.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0482f920-6d15-5dca-af10-918f11b316d4', 0, 'analytic', 'zeroToParShift', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParShift'']/Parameter[@name=''sensitivityConfigFile'']', 231, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file with the sensitivity setup, in particular the par conversion sections. The sections list the par instruments that define each curve, so the conversion can map a zero shift to par shifts. For example, sensitivity.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c8ef585a-c87d-5aba-bfc6-b6dd73924e10', 0, 'analytic', 'zeroToParShift', 'pricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParShift'']/Parameter[@name=''pricingEnginesFile'']', 232, 'string', false, 'Pricing engines file', 'A file name.', 'Names the XML file that sets the pricing engines for the analytic. The file says which model and which engine price each product, so a change here changes the NPVs behind the results. When it is missing, ORE uses the pricing engines file of the Setup block. Use it to run the analytic with other engines than the rest of the run. For example, pricingengine.xml.', 'The pricing engines file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c507a005-6fb6-5703-bade-65f7b6610fe0', 0, 'analytic', 'zeroToParShift', 'scenarioOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParShift'']/Parameter[@name=''scenarioOutputFile'']', 233, 'string', false, 'Scenario output file', 'A file name. ORE ignores it.', 'ORE does not read this parameter for the zero to par shift conversion. Example files carry it. The par shifts file names the output.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8e36fdac-2eb6-5adf-9b5a-f0ffa8fb44d8', 0, 'analytic', 'zeroToParShift', 'parShiftsFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParShift'']/Parameter[@name=''parShiftsFile'']', 234, 'string', false, 'Par shifts file', 'A file name.', 'Names the file that receives the par rate shifts that the conversion finds. Each row is a par instrument with its shift. The default is parshifts.csv, written in the output path. For example, parshifts.csv.', 'parshifts.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '76b71ddd-675e-5b41-a28b-f04311d2e663', 0, 'analytic', 'additionalResults', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''additionalResults'']/Parameter[@name=''active'']', 235, 'boolean', true, 'Run the additional results analytic', 'A flag. Y runs the analytic.', 'Switches the additional results analytic on or off. When it is on, the run writes a report with the results that the pricing engines compute besides the NPV, for example the annuity, the forward rate and the standard deviation of a swaption. What a trade returns depends on its pricing engine. Use it to check how an engine reached an NPV.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '71d2bf6d-0f10-5cb0-8f15-f4e2fa9a81df', 0, 'analytic', 'additionalResults', 'outputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''additionalResults'']/Parameter[@name=''outputFileName'']', 236, 'string', false, 'Additional results report file', 'A file name.', 'Is meant to name the file that holds the additional results. ORE does not read it. The report always has the name additional_results.csv, whatever this parameter says, and has one row for each result of each trade with the trade, the name of the result, its type and its value. Example files carry the parameter.', 'additional_results.csv. ORE ignores the parameter, so the name is always this one.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e34c7d43-7c8a-5a52-baf2-77b1fcc3449a', 0, 'analytic', 'additionalResults', 'additionalResultsReportPrecision', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''additionalResults'']/Parameter[@name=''additionalResultsReportPrecision'']', 237, 'integer', false, 'Additional results precision', 'A whole number of decimal places.', 'Sets the number of decimal places of the numbers in the additional results report. A higher value shows more of each result and makes the file larger. For example, 12 writes a result such as 0.016641350123. ORE reads this parameter first. The NPV analytic has a parameter of the same name that ORE reads only when this one is missing.', '6', 'A whole number of zero or more.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '397f40bc-7189-50a4-ae59-b3ebde1922e6', 0, 'analytic', 'sensitivity', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''active'']', 238, 'boolean', true, 'Run the sensitivity analytic', 'A flag. Y runs the analytic.', 'Switches the sensitivity analytic on or off. When it is on, it shifts each risk factor of the sensitivity configuration file in turn, revalues the portfolio and writes the change of the NPV for each trade. Use N to keep the entry in the document without running it.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd8ec2ea7-f3aa-5fee-97f5-b3c9c697856e', 0, 'analytic', 'sensitivity', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''marketConfigFile'']', 239, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market under which the analytic computes its results. The simulation market lists the risk factors that ORE can shift, for example the discount curves, the FX spots and the volatility surfaces, and the tenors of each. The analytic needs only the part under Market and ignores the model and the scenario generator. A risk factor that this file leaves out cannot be shifted. For example, simulation.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7908d51a-6ffe-5ff6-bb33-11c22cb0d57a', 0, 'analytic', 'sensitivity', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''sensitivityConfigFile'']', 240, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file that sets the sensitivity calculation: which risk factors ORE bumps, the shift types and sizes, and the par conversion. A risk factor that the file does not list gets no sensitivity. The file is the main input of the analytic, and the shift sizes decide the finite differences. For example, sensitivity.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'db703ee7-78b3-5aec-9d10-b5e859a5bdcb', 0, 'analytic', 'sensitivity', 'pricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''pricingEnginesFile'']', 241, 'string', false, 'Pricing engines file', 'A file name.', 'Names the XML file that sets the pricing engines for the analytic. The file says which model and which engine price each product, so a change here changes the NPVs behind the results. When it is missing, ORE uses the pricing engines file of the Setup block. Use it to run the analytic with other engines than the rest of the run. For example, pricingengine.xml.', 'The pricing engines file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f3bf5c3e-92d5-59b6-9723-3d5185d60df4', 0, 'analytic', 'sensitivity', 'scenarioOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''scenarioOutputFile'']', 242, 'string', false, 'Scenario output file', 'A file name.', 'Names the file with the result of each scenario: the NPV of the base scenario, the NPV of the shifted scenario and their difference. Use it to check a sensitivity by hand, because each row is one bump of one risk factor. The default is sensitivity_scenario.csv, written in the output path.', 'sensitivity_scenario.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f22c4249-b30d-5444-84bc-211173e0e999', 0, 'analytic', 'sensitivity', 'sensitivityOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''sensitivityOutputFile'']', 243, 'string', false, 'Sensitivity output file', 'A file name.', 'Names the file with the sensitivities: the base NPV, the shift size with its risk factor, and the first and the pure second order finite differences. It also holds a second set with the mixed second order finite differences of the cross gamma.', 'sensitivity.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c22548cd-86ff-5abb-8f86-63155b7242c8', 0, 'analytic', 'sensitivity', 'crossGammaOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''crossGammaOutputFile'']', 244, 'string', false, 'Cross gamma output file', 'A file name. ORE no longer reads it.', 'Named the file for the cross gamma. ORE stopped reading it in 1.8.4.0. The cross gamma is now part of the sensitivity output file.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.2.0', '1.8.4.0'),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e6441cbe-6f17-5dc3-a4b4-1b40a1567b30', 0, 'analytic', 'sensitivity', 'outputSensitivityThreshold', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''outputSensitivityThreshold'']', 245, 'double', false, 'Sensitivity output threshold', 'A number.', 'Sets the smallest absolute value that the analytic writes. It drops every finite difference below the number from the output files, so a bump that moves no trade leaves no row. A larger value gives smaller files and hides numerical noise. The default is 0.000001. For example, 0.01 keeps only the sensitivities of one cent or more.', '0.000001', 'A number, written with a decimal point.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c849297c-63d0-5370-a55e-7b86bee146fb', 0, 'analytic', 'sensitivity', 'recalibrateModels', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''recalibrateModels'']', 246, 'boolean', false, 'Recalibrate the models', 'A flag. Y recalibrates after each shift.', 'Decides whether ORE recalibrates the pricing models after it shifts a relevant term structure. Recalibration gives sensitivities that include the model reaction, and it takes more time. When it is N, the models keep their calibration of the base scenario.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ecd931ad-7f4e-5927-a16a-cb74068358ec', 0, 'analytic', 'sensitivity', 'applySimmExemptions', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''applySimmExemptions'']', 247, 'boolean', false, 'Apply SIMM exemptions', 'A flag. ORE ignores it in the sensitivity block.', 'ORE reads this parameter in the crif analytic only. A value in the sensitivity block has no effect.', 'No. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.4.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e5de6cbb-ec8f-52a8-9e1c-5dbd6e6b796d', 0, 'analytic', 'sensitivity', 'outputProductClassMapping', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''outputProductClassMapping'']', 248, 'boolean', false, 'Output the product class mapping', 'A flag. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it.', 'No. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.4.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f52ec423-03c6-5578-a097-6abf7697991e', 0, 'analytic', 'sensitivity', 'productClassMappingOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''productClassMappingOutputFile'']', 249, 'string', false, 'Product class mapping output file', 'A file name. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.4.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e324470c-5dde-5b62-8994-1cbd9e8d2e50', 0, 'analytic', 'sensitivity', 'parSensitivity', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''parSensitivity'']', 250, 'boolean', false, 'Par sensitivities', 'A flag. Y also computes par sensitivities.', 'Decides whether ORE converts the raw sensitivities into sensitivities to par rates after the raw sensitivity analysis. Raw sensitivities are to the zero rates of the curves, and par sensitivities are to the quotes that a desk trades, such as the par rate of a swap, so they are the numbers a hedge uses. The sensitivity configuration file must have par conversion sections. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '912308b4-9dc0-5834-a17e-f22a1f72aa8c', 0, 'analytic', 'sensitivity', 'parSensitivityOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''parSensitivityOutputFile'']', 251, 'string', false, 'Par sensitivity output file', 'A file name.', 'Names the file with the par sensitivities. It has an effect only when Par sensitivities is on. The default is par_sensitivity.csv, written in the output path. Change it when one run writes more than one set of reports.', 'par_sensitivity.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2d2ec981-a8f7-5046-9d4d-9da6a726a262', 0, 'analytic', 'sensitivity', 'outputJacobi', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''outputJacobi'']', 252, 'boolean', false, 'Write the Jacobi matrices', 'A flag. Y writes the matrices.', 'Decides whether ORE writes the Jacobi matrix and its inverse, which convert between raw and par sensitivities, to files. Use the files to check the par conversion, or to convert other raw sensitivities yourself. The two file name parameters set the names. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ab8d716e-c08a-56fb-b2e8-36127592cefe', 0, 'analytic', 'sensitivity', 'jacobiOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''jacobiOutputFile'']', 253, 'string', false, 'Jacobi matrix file', 'A file name.', 'Names the file for the Jacobi matrix, which converts a raw shift into the par shifts of the quotes. It has an effect only when Write the Jacobi matrices is on. The default is jacobi.csv, written in the output path.', 'jacobi.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1aa380d4-58d6-5de0-b967-35c8b6bd45ef', 0, 'analytic', 'sensitivity', 'jacobiInverseOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''jacobiInverseOutputFile'']', 254, 'string', false, 'Inverse Jacobi matrix file', 'A file name.', 'Names the file for the inverse Jacobi matrix, which converts a par shift into the raw shifts of the market. It has an effect only when Write the Jacobi matrices is on. The default is jacobi_inverse.csv, written in the output path.', 'jacobi_inverse.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '72ccb620-2894-5583-97a7-6371cb934099', 0, 'analytic', 'sensitivity', 'parRateSensitivityOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''parRateSensitivityOutputFile'']', 255, 'string', false, 'Par rate sensitivity output file', 'A file name. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it. Use the par sensitivity output file.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '697a7939-3fae-5434-bbd8-79ae97cd13d0', 0, 'analytic', 'sensitivity', 'optimiseRiskFactors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''optimiseRiskFactors'']', 256, 'boolean', false, 'Optimise the risk factors', 'A flag. Y limits the par sensitivities to the risk factors that matter.', 'Decides whether the par sensitivity calculation uses only the risk factors that the raw sensitivity analysis found relevant for the portfolio. It makes the par conversion faster and smaller. It has an effect only when Par sensitivities is on.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '425be5ca-a21f-58ab-8b85-13d8ef780a08', 0, 'analytic', 'sensitivity', 'laxFxConversion', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''laxFxConversion'']', 257, 'boolean', false, 'Lax FX conversion', 'A flag. Y uses the spot quote of the currency pair directly.', 'Decides how ORE finds the FX rate that converts a sensitivity into the base currency. With Y, ORE uses the spot quote of the pair directly. With N, ORE uses the stricter rate lookup. Switch it on if the strict lookup fails for a currency pair that the market does not quote.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '739d2fa1-074b-5490-bc64-ed458f171729', 0, 'analytic', 'sensitivity', 'decomposeIndexSensitivities', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''decomposeIndexSensitivities'']', 258, 'boolean', false, 'Decompose index sensitivities', 'A flag. Y splits index sensitivities into their constituents.', 'Decides whether ORE decomposes the sensitivities of credit, equity and commodity indices into the sensitivities of the constituents. Credit index decomposition also needs SensitivityDecomposition in the pricing engine settings. Equity and commodity decomposition need index_decomposition in the additional fields of the trade, and reference data for the indices.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '49dd04bc-6563-5ecc-99cc-7ba4fb6eb7c7', 0, 'analytic', 'sensitivity', 'alignPillars', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''alignPillars'']', 259, 'boolean', false, 'Align the pillars', 'A flag. Y aligns the pillars with the par instruments.', 'Decides whether ORE aligns the pillars of the simulation market with those of the par instruments, so that the raw and the par sensitivities refer to the same points. Without alignment a par instrument can fall between two pillars, and the conversion then interpolates. The default follows Par sensitivities: ORE aligns the pillars when par sensitivities are on.', 'The value of Par sensitivities. Pillars are aligned when par sensitivities are on.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6e360fe6-9d7c-5d4c-ae59-1ec11b665ca2', 0, 'analytic', 'sensitivity', 'computeTheta', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''computeTheta'']', 260, 'boolean', false, 'Compute theta', 'A flag. Y computes the theta.', 'Decides whether the sensitivity calculation also computes the theta, the change of the NPV when the valuation date moves. ORE reads the parameter from the sensitivity block, the simm block or the crif block, in this order, and one value serves all three analytics.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '61fe0b96-70d0-5e33-af7e-67ad6a326f32', 0, 'analytic', 'sensitivity', 'thetaPeriod', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''thetaPeriod'']', 261, 'string', false, 'Theta period', 'A period, for example 1D.', 'Sets the length of the time step for the theta. The theta is the change of the NPV when the valuation date moves by this period, with the market unchanged. For example, 1D moves the valuation date by one day, and 1W by one week. ORE reads it only when Compute theta is on. The default is 1D.', '1D', 'A period such as 1D or 1W.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '92281ec6-1cf6-5657-9ccf-c1af17868c35', 0, 'analytic', 'sensitivity', 'outputPrecision', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivity'']/Parameter[@name=''outputPrecision'']', 262, 'integer', false, 'Sensitivity output precision', 'A whole number of decimal places.', 'Sets the number of decimal places of the sensitivities in the output files. A higher number shows more of each value and makes the files larger. The default is 2. For example, 6 shows a small sensitivity such as 0.001234 in full. Raise it when you compare two runs to find a small difference.', '2', 'A whole number of zero or more.', '1.8.6.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '217c6104-44b1-55a9-8e31-7b060b90f105', 0, 'analytic', 'calibration', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''active'']', 263, 'boolean', true, 'Run the calibration', 'A flag. Y runs the calibration.', 'Switches the model calibration on or off. When it is on, the run calibrates the simulation model and writes the calibrated model data, so that a later simulation can start from it without a new calibration. The calibration runs a part of what the simulation does.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0d571441-dc21-51bc-81cb-ce206c0b9e53', 0, 'analytic', 'calibration', 'configFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''configFile'']', 264, 'string', false, 'Model configuration file', 'A file name.', 'Names the XML file with the cross asset model data to calibrate: the currencies, the model parametrisations and the calibration instruments. This is usually the simulation configuration file. The output of the run replaces the initial values in this data with the calibrated values. For example, simulation.xml. ORE uses the file only for the CAM model.', 'None. A CAM calibration needs this file, or the parameter Cross asset model file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a6154671-5335-55b9-8b2e-f02a12580b67', 0, 'analytic', 'calibration', 'outputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''outputFile'']', 265, 'string', false, 'Calibration report file', 'A file name.', 'Names the file of the calibration report. The report holds the calibrated cross asset model as one XML string. The run also writes the model data to calibration.xml in the output path, and you can paste its model section into the simulation configuration file to run without a calibration. For example, calibration.csv.', 'calibration.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '82c32da6-e32b-5625-bef2-c80066989696', 0, 'analytic', 'calibration', 'model', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''model'']', 266, 'string', false, 'Calibration model', 'CAM or HW.', 'Selects the model to calibrate. CAM is the cross asset model of the simulation, calibrated to market instruments. HW is the Hull-White model, calibrated to historical data. The HW parameters of this analytic have an effect only for HW.', 'CAM', 'CAM or HW.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '72f10f9f-4ad0-5d29-9bf4-8fd8674d15bb', 0, 'analytic', 'calibration', 'mode', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''mode'']', 267, 'string', false, 'HW calibration mode', 'historical', 'Selects how ORE calibrates the Hull-White model. Only historical is supported: ORE fits the model to historical discount factors and rates. The mode riskNeutral is a stub that does nothing in release 1.8.17.0. ORE uses it only when the model is HW and the mode is historical.', 'None. With the HW model the parameter is needed.', 'historical', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '744aed38-8337-5f21-98e2-34adc16ae1aa', 0, 'analytic', 'calibration', 'foreignCurrencies', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''foreignCurrencies'']', 268, 'string', false, 'Foreign currencies', 'A comma-separated list of currency codes.', 'Lists the foreign currencies that the calibration covers, besides the base currency. Each currency adds its own interest rate model and an FX model against the base currency. For example, EUR,GBP calibrates the model for euro and sterling. ORE uses it only when the model is HW and the mode is historical. Without a value the calibration covers the base currency only.', 'None. The calibration covers the base currency only.', 'A comma-separated list of currency codes.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '94aef581-5b37-5a74-98c3-e018efa22432', 0, 'analytic', 'calibration', 'pcaCalibration', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''pcaCalibration'']', 269, 'boolean', false, 'PCA calibration', 'A flag. Y runs the principal component analysis.', 'Decides whether ORE reads the historical discount factors and runs a principal component analysis (PCA) to find the factors of the interest rate curves. Switch it off to supply the eigenvectors from files, with PCA input files. ORE uses it only when the model is HW and the mode is historical.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4d36035a-8040-5622-9f74-7f839bedb27c', 0, 'analytic', 'calibration', 'curveTenors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''curveTenors'']', 270, 'string', false, 'Curve tenors', 'A comma-separated list of periods.', 'Lists the tenors of each interest rate curve. They are the points of the historical discount factors, and the points of each eigenvector in the files that give them. For example, 1Y,2Y,3Y,5Y,10Y,15Y,20Y,30Y. ORE uses it only when the model is HW and the mode is historical. The run stops if the list is missing.', 'None. The parameter is mandatory.', 'A comma-separated list of periods such as 1Y,5Y.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b014a4f7-537c-571d-985d-ce78232c0e05', 0, 'analytic', 'calibration', 'useForwardOrZeroRate', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''useForwardOrZeroRate'']', 271, 'string', false, 'Zero or forward rates', 'zero or forward.', 'Selects the rates of the calibration. With PCA calibration on, it says whether the covariance matrix comes from changes in zero rates or in forward rates. With PCA calibration off, it says how ORE reads the eigenvectors of the input files for the mean reversion calibration. The run stops if the value is neither zero nor forward. ORE uses it only when the model is HW and the mode is historical.', 'None. The parameter is needed.', 'zero or forward.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '50854c84-6713-57d1-bd70-41242871f745', 0, 'analytic', 'calibration', 'pcaInputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''pcaInputFileName'']', 272, 'string', false, 'PCA input files', 'A comma-separated list of file names.', 'Lists the files with the eigenvalues and eigenvectors for the mean reversion calibration, one curve for each file. Use it when PCA calibration is off. For example, pca_USD.csv,pca_EUR.csv,pca_GBP.csv. ORE uses it only for the HW model with historical mode and mean reversion calibration on.', 'None.', 'A comma-separated list of file names.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e0e8116f-f6d8-5f51-8dfa-87641c1844d5', 0, 'analytic', 'calibration', 'meanReversionCalibration', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''meanReversionCalibration'']', 273, 'boolean', false, 'Mean reversion calibration', 'A flag. Y calibrates the mean reversion.', 'Decides whether ORE calibrates the mean reversion of the principal components that it keeps. The components come from the PCA step or from the PCA input files. When it is No, the mean reversion stays as the configuration gives it. The basis function number and the kappa bound steer the search. ORE uses it only when the model is HW and the mode is historical.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2258a29e-83bf-5463-be41-99de5e67dbe7', 0, 'analytic', 'calibration', 'basisFunctionNumber', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''basisFunctionNumber'']', 274, 'integer', false, 'Number of basis functions', 'A whole number.', 'Sets the number of basis functions in the mean reversion calibration. More functions let the mean reversion follow a richer shape over time and need more data to stay stable. For example, 2. ORE uses it only for the HW model with historical mode and mean reversion calibration on.', '0. A run with mean reversion calibration needs a value.', 'A whole number of zero or more.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0f1fabd1-052f-586d-b9b7-d41557d8c45e', 0, 'analytic', 'calibration', 'kappaUpperBound', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''kappaUpperBound'']', 275, 'double', false, 'Upper bound of kappa', 'A number.', 'Sets the upper bound of the mean reversion speed (kappa) in the mean reversion calibration. The search for kappa stays below this bound, so a value that is too low can stop the fit short of the best one. For example, 5.0. ORE uses it only for the HW model with historical mode and mean reversion calibration on.', '0. A run with mean reversion calibration needs a value.', 'A number, written with a decimal point.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5896722b-9fd7-580b-9861-449874bdfb88', 0, 'analytic', 'calibration', 'haltonMaxGuess', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''haltonMaxGuess'']', 276, 'integer', false, 'Maximum number of guesses', 'A whole number.', 'Sets the largest number of starting points that the optimisation of the mean reversion calibration tries. The points come from a Halton sequence. A higher number can find a better fit and takes longer. For example, 500. ORE uses it only for the HW model with historical mode and mean reversion calibration on.', '0. A run with mean reversion calibration needs a value.', 'A whole number of zero or more.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5e4b950e-d572-5d3c-9c18-6a8bb4b5332f', 0, 'analytic', 'calibration', 'meanReversionOutputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''meanReversionOutputFileName'']', 277, 'string', false, 'Mean reversion output file', 'A file name.', 'Names the file that receives the calibrated mean reversion speed (kappa) and the volatility (v) of each curve. ORE writes it in the output path. For example, meanReversion.csv. ORE uses it only for the HW model with historical mode and mean reversion calibration on.', 'None. ORE does not write the file.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0ce6a42e-d7ab-54e8-a911-2fac9aa23243', 0, 'analytic', 'calibration', 'scenarioInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''scenarioInputFile'']', 278, 'string', false, 'Historical scenario file', 'A file name.', 'Names the file with the historical discount factors and FX spot rates. The file must be in the scenario.csv format of ORE. ORE uses it only for the HW model with historical mode and PCA calibration on. The run stops if the file is missing.', 'None. The parameter is mandatory.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '933ecb63-dc21-56db-9a95-b4b549869f34', 0, 'analytic', 'calibration', 'startDate', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''startDate'']', 279, 'date', false, 'History start date', 'A date.', 'Sets the first date of the historical data that the calibration uses. A longer history gives steadier parameters and includes older market regimes. For example, 2019-09-29. ORE uses it only for the HW model with historical mode and PCA calibration on. The run stops if the date is missing.', 'None. The parameter is mandatory.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0cc7309f-643f-56a3-871b-8aa0e049f5c2', 0, 'analytic', 'calibration', 'endDate', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''endDate'']', 280, 'date', false, 'History end date', 'A date.', 'Sets the last date of the historical data that the calibration uses. It is usually the valuation date or the last date with market data. For example, 2022-09-27. ORE uses it only for the HW model with historical mode and PCA calibration on. The run stops if the date is missing.', 'None. The parameter is mandatory.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bb9b4b35-9178-5aed-80a3-15a86d265f3d', 0, 'analytic', 'calibration', 'lambda', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''lambda'']', 281, 'double', false, 'Decay factor', 'A number between 0 and 1.', 'Sets the weight decay of the exponentially weighted differences in the historical rates, when ORE computes the covariance matrix. A value of 1 gives all dates the same weight. A smaller value puts more weight on recent dates. ORE uses it only for the HW model with historical mode and PCA calibration on.', '1. All dates have the same weight.', 'A number, written with a decimal point.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9a46ed88-d29c-50a8-99d7-7d5ad21125c3', 0, 'analytic', 'calibration', 'varianceRetained', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''varianceRetained'']', 282, 'double', false, 'Variance retained', 'A number above 0 and up to 1.', 'Sets the share of the total variance that the retained principal components must explain. It decides how many principal components ORE keeps. For example, 0.90 keeps as many components as needed to explain 90 percent of the variance. ORE uses it only for the HW model with historical mode and PCA calibration on. The run stops if the value is missing, zero or above 1.', 'None. The parameter is mandatory.', 'A number, written with a decimal point.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd6549213-71fd-52a4-9a8e-a86eba0cabc3', 0, 'analytic', 'calibration', 'pcaOutputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''pcaOutputFileName'']', 283, 'string', false, 'PCA output file', 'A file name.', 'Names the file that receives the eigenvalues and eigenvectors that ORE retains for each currency. ORE writes it in the output path. For example, pca.csv. ORE uses it only for the HW model with historical mode and PCA calibration on.', 'None. ORE does not write the file.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '26c317b9-acea-555b-83d9-783ca4adfb87', 0, 'analytic', 'calibration', 'pricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''pricingEnginesFile'']', 284, 'string', false, 'Pricing engines file for the calibration', 'A file name.', 'Names the XML file that sets the pricing engines for the calibration instruments, for example the swaptions that the model is calibrated to. The calibration prices these instruments with the engines of the file and moves the model parameters until the prices match the market. Without the file ORE uses the pricing engines file of the Setup block. For example, pricingengine.xml.', 'The pricing engines file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8457522e-f2d6-539f-8cee-ed9e0428d943', 0, 'analytic', 'calibration', 'crossAssetModelData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''calibration'']/Parameter[@name=''crossAssetModelData'']', 285, 'string', false, 'Cross asset model file', 'A file name.', 'Names the XML file with the cross asset model data, if it sits in another file than the model configuration file. When it is set, ORE reads the model data from this file and not from the configuration file. Use it to calibrate a model that you keep apart from the rest of the configuration.', 'The model configuration file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '29724202-1aa0-52ab-9557-3c1f3dd2f73d', 0, 'analytic', 'initialMargin', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''initialMargin'']/Parameter[@name=''active'']', 286, 'boolean', false, 'Initial margin block', 'ORE ignores this block.', 'ORE does not read analytics of this type, and the block has no effect. Example files of an older layout carry it. To compute an initial margin, use the simm analytic or the imschedule analytic.', 'None. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd234ccc4-3eed-5b9b-8f30-75490d43ef83', 0, 'analytic', 'initialMargin', 'method', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''initialMargin'']/Parameter[@name=''method'']', 287, 'string', false, 'Initial margin method', 'A name. ORE ignores it.', 'ORE does not read analytics of the type initialMargin, so this parameter has no effect. Use the simm analytic or the imschedule analytic.', 'None. ORE ignores the parameter, so a value has no effect.', 'A name.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3ca6116c-d941-59b2-b305-8c3bd7752e07', 0, 'analytic', 'zeroToParSensiConversion', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''active'']', 288, 'boolean', true, 'Run the par conversion of sensitivities', 'A flag. Y runs the analytic.', 'Switches the conversion of raw sensitivities into par sensitivities on or off, as a separate step. The raw sensitivities come from a file. The conversion is the same as the embedded par conversion of the sensitivity analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '59aaaa49-0cd2-5c00-a2f3-7598a27fd6cc', 0, 'analytic', 'zeroToParSensiConversion', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''marketConfigFile'']', 289, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market under which the analytic computes its results. The simulation market lists the risk factors that ORE can shift, for example the discount curves, the FX spots and the volatility surfaces, and the tenors of each. The analytic needs only the part under Market and ignores the model and the scenario generator. A risk factor that this file leaves out cannot be shifted. For example, simulation.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '19ad21db-1786-5dfb-a37e-a3cd5f6529c2', 0, 'analytic', 'zeroToParSensiConversion', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''sensitivityConfigFile'']', 290, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file with the sensitivity setup, in particular the par conversion sections. The sections list the par instruments that define each curve, so the conversion can map a raw sensitivity to par sensitivities. For example, sensitivity.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9ee5cdc6-0848-5d48-bb80-8fe484bd9715', 0, 'analytic', 'zeroToParSensiConversion', 'pricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''pricingEnginesFile'']', 291, 'string', false, 'Pricing engines file', 'A file name.', 'Names the XML file that sets the pricing engines for the analytic. The file says which model and which engine price each product, so a change here changes the NPVs behind the results. When it is missing, ORE uses the pricing engines file of the Setup block. Use it to run the analytic with other engines than the rest of the run. For example, pricingengine.xml.', 'The pricing engines file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a36c1695-adcb-5c86-b513-5185780b00c7', 0, 'analytic', 'zeroToParSensiConversion', 'sensitivityInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''sensitivityInputFile'']', 292, 'string', false, 'Raw sensitivities file', 'A file name.', 'Names the CSV file with the raw (zero) sensitivities to convert, for example the result of an earlier sensitivity run or the sensitivities of another system. The file needs six columns, and the column name parameters set their names. For example, sensitivity.csv. The analytic needs this file.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '18ba3d00-1940-5a82-ac4f-a72e5a82e578', 0, 'analytic', 'zeroToParSensiConversion', 'outputThreshold', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''outputThreshold'']', 293, 'double', false, 'Output threshold', 'A number.', 'Sets the smallest absolute value that the analytic writes. It drops every par sensitivity below the number from the output. A larger value gives a smaller file and hides numerical noise. The default is 0.000001. For example, 0.01.', '0.000001', 'A number, written with a decimal point.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '26b9c8d4-3d1a-5291-8f48-32b24d662ca0', 0, 'analytic', 'zeroToParSensiConversion', 'outputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''outputFile'']', 294, 'string', false, 'Par sensitivities file', 'A file name.', 'Names the file that receives the par sensitivities, one row for each trade, netting set or portfolio and each par instrument. The default is parConversionSensitivity.csv, written in the output path. For example, parconversion_sensitivity.csv.', 'parConversionSensitivity.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1d004ddd-08c9-5f72-9337-be8e4aa006d9', 0, 'analytic', 'zeroToParSensiConversion', 'outputJacobi', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''outputJacobi'']', 295, 'boolean', false, 'Write the Jacobi matrices', 'A flag. Y writes the matrices.', 'Decides whether the analytic writes the Jacobi matrix and its inverse to files. The matrices convert between raw and par sensitivities, so you can check the conversion or use them elsewhere. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4eb2d389-9bb1-5468-a743-ddac04d00b2f', 0, 'analytic', 'zeroToParSensiConversion', 'jacobiOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''jacobiOutputFile'']', 296, 'string', false, 'Jacobi matrix file', 'A file name.', 'Names the file for the Jacobi matrix, which converts a raw shift into the par shifts of the quotes. It has an effect only when Write the Jacobi matrices is on. The default is parConversionJacobi.csv, written in the output path.', 'parConversionJacobi.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '97da5076-c7ea-535d-a3d3-63542efa075f', 0, 'analytic', 'zeroToParSensiConversion', 'jacobiInverseOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''jacobiInverseOutputFile'']', 297, 'string', false, 'Inverse Jacobi matrix file', 'A file name.', 'Names the file for the inverse Jacobi matrix, which converts a par shift into the raw shifts of the market. It has an effect only when Write the Jacobi matrices is on. The default is parConversionJacobi_inverse.csv, written in the output path.', 'parConversionJacobi_inverse.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '262150b3-60ff-563e-b363-9c1dfb263493', 0, 'analytic', 'zeroToParSensiConversion', 'idColumn', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''idColumn'']', 298, 'string', false, 'Id column', 'A column name.', 'Names the column of the input file with the unique identifier of the trade, netting set or portfolio. Change it when the file comes from a system that calls the column something else. The default is TradeId. For example, NettingSetId for a file of netting set sensitivities.', 'TradeId', 'A column name.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1e607d4d-8189-5f80-9a2f-02c61bf22ff4', 0, 'analytic', 'zeroToParSensiConversion', 'riskFactorColumn', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''riskFactorColumn'']', 299, 'string', false, 'Risk factor column', 'A column name.', 'Names the column of the input file with the identifier of the raw sensitivity. The name must follow the ORE naming convention, for example DiscountCurve/EUR/5/1Y. Change the parameter when the file calls the column something else. The default is Factor_1.', 'Factor_1', 'A column name.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '76ecebf5-d336-5681-a294-065c920ba6e6', 0, 'analytic', 'zeroToParSensiConversion', 'deltaColumn', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''deltaColumn'']', 300, 'string', false, 'Sensitivity column', 'A column name.', 'Names the column of the input file with the raw sensitivity of the trade, netting set or portfolio to the risk factor. Change it when the file calls the column something else. The default is Delta.', 'Delta', 'A column name.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '81710024-feca-5302-8c0c-5106542b4e0e', 0, 'analytic', 'zeroToParSensiConversion', 'currencyColumn', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''currencyColumn'']', 301, 'string', false, 'Currency column', 'A column name.', 'Names the column of the input file with the currency of the raw sensitivity. The currency must equal the base currency of the simulation settings. Change the parameter when the file calls the column something else. The default is Currency.', 'Currency', 'A column name.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5586a268-fc44-5bf0-af2e-775dd85cb58c', 0, 'analytic', 'zeroToParSensiConversion', 'baseNpvColumn', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''baseNpvColumn'']', 302, 'string', false, 'Base NPV column', 'A column name.', 'Names the column of the input file with the base NPV of the trade, netting set or portfolio. Change it when the file calls the column something else. The default is Base NPV.', 'Base NPV', 'A column name.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3633ed25-83c1-5ed2-9739-a7d2f856a7b3', 0, 'analytic', 'zeroToParSensiConversion', 'shiftSizeColumn', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''zeroToParSensiConversion'']/Parameter[@name=''shiftSizeColumn'']', 303, 'string', false, 'Shift size column', 'A column name.', 'Names the column of the input file with the shift size that ORE applied to compute the raw sensitivity. The value must agree with the sensitivity configuration, because the conversion rescales by it. Change the parameter when the file calls the column something else. The default is ShiftSize_1.', 'ShiftSize_1', 'A column name.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '564cd889-f14b-5e40-ae48-663751cdf374', 0, 'analytic', 'saccr', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''saccr'']/Parameter[@name=''active'']', 304, 'boolean', true, 'Run the SA-CCR analytic', 'A flag. Y runs the analytic.', 'Switches the standardised approach for the counterparty credit risk capital (SA-CCR) on or off. The calculation gives the exposure at default of each netting set, as the replacement cost plus the potential future exposure, times a factor. It needs the netting set definitions and the collateral balances.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '90533623-b98f-5fa7-81cd-4d30f1bd05dc', 0, 'analytic', 'saccr', 'csaFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''saccr'']/Parameter[@name=''csaFile'']', 305, 'string', false, 'Netting set definitions file', 'A file name.', 'Names the XML file with the netting set definitions, as in the XVA analytics. The file holds the margin agreements, such as the threshold and the minimum transfer amount, that the exposure at default depends on. ORE looks for the file name in the saccr block, then in the bacva block. For example, netting.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1ceb9a11-e62b-5368-8ba9-f99e5392a9b9', 0, 'analytic', 'saccr', 'collateralBalancesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''saccr'']/Parameter[@name=''collateralBalancesFile'']', 306, 'string', false, 'Collateral balances file', 'A file name.', 'Names the XML file with the variation margin and initial margin balances of the valuation date. The balances reduce the replacement cost and the exposure at default of each netting set. ORE looks for the file name in the saccr block, then in the bacva block. For example, collateralbalances.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a79af0e3-9d34-5c55-9a1d-97fae88397ba', 0, 'analytic', 'saccr', 'simmVersion', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''saccr'']/Parameter[@name=''simmVersion'']', 307, 'double', false, 'SIMM version', 'A SIMM version, for example 2.6.', 'Names the version of the SIMM that the calculation uses for the name and bucket mapping of commodity hedging sets. Use the version that the firm has adopted, for example 2.6. The run stops if the version is empty. The parameter is mandatory.', 'None. The parameter is mandatory.', 'A SIMM version such as 2.4, 2.5A, 2.6 or 2.7.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3785039a-cb60-5df3-9fe8-fccf684a0ae4', 0, 'analytic', 'saccr', 'counterpartyFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''saccr'']/Parameter[@name=''counterpartyFile'']', 308, 'string', false, 'Counterparty file', 'A file name.', 'Names the XML file with the counterparty information for the SA-CCR calculation, such as the credit quality and the sector of each counterparty. A value here replaces the file of the Setup block, so one run can use a different list of counterparties for the capital calculation.', 'The counterparty file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'edb8bc31-14b8-555a-bcff-ac77149d8784', 0, 'analytic', 'saccr', 'nameMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''saccr'']/Parameter[@name=''nameMappingInputFile'']', 309, 'string', false, 'Name mapping file', 'A file name.', 'Names the file that maps the names in the portfolio to the SIMM names for the commodity hedging sets. Use it when the names of the portfolio differ from the names of the SIMM. Without it ORE uses the names as they are.', 'None. ORE uses the names as they are.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e4016e4d-90e2-5956-897d-35f24b31771a', 0, 'analytic', 'saccr', 'bucketMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''saccr'']/Parameter[@name=''bucketMappingInputFile'']', 310, 'string', false, 'Bucket mapping file', 'A file name.', 'Names the file that maps risk factors to the SIMM buckets for the commodity hedging sets. The bucket decides the supervisory factor that the hedging set gets. Without it ORE uses the standard buckets.', 'None. ORE uses the standard SIMM buckets.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '64943b53-67c0-5d59-8225-ed8c37d95419', 0, 'analytic', 'smrc', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''smrc'']/Parameter[@name=''active'']', 311, 'boolean', true, 'Run the SMRC analytic', 'A flag. Y runs the analytic.', 'Switches the basic standardised market risk capital calculation (SMRC) on or off. The calculation applies the standardised formula to the sensitivities of the portfolio and gives the capital charge for market risk. It needs no inputs besides the Setup block.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fccaeda4-cc2f-5f6d-812f-b28bb50178a4', 0, 'analytic', 'portfolioDetails', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''portfolioDetails'']/Parameter[@name=''active'']', 312, 'boolean', true, 'Run the portfolio details analytic', 'A flag. Y runs the analytic.', 'Switches the portfolio details analytic on or off. It analyses the portfolio and writes reports of its risk factors, its market objects, its swap indices, the number of trades for each counterparty, netting set and trade type, and its underlying indices.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fe536e63-0743-50d2-9425-c8fc1e6da0dd', 0, 'analytic', 'portfolioDetails', 'riskFactorFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''portfolioDetails'']/Parameter[@name=''riskFactorFileName'']', 313, 'string', false, 'Risk factor report file', 'A file name.', 'Names the file with the report of the risk factors of the portfolio: one row for each risk factor that the trades depend on. Use it to find the market data that a run needs before you load it. The default is risk_factors.csv, written in the output path.', 'risk_factors.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '436fa8bc-cb0c-5048-a2a8-399279cb2f25', 0, 'analytic', 'portfolioDetails', 'marketObjectFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''portfolioDetails'']/Parameter[@name=''marketObjectFileName'']', 314, 'string', false, 'Market object report file', 'A file name.', 'Names the file with the report of the market objects that the portfolio needs, for example the yield curves, the volatility surfaces and the FX spots. Use it to check that todays market holds everything the trades use. The default is market_objects.csv, written in the output path.', 'market_objects.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '82d34781-2543-589b-abfc-2fc745dcc55d', 0, 'analytic', 'portfolioDetails', 'version', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''portfolioDetails'']/Parameter[@name=''version'']', 315, 'string', false, 'SIMM version', 'A SIMM version, for example 2.6.', 'Names a SIMM version. The CRIF generation uses it as its last choice, when the crif block, the saccr block and the simm block have no version. The portfolio details analytic itself computes no margin. For example, 2.6.', 'None.', 'A SIMM version such as 2.6.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '963ea873-bfe4-5fbe-90f7-aee5e9cbc44d', 0, 'analytic', 'portfolioDetails', 'portfolio_details_configuration', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''portfolioDetails'']/Parameter[@name=''portfolio_details_configuration'']', 316, 'string', false, 'Details configuration', 'A name.', 'Names the configuration of the portfolio details. ORE reads the value, and no analytic of release 1.8.17.0 uses it. The default is BASIC. Leave it as it is.', 'BASIC', 'A name such as BASIC.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '558d14db-c899-5d98-8b27-ae690b77047f', 0, 'analytic', 'stress', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''active'']', 317, 'boolean', true, 'Run the stress analytic', 'A flag. Y runs the analytic.', 'Switches the stress analytic on or off. When it is on, it revalues the portfolio under each scenario of the stress configuration file and writes the change of the NPV for each trade. Use N to keep the entry in the document without running it.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2de4eb92-c7ad-586d-8fe4-7959b2eec959', 0, 'analytic', 'stress', 'precision', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''precision'']', 318, 'integer', false, 'Output precision', 'A whole number of decimal places.', 'Sets the number of decimal places of the numbers in the stress result file. A higher number shows more of each value and makes the file larger. The default is 2. For example, 6 shows a small change such as 0.001234 in full.', '2', 'A whole number of zero or more.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f26de980-0178-51e1-9d38-a5575bc90c2a', 0, 'analytic', 'stress', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''marketConfigFile'']', 319, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market under which the analytic computes its results. The simulation market lists the risk factors that ORE can shift, for example the discount curves, the FX spots and the volatility surfaces, and the tenors of each. The analytic needs only the part under Market and ignores the model and the scenario generator. A risk factor that this file leaves out cannot be shifted. For example, simulation.xml. The analytic replaces the market of the valuation date with this simulation market and applies the stress scenarios to it.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a6094a4a-4e48-58d4-9510-25c377a6e0b5', 0, 'analytic', 'stress', 'stressConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''stressConfigFile'']', 320, 'string', false, 'Stress configuration file', 'A file name.', 'Names the XML file with the stress scenarios. The same file also decides whether the stress is in the raw domain, as shifts of the zero rates, or in the par domain, as shifts of the par rates. For example, stresstest.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'efce0399-b397-55ca-9c03-37012b3d787a', 0, 'analytic', 'stress', 'pricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''pricingEnginesFile'']', 321, 'string', false, 'Pricing engines file', 'A file name.', 'Names the XML file that sets the pricing engines for the analytic. The file says which model and which engine price each product, so a change here changes the NPVs behind the results. When it is missing, ORE uses the pricing engines file of the Setup block. Use it to run the analytic with other engines than the rest of the run. For example, pricingengine.xml.', 'The pricing engines file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ca723219-da4a-52dd-b31b-48fa14cc7e34', 0, 'analytic', 'stress', 'scenarioOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''scenarioOutputFile'']', 322, 'string', false, 'Stress result file', 'A file name.', 'Names the file with the result of each stress scenario: the NPV of the base scenario, the NPV of the stressed scenario and their difference. Each row is one trade under one scenario. The default is stress.csv, written in the output path. For example, stresstest.csv.', 'stress.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b78de119-ec48-5902-9122-3a5ed0089471', 0, 'analytic', 'stress', 'outputThreshold', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''outputThreshold'']', 323, 'double', false, 'Output threshold', 'A number.', 'Sets the smallest absolute NPV change that the analytic writes. It drops every change below the number from the output, so a scenario that moves a trade by less than the number leaves no row. The default is 0, so the analytic writes every change. For example, 0.000001.', '0. The analytic writes every change.', 'A number, written with a decimal point.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '40261921-51af-568f-80e2-ab6da257609e', 0, 'analytic', 'stress', 'generateCashflows', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''generateCashflows'']', 324, 'boolean', false, 'Generate cash flows', 'A flag. Y writes the cash flows under each scenario.', 'Decides whether the analytic also writes the cash flows of the trades under each stress scenario, to the cash flow output file. Use it to see how a scenario changes the amounts and the dates of the flows, for example when a floating rate fixes higher. The file is large for a big portfolio. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6446451e-dc07-5eb0-acb6-fc7845624b31', 0, 'analytic', 'stress', 'scenarioCashflowOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''scenarioCashflowOutputFile'']', 325, 'string', false, 'Stress cash flow file', 'A file name.', 'Names the file with the cash flows under each stress scenario. It has an effect only when Generate cash flows is on. The default is stress_cashflows.csv, written in the output path. For example, stresstest_flows.csv.', 'stress_cashflows.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '936181c7-dd6b-577c-81c7-374843e82d1d', 0, 'analytic', 'stress', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''sensitivityConfigFile'']', 326, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file with the sensitivity setup, which a par stress test needs for the conversion of the par shifts. The conversion turns a shift of par rates into the equivalent shift of the model rates. Without it ORE supports no par stress test and the stress file must be in the raw domain.', 'None. Par stress tests are not supported.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '19aea509-f305-5950-8df6-a8c74a7f22bf', 0, 'analytic', 'stress', 'stressZeroScenarioDataFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''stressZeroScenarioDataFile'']', 327, 'string', false, 'Raw domain stress file', 'A file name.', 'Names the file that receives the stress test definition in the raw domain, when the stress test file is in the par domain. The converted file can be used again without a new conversion, which saves the cost of the par conversion. For example, zeroStressScenarioData.xml.', 'stress_ZeroStressData.xml. The analytic writes the file only for a stress test in the par domain.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '73f0594a-11fb-5280-af0b-5753af44b05d', 0, 'analytic', 'stress', 'scenarioFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''scenarioFile'']', 328, 'string', false, 'Scenario input file', 'A file name.', 'Names a file with market scenarios that ORE reads as stress scenarios, for example scenarios that an earlier run wrote or a historical event that you saved. For example, StressScenarios/stress_scenarios.csv. The scenarios come in addition to those of the stress configuration file.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.2.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a235b68a-fa5c-5e21-9773-84c569cb37ad', 0, 'analytic', 'stress', 'optimiseRiskFactors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''optimiseRiskFactors'']', 329, 'boolean', false, 'Optimise the risk factors', 'A flag. Y limits the par conversion to the risk factors that matter.', 'Decides whether the par stress conversion limits itself to the risk factors that the stress scenarios shift. A par stress test converts par shifts into raw shifts, and the conversion handles every risk factor of the market unless this is on. It makes the conversion faster. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bdee8562-7665-5ee0-92a4-e01f2f326b36', 0, 'analytic', 'stress', 'lowerBoundCapVols', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''lowerBoundCapVols'']', 330, 'double', false, 'Lower bound of cap volatilities', 'A number.', 'Is meant to set the lowest cap and floor volatility that the par to raw conversion tries. The conversion uses the bound 1e-8. ORE reads the value for the stress analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '1e-8', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c5a47b12-16d2-5ff2-95cb-dc2e5164422a', 0, 'analytic', 'stress', 'upperBoundCapVols', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''upperBoundCapVols'']', 331, 'double', false, 'Upper bound of cap volatilities', 'A number.', 'Is meant to set the highest cap and floor volatility that the par to raw conversion tries, as a multiple of the base volatility. The conversion uses the bound 10. ORE reads the value for the stress analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '10', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b3d7a2fa-401e-573e-b131-54315c0cd33b', 0, 'analytic', 'stress', 'lowerBoundDiscountFactors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''lowerBoundDiscountFactors'']', 332, 'double', false, 'Lower bound of discount factors', 'A number.', 'Is meant to set the lowest discount factor that the par to raw conversion tries. The conversion uses the bound 1e-8. ORE reads the value for the stress analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '1e-8', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ea1b48fe-62c3-5571-9b6f-01b572258fac', 0, 'analytic', 'stress', 'upperBoundDiscountFactors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''upperBoundDiscountFactors'']', 333, 'double', false, 'Upper bound of discount factors', 'A number.', 'Is meant to set the highest discount factor that the par to raw conversion tries. The conversion uses the bound 10. ORE reads the value for the stress analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '10', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f1e07cf1-33b0-586c-a994-aafa97354d0e', 0, 'analytic', 'stress', 'lowerBoundSurvivalProb', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''lowerBoundSurvivalProb'']', 334, 'double', false, 'Lower bound of survival probabilities', 'A number.', 'Is meant to set the lowest survival probability that the par to raw conversion tries. The conversion treats survival probabilities like discount factors and uses the bound 1e-8. ORE reads the value for the stress analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '1e-8', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3ee3058f-a952-56a6-a723-b1d25709ff51', 0, 'analytic', 'stress', 'upperBoundSurvivalProb', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''upperBoundSurvivalProb'']', 335, 'double', false, 'Upper bound of survival probabilities', 'A number.', 'Is meant to set the highest survival probability that the par to raw conversion tries. The conversion treats survival probabilities like discount factors and uses the bound 10. ORE reads the value for the stress analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '10', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1b844cdb-03ce-5b67-af3a-ac79cf4a508e', 0, 'analytic', 'stress', 'accuracy', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stress'']/Parameter[@name=''accuracy'']', 336, 'double', false, 'Accuracy of the conversion', 'A number.', 'Is meant to set the accuracy of the root search that turns a par shift into a raw shift. The conversion uses the accuracy 1e-8. ORE reads the value for the stress analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '1e-8', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7ff6fca2-6964-5ce1-8fb3-e694060d05d0', 0, 'analytic', 'parametricVar', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''active'']', 337, 'boolean', true, 'Run the parametric VaR analytic', 'A flag. Y runs the analytic.', 'Switches the parametric VaR analytic on or off. When it is on, the run computes the value at risk from the sensitivities and a covariance matrix of the risk factors, under the assumption that the returns follow a normal distribution. It is fast, because it revalues nothing. Use N to keep the entry in the document without running it.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '143a53f0-d53b-5830-ba93-68d851207785', 0, 'analytic', 'parametricVar', 'sensitivityInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''sensitivityInputFile'']', 338, 'string', false, 'Sensitivities file', 'A comma-separated list of file names.', 'Lists the files with the delta, vega and gamma sensitivities and the cross gamma, as the sensitivity analytic of ORE writes them. The analytic reads the sensitivities from these files and does not compute them, so run the sensitivity analytic first or supply the files from another system. Separate the names with a comma. For example, ../Output/sensitivity.csv,../Output/crossgamma.csv.', 'None. The analytic needs the sensitivities.', 'A comma-separated list of file names.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '58eedad2-c394-5e68-b184-8e6baed7119f', 0, 'analytic', 'parametricVar', 'covarianceInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''covarianceInputFile'']', 339, 'string', false, 'Covariance file', 'A file name.', 'Names the file with the covariances of the risk factors. ORE does not compute them, so you must supply them. The file has three columns: the first factor, the second factor and the covariance. The factor names follow the naming in the sensitivity and cross gamma files, and the covariances must agree with the sensitivities: if a sensitivity is for an absolute shift in basis points, the covariances are for absolute shifts in basis points. The covariances must include the holding period, because ORE does not scale them with the square root of time. For example, covariance.csv.', 'None. The analytic needs the covariances.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '125667a0-d2dd-5012-a7aa-5af5127b7d21', 0, 'analytic', 'parametricVar', 'quantiles', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''quantiles'']', 340, 'string', false, 'Quantiles', 'A comma-separated list of quantiles.', 'Lists the quantiles of the profit and loss distribution that the report shows. Each quantile gives one column in the output file. The 1 percent quantile is the lower tail of the P&L distribution, which is the VaR, and the 99 percent quantile is the upper tail. For example, 0.01,0.05,0.95,0.99. The historical simulation VaR analytic has the same parameter.', 'None. The analytic needs the list.', 'A comma-separated list of numbers between 0 and 1, for example 0.01,0.05,0.95,0.99.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cec0c8f4-3e71-5e18-8429-ade4559e4022', 0, 'analytic', 'parametricVar', 'breakdown', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''breakdown'']', 341, 'boolean', false, 'Break down the VaR', 'A flag. Y breaks down the VaR.', 'Decides whether the analytic computes the VaR for each portfolio, risk class (all, interest rate, FX, inflation, equity, credit) and risk type (all, delta and gamma, vega), and not only for the whole portfolio. The historical simulation VaR analytic has the same parameter.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '310a9993-ad34-5a3b-9586-ea7e0d3dc57a', 0, 'analytic', 'parametricVar', 'portfolioFilter', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''portfolioFilter'']', 342, 'string', false, 'Portfolio filter', 'A regular expression.', 'Limits the VaR to the trades whose portfolio id matches the regular expression. Without it, the analytic uses the whole portfolio. Use it to compute the VaR of one desk or one book from a portfolio file that holds many. For example, PF1|PF2 selects the portfolios PF1 and PF2. The historical simulation VaR analytic has the same parameter.', 'None. The analytic uses the whole portfolio.', 'A regular expression.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0598e60c-9960-5e4c-a4f4-69f52cbc6139', 0, 'analytic', 'parametricVar', 'method', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''method'']', 343, 'string', false, 'VaR method', 'Delta, DeltaGammaNormal, MonteCarlo, Cornish-Fisher or Saddlepoint.', 'Selects the method for the VaR. Delta uses the delta sensitivities only. DeltaGammaNormal adds the gamma and uses a normal approximation. MonteCarlo simulates the risk factors. Cornish-Fisher and Saddlepoint are two other approximations of the distribution. The name varMethod is another name for the same parameter.', 'DeltaGammaNormal', 'One of Delta, DeltaGammaNormal, MonteCarlo, Cornish-Fisher or Saddlepoint.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f0b62308-c195-5300-a5d4-f2b71257a9a7', 0, 'analytic', 'parametricVar', 'outputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''outputFile'']', 344, 'string', false, 'VaR report file', 'A file name.', 'Names the file with the main VaR report: one row for each portfolio, risk class and risk type with the VaR at each quantile. The parametric and the historical simulation analytic share this name: ORE reads it from the parametric block first, so set it there when you run both. For example, var.csv.', 'var.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e16b1d25-e1a0-5bd0-9476-b97ed5344e69', 0, 'analytic', 'parametricVar', 'SalvagingAlgorithm', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''SalvagingAlgorithm'']', 345, 'string', false, 'Salvaging algorithm', 'None, Spectral, Hypersphere, LowerDiagonal, Higham or Principal.', 'Selects the algorithm that repairs a covariance matrix that is not positive semi-definite. Such a matrix arises when the correlations come from different sources or from too few observations, and the VaR needs a valid matrix. None does not repair it, and the run then stops on an invalid matrix. The other five names are repair methods. The default is Spectral, which replaces the negative eigenvalues by zero.', 'Spectral', 'One of None, Spectral, Hypersphere, LowerDiagonal, Higham or Principal.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '88002ca1-c8e1-522a-9cc6-67647914214a', 0, 'analytic', 'parametricVar', 'mcSamples', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''mcSamples'']', 346, 'integer', false, 'Monte Carlo samples', 'A whole number.', 'Sets the number of samples of the Monte Carlo method. A higher number gives a steadier result and takes longer. The name varMcSamples is another name for the same parameter. ORE uses it only when the method is MonteCarlo.', '1000000', 'A whole number of zero or more.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '71e11997-3bed-5f0b-959d-edbcf5b84db4', 0, 'analytic', 'parametricVar', 'mcSeed', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parametricVar'']/Parameter[@name=''mcSeed'']', 347, 'integer', false, 'Monte Carlo seed', 'A whole number.', 'Sets the seed of the random number generator of the Monte Carlo method. The same seed gives the same result. The name varMcSeed is another name for the same parameter. ORE uses it only when the method is MonteCarlo.', '42', 'A whole number of zero or more.', '1.8.3.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0d8c6a1b-a0ce-596a-aca1-c5c593828bca', 0, 'analytic', 'simm', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''active'']', 348, 'boolean', true, 'Run the SIMM analytic', 'A flag. Y runs the analytic.', 'Switches the ISDA Standard Initial Margin Model (SIMM) on or off. The analytic computes the initial margin from sensitivities in the Common Risk Interchange Format (CRIF): it applies the risk weights and the correlations of the chosen SIMM version to the sensitivities of each product class and adds the results. Use it to estimate the margin that a bilateral agreement asks for.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '79b5ec08-e48f-54ee-a72d-0475a6ed5e23', 0, 'analytic', 'simm', 'version', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''version'']', 349, 'string', false, 'SIMM version', 'A SIMM version, for example 2.6.', 'Selects the version of the SIMM. ISDA publishes a new version about once a year, and the firm and its counterparties must use the same one. ORE supports the SIMM versions 1.0, 1.1, 1.2, 1.3, 1.3.38, 2.0, 2.1, 2.2, 2.3, 2.4, 2.5, 2.5A, 2.6 and 2.6.5. For example, 2.6 applies the risk weights of that version. The run stops if no version is set.', 'None. The parameter is mandatory.', 'A SIMM version such as 2.6.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b145c7f9-f7a9-5c66-9a86-57959fa54b3d', 0, 'analytic', 'simm', 'crif', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''crif'']', 350, 'string', false, 'CRIF file', 'A file name.', 'Names the CRIF file with the sensitivities. The SIMM analytic can process a full CRIF with interest rate, FX, inflation, equity, credit and commodity risk. When the parameter is missing, ORE uses the CRIF analytic to generate the CRIF, and that generation covers interest rate and FX risk only. For example, crif.csv.', 'None. ORE generates the CRIF with the CRIF analytic.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3b359233-c2ab-55f4-b28b-06185a24115b', 0, 'analytic', 'simm', 'calculationCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''calculationCurrency'']', 351, 'string', false, 'Calculation currency', 'A currency code, for example USD.', 'Sets the currency of the calculation. The SIMM ignores the Risk_FX entries of the CRIF in this currency. It is also the currency to call and to post, unless the next two parameters override it. For example, USD. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'The base currency. The run stops if neither is set.', 'A currency code of three letters, for example USD.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cce45380-a41e-5e48-ae96-767748c2d530', 0, 'analytic', 'simm', 'enforceIMRegulations', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''enforceIMRegulations'']', 352, 'boolean', false, 'Enforce the IM regulations', 'A flag. Y calculates the SIMM for each regulation.', 'Decides whether ORE calculates the SIMM for each post and collect regulation that the records of the CRIF name, and then reports the worst case. When it is N, ORE ignores the regulations of the CRIF. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'No. ORE ignores the post and collect regulations of the CRIF.', 'A flag, written Y or N, or true or false.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e1fa7b97-fceb-515c-96a7-4f1f92e5a075', 0, 'analytic', 'simm', 'mporDays', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''mporDays'']', 353, 'integer', false, 'Margin period of risk in days', '1 or 10.', 'Sets the margin period of risk of the SIMM, in days. The SIMM scales the risk weights to the period over which the portfolio can move before a defaulted counterparty is closed out. ORE supports 1 and 10 for the versions from 2.2 onwards and only 10 for the earlier versions. The default is 10, the period for bilateral margin.', '10', '1 or 10.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5b0b5b9d-eca9-52d2-9d73-0d48f5f82530', 0, 'analytic', 'simm', 'simmCalibration', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''simmCalibration'']', 354, 'string', false, 'SIMM calibration file', 'A file name.', 'Names a file with the calibration of the SIMM, that is the risk weights and the correlations. When the file exists, it replaces the calibration of the SIMM version above. Use it to test a calibration that ISDA has proposed but not yet released, or a calibration of your own. Without it ORE uses the calibration of the version.', 'None. ORE uses the calibration of the version.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '27337edb-aff9-50a6-b2bf-4b2252e01ae4', 0, 'analytic', 'simm', 'writeIntermediateReports', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''writeIntermediateReports'']', 355, 'boolean', false, 'Write the intermediate reports', 'A flag. Y writes the reports.', 'Decides whether the SIMM analytic writes its intermediate reports, which show the steps from the CRIF to the margin: the sensitivities by risk class, the weighted sensitivities, and the margin of each bucket. Use them to follow how the margin builds up, or to find which bucket drives it. The default is Yes.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4109b6d3-49fa-567f-9731-41b8b4e24c55', 0, 'analytic', 'simm', 'calculationCurrencyCall', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''calculationCurrencyCall'']', 356, 'string', false, 'Calculation currency to call', 'A currency code, for example USD.', 'Sets a separate calculation currency for the margin that we call. A credit support annex can set one currency for what we call and another for what we post. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'The calculation currency, or the base currency when that is missing too.', 'A currency code of three letters, for example USD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c9e468e8-8216-599b-a041-5cd9be95e760', 0, 'analytic', 'simm', 'calculationCurrencyPost', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''calculationCurrencyPost'']', 357, 'string', false, 'Calculation currency to post', 'A currency code, for example USD.', 'Sets a separate calculation currency for the margin that we post. A credit support annex can set one currency for what we call and another for what we post. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'The calculation currency, or the base currency when that is missing too.', 'A currency code of three letters, for example USD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1892edf4-6272-55b4-8f99-aa20d5324c64', 0, 'analytic', 'simm', 'resultCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''resultCurrency'']', 358, 'string', false, 'Result currency', 'A currency code, for example USD.', 'Sets the currency of the SIMM amounts in the report. ORE converts the margin from the calculation currency into this currency at the spot rate of the valuation date. For example, EUR reports the margin in euro. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'The calculation currency to call.', 'A currency code of three letters, for example USD.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b31cf3b6-baf2-513d-8da3-a4a2f64bcea4', 0, 'analytic', 'simm', 'reportingCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''reportingCurrency'']', 359, 'string', false, 'Reporting currency', 'A currency code, for example USD.', 'Adds two columns to the SIMM report: the reporting currency and the SIMM amount converted into it. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'None. The report has no extra columns.', 'A currency code of three letters, for example USD.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c13f23f3-d8b5-58b5-9d27-a74b8013f989', 0, 'analytic', 'simm', 'nameMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''nameMappingInputFile'']', 360, 'string', false, 'Name mapping file', 'A file name.', 'Names the file that maps the names in the portfolio to the SIMM names. Without it ORE uses the names as they are. ORE reads it from the first of the blocks crif, saccr, simm, npv and Setup that has a value.', 'None. ORE uses the names as they are.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b5071107-98c8-5c4a-87d9-45229a4bd426', 0, 'analytic', 'simm', 'bucketMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''bucketMappingInputFile'']', 361, 'string', false, 'Bucket mapping file', 'A file name.', 'Names the file that maps risk factors to the SIMM buckets. The bucket decides the risk weight and the correlation that a sensitivity gets. Without it ORE uses the standard buckets. ORE reads it from the first of the blocks crif, saccr, simm, npv and Setup that has a value.', 'None. ORE uses the standard SIMM buckets.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9b4347eb-99c2-5840-ab7d-072cbc3b038c', 0, 'analytic', 'simm', 'computeTheta', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simm'']/Parameter[@name=''computeTheta'']', 362, 'boolean', false, 'Compute theta', 'A flag. Y computes the theta.', 'Decides whether the sensitivity calculation behind the CRIF also computes the theta. ORE reads the parameter from the sensitivity block, the simm block or the crif block, in this order, and one value serves all three analytics.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '48e3e309-436b-54fa-8884-6f78a2a572bf', 0, 'analytic', 'imschedule', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imschedule'']/Parameter[@name=''active'']', 363, 'boolean', true, 'Run the IM schedule analytic', 'A flag. Y runs the analytic.', 'Switches the IM schedule analytic on or off. It computes the basic initial margin with the IM schedule method from minimal trade information: the NPV, the notional and the end date. The CRIF file gives the information.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7e98d4c9-5804-59e0-a540-27b8630250df', 0, 'analytic', 'imschedule', 'crif', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imschedule'']/Parameter[@name=''crif'']', 364, 'string', false, 'CRIF file', 'A file name.', 'Names the CRIF file for the IM schedule. It needs two lines for each trade, one with the risk class PV and one with the risk class Notional, which ORE reads as the NPV and the notional. It also needs the product class and the end date. The product class must be one of Rates, FX, Equity, Credit and Commodity: the SIMM uses the combined class RatesFX, but the IM schedule does not. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops. For example, crif_schedule.csv.', 'None. The analytic needs the file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '124da144-9fb4-57db-8a60-264716ff45fa', 0, 'analytic', 'imschedule', 'calculationCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imschedule'']/Parameter[@name=''calculationCurrency'']', 365, 'string', false, 'Calculation currency', 'A currency code, for example USD.', 'Sets the currency of the calculation. The schedule approach states the margin in this currency, and the credit support annex usually names it. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops. For example, USD.', 'The base currency. The run stops if neither is set.', 'A currency code of three letters, for example USD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e9a0888d-1d3c-5377-ba26-82afc9bbb810', 0, 'analytic', 'imschedule', 'version', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imschedule'']/Parameter[@name=''version'']', 366, 'string', false, 'SIMM version', 'A SIMM version, for example 2.6.', 'Selects the version for the CRIF. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops. Use the version that the firm has adopted. The default is the version of the simm block.', 'The version of the simm block.', 'A SIMM version such as 2.6.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a68ad0a0-6699-5c62-9d9c-3a75b5a8a2b4', 0, 'analytic', 'imschedule', 'calculationCurrencyCall', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imschedule'']/Parameter[@name=''calculationCurrencyCall'']', 367, 'string', false, 'Calculation currency to call', 'A currency code, for example USD.', 'Sets a separate calculation currency for the margin that we call. A credit support annex can set one currency for what we call and another for what we post. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'The calculation currency, or the base currency when that is missing too.', 'A currency code of three letters, for example USD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3cdf50d1-0c16-5bb1-b330-c41105bb1b48', 0, 'analytic', 'imschedule', 'calculationCurrencyPost', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imschedule'']/Parameter[@name=''calculationCurrencyPost'']', 368, 'string', false, 'Calculation currency to post', 'A currency code, for example USD.', 'Sets a separate calculation currency for the margin that we post. A credit support annex can set one currency for what we call and another for what we post. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'The calculation currency, or the base currency when that is missing too.', 'A currency code of three letters, for example USD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9ad0e7a1-349e-5437-888c-508a11041059', 0, 'analytic', 'imschedule', 'resultCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imschedule'']/Parameter[@name=''resultCurrency'']', 369, 'string', false, 'Result currency', 'A currency code, for example USD.', 'Sets the currency of the amounts in the report. ORE converts the margin from the calculation currency into this currency at the spot rate of the valuation date. For example, EUR reports the margin in euro. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'The calculation currency to call.', 'A currency code of three letters, for example USD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e7426ab2-033a-520e-a6ee-4d176a251469', 0, 'analytic', 'imschedule', 'reportingCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imschedule'']/Parameter[@name=''reportingCurrency'']', 370, 'string', false, 'Reporting currency', 'A currency code, for example USD.', 'Adds two columns to the report: the reporting currency and the amount converted into it. Use it to see the margin in a second currency next to the calculation currency, for example the currency of the group accounts. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'None. The report has no extra columns.', 'A currency code of three letters, for example USD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd9604749-5796-5681-9d60-031e623c6595', 0, 'analytic', 'imschedule', 'enforceIMRegulations', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imschedule'']/Parameter[@name=''enforceIMRegulations'']', 371, 'boolean', false, 'Enforce the IM regulations', 'A flag. Y calculates for each regulation.', 'Decides whether ORE calculates the margin for each post and collect regulation that the records of the CRIF name, and then reports the worst case. When the SIMM and the IM schedule analytic are both active, the two values must be the same, or the run stops.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '80ce3228-3a9e-5442-9334-73e3a659b607', 0, 'analytic', 'creditcurves', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''creditcurves'']/Parameter[@name=''active'']', 372, 'boolean', false, 'Credit curves block', 'ORE ignores this block.', 'ORE does not read analytics of this type, and the block has no effect. Example files of an older layout carry it. To export curves, use the curves analytic.', 'None. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '040284d9-31bd-5ab0-9aa4-68cf21d6c37b', 0, 'analytic', 'creditcurves', 'configuration', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''creditcurves'']/Parameter[@name=''configuration'']', 373, 'string', false, 'Market configuration', 'A name. ORE ignores it.', 'ORE does not read analytics of the type creditcurves, so this parameter has no effect. The curves analytic exports the curves of a market configuration.', 'None. ORE ignores the parameter, so a value has no effect.', 'A name.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bcc6886e-a937-5004-9867-e2adea40c231', 0, 'analytic', 'creditcurves', 'grid', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''creditcurves'']/Parameter[@name=''grid'']', 374, 'string', false, 'Time grid', 'A time grid. ORE ignores it.', 'ORE does not read analytics of the type creditcurves, so this parameter has no effect.', 'None. ORE ignores the parameter, so a value has no effect.', 'A time grid.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '78776920-bf28-5434-8d58-31f27b1a3e0e', 0, 'analytic', 'creditcurves', 'outputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''creditcurves'']/Parameter[@name=''outputFileName'']', 375, 'string', false, 'Output file', 'A file name. ORE ignores it.', 'ORE does not read analytics of the type creditcurves, so this parameter has no effect.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd5bd52d5-91f3-58a0-88a6-f4d6aa1b0c04', 0, 'analytic', 'scenario', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenario'']/Parameter[@name=''active'']', 376, 'boolean', true, 'Run the scenario analytic', 'A flag. Y runs the analytic.', 'Switches the scenario analytic on or off. It is a utility that exports the base scenario of the simulation market to a file: the value of every risk factor on the valuation date. The P&L calculation uses it too, to get the scenario of each date. Use it to check what the simulation market holds.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1f14b5d8-b2d9-5364-95fc-30129802ffc3', 0, 'analytic', 'scenario', 'simulationConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenario'']/Parameter[@name=''simulationConfigFile'']', 377, 'string', false, 'Simulation configuration file', 'A file name.', 'Names the XML file with the simulation market whose base scenario the analytic exports. The market lists the risk factors, so the file decides which values the scenario holds. For example, simulation.xml. The analytic needs this file.', 'None. The analytic needs the file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2d909350-6f5b-5c55-b6c0-da23ad48d69c', 0, 'analytic', 'scenario', 'scenarioOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenario'']/Parameter[@name=''scenarioOutputFile'']', 378, 'string', false, 'Scenario output file', 'A file name.', 'Names the file that receives the base scenario: one row for each risk factor with its value on the valuation date. The default is scenario.csv, written in the output path. For example, scenario.csv.', 'scenario.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '577d4e9c-ff11-508f-8e54-f57a81501c93', 0, 'analytic', 'pnlExplain', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''active'']', 379, 'boolean', true, 'Run the P&L explain analytic', 'A flag. Y runs the analytic.', 'Switches the P&L explain analytic on or off. When it is on, the run explains the P&L between two valuation dates by the raw or par sensitivities and the moves of the risk factors: the delta effect, the gamma effect and what remains unexplained. Use it to check that the risk numbers account for the P&L.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3023f8b3-69df-5942-bd4c-3dc28d1bed3c', 0, 'analytic', 'pnlExplain', 'mporDate', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''mporDate'']', 380, 'date', false, 'Second valuation date', 'A date.', 'Sets the later of the two valuation dates of the P&L calculation. The first date is the valuation date of the Setup block. The market data must be available for both dates. The name pnlDate is another name for the same parameter. The P&L analytic has the same parameter. For example, 2023-02-14.', 'None. ORE derives the date from the number of days.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9f539c8d-9d38-52f5-b0af-a3062bcad392', 0, 'analytic', 'pnlExplain', 'simulationConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''simulationConfigFile'']', 381, 'string', false, 'Simulation configuration file', 'A file name.', 'Names the XML file with the simulation market. It decides which market factors ORE moves from the first to the second valuation date to compute the P&L. When it is missing, ORE uses the simulation market of the scenario analytic. For example, simulation.xml. The P&L analytic has the same parameter.', 'The simulation market of the scenario analytic.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c74e1295-fa4f-5b2a-b6dd-7ae1fb96de4c', 0, 'analytic', 'pnlExplain', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''sensitivityConfigFile'']', 382, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file with the sensitivity setup for the sensitivity analysis at the valuation date. When it is missing, ORE uses the sensitivity setup of the sensitivity analytic. For example, sensitivity.xml.', 'The sensitivity setup of the sensitivity analytic.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ad498fab-9d31-5560-84c2-7d7dcfec0d57', 0, 'analytic', 'pnlExplain', 'parSensitivity', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''parSensitivity'']', 383, 'boolean', false, 'Use par sensitivities', 'A flag. Y explains the P&L with par sensitivities.', 'Decides whether the explanation uses par sensitivities. With N, it uses the raw sensitivities and the moves of the zero rates. With Y, it uses the par sensitivities and the par rate shifts between the two dates, which come from the zero to par shift analytic. Use Y when the desk thinks in par rates. The default is No.', 'No. The explanation uses raw sensitivities.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2429e615-dd30-5ffa-a49e-b64121fb1975', 0, 'analytic', 'pnlExplain', 'curveConfigMporFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''curveConfigMporFile'']', 384, 'string', false, 'Curve configuration at the second date', 'A file name.', 'Names the XML file with the curve configuration for the second valuation date. It can differ from the configuration of the first date, which the Setup block gives. The name curveConfigPnlFile is another name for the same parameter. The P&L analytic has the same parameter.', 'The curve configuration of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7bb8ba87-bbc9-56e2-8465-898cd07ea634', 0, 'analytic', 'pnlExplain', 'conventionsMporFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''conventionsMporFile'']', 385, 'string', false, 'Conventions at the second date', 'A file name.', 'Names the XML file with the conventions for the second valuation date. Use it when the market conventions changed between the two dates, for example after a move to a new reference rate. The name conventionsPnlFile is another name for the same parameter. Without it ORE uses the conventions of the Setup block. The P&L analytic has the same parameter.', 'The conventions of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1b8d8a51-057b-5027-8a30-e803f8dcbeb4', 0, 'analytic', 'pnlExplain', 'portfolioMporFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''portfolioMporFile'']', 386, 'string', false, 'Portfolio at the second date', 'A file name.', 'Names the XML file with the portfolio at the second valuation date. It is usually different from the portfolio of the first date. The name portfolioPnlFile is another name for the same parameter. The P&L analytic has the same parameter.', 'None. The analytic values the portfolio of the valuation date at the second date too.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1270d5c0-5434-5e51-ab8a-2bdbcb0f2521', 0, 'analytic', 'pnlExplain', 'outputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''outputFileName'']', 387, 'string', false, 'P&L explain report file', 'A file name.', 'Names the file with the P&L explain report: one row for each trade, or for each risk factor when the risk factor level report is on, with the explained parts and the remainder. The default is pnl_explain.csv, written in the output path. For example, pnl_explain.csv.', 'pnl_explain.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4543ad11-aa82-5b30-aef0-3bbeacfaa2a8', 0, 'analytic', 'pnlExplain', 'mporDays', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''mporDays'']', 388, 'integer', false, 'Days to the second date', 'A whole number of days.', 'Sets the second valuation date as a number of days after the valuation date, counted on the calendar. ORE uses it when the second date is missing. The name horizonDays is another name for the same parameter. The P&L analytic has the same parameter. For example, 10.', '10', 'A whole number of zero or more.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ae4f396e-e66b-5c5a-8cd5-44f80713e9b1', 0, 'analytic', 'pnlExplain', 'mporCalendar', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''mporCalendar'']', 389, 'string', false, 'Calendar of the second date', 'A calendar name.', 'Names the calendar that ORE uses to compute the second valuation date from the valuation date and the number of days. The name horizonCalendar is another name for the same parameter. The P&L analytic has the same parameter.', 'None. The analytic needs a calendar when it derives the date from the days.', 'A calendar name such as TARGET, US or UK.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2e1e04f6-eb72-5cca-82cb-3fa3a360749c', 0, 'analytic', 'pnlExplain', 'mporOverlappingPeriods', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''mporOverlappingPeriods'']', 390, 'boolean', false, 'Overlapping periods', 'A flag. Y uses overlapping periods.', 'Sets whether holding periods overlap. The name horizonOverlappingPeriods is another name for the same parameter. With overlapping periods each scenario starts one day after the one before, which gives many scenarios from a short history. The P&L analytic has the same parameter.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bd73918b-86f4-58ab-ab12-f18c75c34f38', 0, 'analytic', 'pnlExplain', 'dateAdjustedRiskFactors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''dateAdjustedRiskFactors'']', 391, 'string', false, 'Date adjusted risk factors', 'A comma-separated list of risk factor types.', 'Lists the types of risk factor for which ORE adjusts the scenario dates at the second valuation date relative to the first, when it computes the P&L explain. The adjustment matters for commodity curves, so that the dates refer to the same future contracts at both dates. For example, CommodityCurve. The P&L analytic has the same parameter.', 'None. ORE makes no adjustment.', 'A comma-separated list of risk factor key types such as CommodityCurve.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd7f6642a-40ce-560f-a517-8f7859d604bb', 0, 'analytic', 'pnlExplain', 'conventionsPnlOverride', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''conventionsPnlOverride'']', 392, 'string', false, 'Conventions override at the second date', 'A file name.', 'Names an XML file with convention settings that replace the matching settings of the conventions at the second date. Use it to change only the conventions that differ between the two dates and keep the rest. The file needs only the entries that change. The P&L analytic has the same parameter.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '02dc5ae0-c5ce-5ebf-9df3-d2248fed7c27', 0, 'analytic', 'pnlExplain', 'curveConfigMporOverride', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''curveConfigMporOverride'']', 393, 'string', false, 'Curve configuration override at the second date', 'A file name.', 'Names an XML file with curve settings that replace the matching settings of the curve configuration at the second date. The name curveConfigPnlOverride is another name for the same parameter. The P&L analytic has the same parameter.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '29ab3613-3e90-5830-b0e5-b500c74252a2', 0, 'analytic', 'pnlExplain', 'riskFactorLevelReporting', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''riskFactorLevelReporting'']', 394, 'boolean', false, 'Report by risk factor', 'A flag. Y breaks the explanation down by risk factor.', 'Decides whether the explanation shows the P&L for each risk factor. Use it to see which move of the market caused which part of the P&L. The report is larger, because it has a row for each trade and risk factor. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3b39598d-5394-501c-ad89-22272841d1e5', 0, 'analytic', 'pnlExplain', 'portfolioFilter', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''portfolioFilter'']', 395, 'string', false, 'Portfolio filter', 'A regular expression.', 'Limits the explanation to the trades whose portfolio id matches the regular expression. Use it to explain the P&L of one desk or one book from a portfolio file that holds many. Without it, the analytic uses the whole portfolio. For example, PF1 selects the portfolio PF1.', 'None. The analytic uses the whole portfolio.', 'A regular expression.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fd11712c-cb09-5266-9984-4558cee986a1', 0, 'analytic', 'pnlExplain', 'returnConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''returnConfigFile'']', 396, 'string', false, 'Return configuration file', 'A file name.', 'Names the XML file with the return configuration, which sets how ORE derives the shift of each risk factor between the two dates, for example as an absolute difference or as a relative or log return. Without the file ORE uses its standard return calculation.', 'None. ORE uses its standard return calculation.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9ce5aae9-bd2b-52d8-bb05-22cd18774475', 0, 'analytic', 'pnlExplain', 'historicalScenarioFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnlExplain'']/Parameter[@name=''historicalScenarioFile'']', 397, 'string', false, 'Historical scenario file', 'A file name.', 'Names the CSV file with the market scenarios of the two dates, if the explanation reads them from a file. The explanation then takes the moves of the risk factors from the file and does not build them from market data of the two dates. Without it the analytic uses the market data of the two dates.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0593ca4e-e065-56e9-9ca5-f9582cdd16e1', 0, 'analytic', 'pnl', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''active'']', 398, 'boolean', true, 'Run the P&L analytic', 'A flag. Y runs the analytic.', 'Switches the P&L analytic on or off. When it is on, the run computes the single-period P&L between the valuation date and a second valuation date: the change of the NPV of each trade. It needs market data for both dates.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a9b4d778-12ac-59c2-b08d-747abae1a83d', 0, 'analytic', 'pnl', 'mporDays', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''mporDays'']', 399, 'integer', false, 'Days to the second date', 'A whole number of days.', 'Sets the second valuation date as a number of days after the valuation date, counted on the calendar. ORE uses it when the second date is missing. The name horizonDays is another name for the same parameter. The P&L explain analytic has the same parameter. For example, 10.', '10', 'A whole number of zero or more.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'df76e2c3-135b-5dc7-b82e-1d68aa5a65bb', 0, 'analytic', 'pnl', 'mporCalendar', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''mporCalendar'']', 400, 'string', false, 'Calendar of the second date', 'A calendar name.', 'Names the calendar that ORE uses to compute the second valuation date from the valuation date and the number of days. The name horizonCalendar is another name for the same parameter. The P&L explain analytic has the same parameter.', 'None. The analytic needs a calendar when it derives the date from the days.', 'A calendar name such as TARGET, US or UK.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '50973f08-0206-589e-9754-9a3fceac8ae3', 0, 'analytic', 'pnl', 'curveConfigMporFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''curveConfigMporFile'']', 401, 'string', false, 'Curve configuration at the second date', 'A file name.', 'Names the XML file with the curve configuration for the second valuation date. It can differ from the configuration of the first date, which the Setup block gives. The name curveConfigPnlFile is another name for the same parameter. The P&L explain analytic has the same parameter.', 'The curve configuration of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5d8ea5c2-289c-51a8-a024-b9d688d23fe6', 0, 'analytic', 'pnl', 'conventionsMporFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''conventionsMporFile'']', 402, 'string', false, 'Conventions at the second date', 'A file name.', 'Names the XML file with the conventions for the second valuation date. Use it when the market conventions changed between the two dates, for example after a move to a new reference rate. The name conventionsPnlFile is another name for the same parameter. Without it ORE uses the conventions of the Setup block. The P&L explain analytic has the same parameter.', 'The conventions of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eb632705-8774-5110-9269-d95c4c9e3353', 0, 'analytic', 'pnl', 'portfolioMporFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''portfolioMporFile'']', 403, 'string', false, 'Portfolio at the second date', 'A file name.', 'Names the XML file with the portfolio at the second valuation date. It is usually different from the portfolio of the first date. The name portfolioPnlFile is another name for the same parameter. The P&L explain analytic has the same parameter.', 'None. The analytic values the portfolio of the valuation date at the second date too.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ac28d1e3-f59f-57b7-bc0a-b1a2f0210e20', 0, 'analytic', 'pnl', 'simulationConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''simulationConfigFile'']', 404, 'string', false, 'Simulation configuration file', 'A file name.', 'Names the XML file with the simulation market. It decides which market factors ORE moves from the first to the second valuation date to compute the P&L. When it is missing, ORE uses the simulation market of the scenario analytic. For example, simulation.xml. The P&L explain analytic has the same parameter.', 'The simulation market of the scenario analytic.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '60bb6206-8b4e-5667-8ce0-0ee34bd4ccfc', 0, 'analytic', 'pnl', 'outputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''outputFileName'']', 405, 'string', false, 'P&L report file', 'A file name.', 'Names the file with the P&L report: one row for each trade with the NPV at both dates and the P&L. Change it when one run writes several reports and you need to tell the files apart. The default is pnl.csv, written in the output path. For example, pnl.csv.', 'pnl.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '18301c09-168e-5cb4-8312-6a2c9219c273', 0, 'analytic', 'pnl', 'mporDate', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''mporDate'']', 406, 'date', false, 'Second valuation date', 'A date.', 'Sets the later of the two valuation dates of the P&L calculation. The first date is the valuation date of the Setup block. The market data must be available for both dates. The name pnlDate is another name for the same parameter. The P&L explain analytic has the same parameter. For example, 2023-02-14.', 'None. ORE derives the date from the number of days.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3fd06fe4-b084-52cb-aefb-086184aebbd3', 0, 'analytic', 'pnl', 'mporOverlappingPeriods', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''mporOverlappingPeriods'']', 407, 'boolean', false, 'Overlapping periods', 'A flag. Y uses overlapping periods.', 'Sets whether holding periods overlap. The name horizonOverlappingPeriods is another name for the same parameter. With overlapping periods each scenario starts one day after the one before, which gives many scenarios from a short history. The P&L explain analytic has the same parameter.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1b4a4c41-e3b6-5a36-82ae-01952776fc4f', 0, 'analytic', 'pnl', 'dateAdjustedRiskFactors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''dateAdjustedRiskFactors'']', 408, 'string', false, 'Date adjusted risk factors', 'A comma-separated list of risk factor types.', 'Lists the types of risk factor for which ORE adjusts the scenario dates at the second valuation date relative to the first, when it computes the P&L explain. The adjustment matters for commodity curves, so that the dates refer to the same future contracts at both dates. For example, CommodityCurve. The P&L explain analytic has the same parameter.', 'None. ORE makes no adjustment.', 'A comma-separated list of risk factor key types such as CommodityCurve.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b27b5039-3d25-55c3-b9f6-cb5ca6e21da0', 0, 'analytic', 'pnl', 'conventionsPnlOverride', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''conventionsPnlOverride'']', 409, 'string', false, 'Conventions override at the second date', 'A file name.', 'Names an XML file with convention settings that replace the matching settings of the conventions at the second date. Use it to change only the conventions that differ between the two dates and keep the rest. The file needs only the entries that change. The P&L explain analytic has the same parameter.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd165b16d-28e8-5e26-929b-0c65cae62f4e', 0, 'analytic', 'pnl', 'curveConfigMporOverride', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pnl'']/Parameter[@name=''curveConfigMporOverride'']', 410, 'string', false, 'Curve configuration override at the second date', 'A file name.', 'Names an XML file with curve settings that replace the matching settings of the curve configuration at the second date. The name curveConfigPnlOverride is another name for the same parameter. The P&L explain analytic has the same parameter.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '48c531c1-68c8-5b9a-99e7-4768b7c5b4ac', 0, 'analytic', 'historicalSimulationVar', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''active'']', 411, 'boolean', true, 'Run the historical simulation VaR analytic', 'A flag. Y runs the analytic.', 'Switches the historical simulation VaR analytic on or off. When it is on, the run revalues the portfolio under shifts of the risk factors taken from a history of market moves, and reads the VaR as a quantile of the resulting P&L. It needs a file of historical scenarios and the return configuration. Use N to keep the entry in the document without running it.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2323c14c-da34-57f8-b478-d480af7c55df', 0, 'analytic', 'historicalSimulationVar', 'historicalScenarioFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''historicalScenarioFile'']', 412, 'string', false, 'Historical scenario file', 'A file name.', 'Names the CSV file with the market scenarios for every date of the observation periods. The granularity of the scenarios must match the simulation market. The name scenarioFile is another name for the same parameter. For example, scenarios.csv.', 'None. The analytic needs the file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f8f88b8a-0f26-5b1f-9a5b-7cddda3fd3ca', 0, 'analytic', 'historicalSimulationVar', 'simulationConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''simulationConfigFile'']', 413, 'string', false, 'Simulation configuration file', 'A file name.', 'Names the XML file that defines the structure of the simulation market for the P&L calculation: the discount and index curves, the tenor points of the yield curves, the FX pairs and so on. For example, simulation.xml.', 'None. The analytic needs the file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0b9d0a6e-856e-598a-ab16-d184ea13e767', 0, 'analytic', 'historicalSimulationVar', 'historicalPeriod', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''historicalPeriod'']', 414, 'string', false, 'Historical period', 'An even number of dates.', 'Sets the observation periods of the history. A comma-separated list of dates with an even number of entries, for example 2017-01-17,2019-12-30. Each pair of dates is the start and the end of one observation period. The name lookbackPeriod is another name for the same parameter. The run needs a period that is one contiguous part.', 'None. The analytic needs the period.', 'A comma-separated list of dates with an even number of entries.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '425697d1-c14e-52db-8e3f-175dd1918162', 0, 'analytic', 'historicalSimulationVar', 'mporDays', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''mporDays'']', 415, 'integer', false, 'Holding period in days', 'A whole number of days.', 'Sets the number of days between two scenarios that the analytic uses to compute a P&L. This is the holding period of the VaR: the time in which the portfolio cannot be changed. Typical values are 1 and 10. For example, 10 gives a ten-day VaR, which is the period of the Basel market risk rules. The name horizonDays is another name for the same parameter.', '10', 'A whole number of zero or more.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7763d1d0-f379-5b68-a787-51b7d0a90459', 0, 'analytic', 'historicalSimulationVar', 'mporCalendar', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''mporCalendar'']', 416, 'string', false, 'Holding period calendar', 'A calendar name.', 'Names the calendar that ORE uses to compute the dates of the scenarios. The holding period counts business days of this calendar, so a ten-day period over a holiday spans more calendar days. Use the calendar of the market of the portfolio. For example, TARGET. The name horizonCalendar is another name for the same parameter.', 'The calendar of the base currency.', 'A calendar name such as TARGET, USD or UK.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b600e441-8dd5-5d0c-a53f-3f4ede95668e', 0, 'analytic', 'historicalSimulationVar', 'mporOverlappingPeriods', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''mporOverlappingPeriods'']', 417, 'boolean', false, 'Overlapping holding periods', 'A flag. Y uses overlapping periods.', 'Decides whether the holding periods overlap. With Y, a period of 10 days runs from t to t+10, the next from t+1 to t+11, and so on. With N, the periods follow each other without overlap. The name horizonOverlappingPeriods is another name for the same parameter.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bb8ec2a6-2469-5ecf-a850-e3ae2f875462', 0, 'analytic', 'historicalSimulationVar', 'quantiles', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''quantiles'']', 418, 'string', false, 'Quantiles', 'A comma-separated list of quantiles.', 'Lists the quantiles of the profit and loss distribution that the report shows. Each quantile gives one column in the output file. The 1 percent quantile is the lower tail of the P&L distribution, which is the VaR, and the 99 percent quantile is the upper tail. For example, 0.01,0.05,0.95,0.99. The parametric VaR analytic has the same parameter.', 'None. The analytic needs the list.', 'A comma-separated list of numbers between 0 and 1, for example 0.01,0.05,0.95,0.99.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a2d5c28f-e452-5630-add1-e6a5682fe5b8', 0, 'analytic', 'historicalSimulationVar', 'outputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''outputFile'']', 419, 'string', false, 'VaR report file', 'A file name.', 'Names the file with the main VaR report: one row for each portfolio, risk class and risk type with the VaR at each quantile. The parametric and the historical simulation analytic share this name: ORE reads it from the parametric block first, so set it there when you run both. For example, var.csv.', 'var.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '575be10d-23c3-53e6-ae33-e52ee5efadfe', 0, 'analytic', 'historicalSimulationVar', 'includeExpectedShortfall', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''includeExpectedShortfall'']', 420, 'boolean', false, 'Include the expected shortfall', 'A flag. Y adds the expected shortfall columns.', 'Decides whether the report also shows the expected shortfall for each quantile, in extra columns. The expected shortfall at level p is the average P&L of all scenarios at or below the VaR for p, so it shows how bad the tail is beyond the VaR. The Basel market risk rules use the expected shortfall. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cd7c0d92-bc2b-5724-b217-3a1a2ddc280a', 0, 'analytic', 'historicalSimulationVar', 'breakdown', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''breakdown'']', 421, 'boolean', false, 'Break down the VaR', 'A flag. Y breaks down the VaR.', 'Decides whether the analytic computes the VaR for each portfolio, risk class (all, interest rate, FX, inflation, equity, credit) and risk type (all, delta and gamma, vega), and not only for the whole portfolio. The parametric VaR analytic has the same parameter.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '91650b4a-584d-5cfb-8459-98e0a45ea441', 0, 'analytic', 'historicalSimulationVar', 'tradePnl', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''tradePnl'']', 422, 'boolean', false, 'Report the P&L by trade', 'A flag. Y adds the report.', 'Decides whether the analytic writes a second report with the P&L for each trade, risk class and risk type. Use it to find which trades drive the VaR. The report is large for a big portfolio and many scenarios. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b0c23198-9bcd-5d46-b3ed-03986338e6b6', 0, 'analytic', 'historicalSimulationVar', 'riskFactorBreakdown', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''riskFactorBreakdown'']', 423, 'boolean', false, 'Report the P&L by risk factor', 'A flag. Y adds the report.', 'Decides whether the analytic writes a third report with the P&L for each risk factor. Use it to find which risk factors drive the VaR, for example a single curve or a single FX rate. The report is large for many risk factors and scenarios. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ef0d042a-3a58-5278-b213-29a0bb4bc2d6', 0, 'analytic', 'historicalSimulationVar', 'riskClassBreakdown', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''riskClassBreakdown'']', 424, 'boolean', false, 'Break down by risk class', 'A flag. Y computes the VaR for each risk class.', 'Decides whether the analytic computes the VaR for each risk class and risk type (interest rate, FX, inflation, equity, credit, commodity) besides the row for the whole portfolio. Set it to N to compute only the row for the whole portfolio, which cuts the run time a lot.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7b940149-ff8d-5907-a0e1-c0b8576ab26e', 0, 'analytic', 'historicalSimulationVar', 'outputHistoricalScenarios', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''outputHistoricalScenarios'']', 425, 'boolean', false, 'Write the historical scenarios', 'A flag. Y writes the scenarios.', 'Decides whether the analytic writes the historical scenarios that it used to a report. Use it to check which dates and which shifts went into the VaR, or to rerun the scenarios in another system. The report is large, because it holds every risk factor for every scenario. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '71bae30a-0d0f-5c58-9118-81782e1e36c0', 0, 'analytic', 'historicalSimulationVar', 'includeTheta', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''includeTheta'']', 426, 'boolean', false, 'Include the theta', 'A flag. Y includes the theta in the P&L.', 'Decides whether the P&L of each scenario also includes the change of the NPV that the passing of the holding period causes, the theta. Without it the P&L shows the effect of the market move only. Switch it on when the VaR must cover the time decay too. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6af883cb-46d3-5653-82ae-2266e1e6bd67', 0, 'analytic', 'historicalSimulationVar', 'includePeriodCashflow', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''includePeriodCashflow'']', 427, 'boolean', false, 'Include the cash flows of the period', 'A flag. Y includes the cash flows.', 'Decides whether the P&L of each scenario also includes the cash flows that pay during the holding period. Without it a coupon that pays in the period is lost from the P&L. Switch it on for a VaR that measures the full change of wealth. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'baead322-de77-559f-a352-aef645caa589', 0, 'analytic', 'historicalSimulationVar', 'portfolioFilter', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''portfolioFilter'']', 428, 'string', false, 'Portfolio filter', 'A regular expression.', 'Limits the VaR to the trades whose portfolio id matches the regular expression. Without it, the analytic uses the whole portfolio. For example, PF1 selects the portfolio PF1.', 'None. The analytic uses the whole portfolio.', 'A regular expression.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd41e649e-98b2-5086-830f-b24686243118', 0, 'analytic', 'historicalSimulationVar', 'sensitivityInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''sensitivityInputFile'']', 429, 'string', false, 'Sensitivities file', 'A file name.', 'Names a CSV file with the delta, gamma and cross gamma sensitivities, in the same format as for the parametric VaR analytic. When this and the sensitivity configuration file are both set, ORE computes the historical P&Ls from the sensitivities and the historical scenario shifts and not by full revaluation.', 'None. The analytic revalues in full.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '58cb2750-cf93-59b4-848c-a17f4a0beea1', 0, 'analytic', 'historicalSimulationVar', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''sensitivityConfigFile'']', 430, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file with the sensitivity scenario setup that maps the historical moves to the risk factors of the sensitivities file. If either of the two sensitivity parameters is missing, the analytic revalues in full.', 'None. The analytic revalues in full.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b58b5a0f-2677-5d6d-88fc-b4cfce1dac1f', 0, 'analytic', 'historicalSimulationVar', 'returnConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''historicalSimulationVar'']/Parameter[@name=''returnConfigFile'']', 431, 'string', false, 'Return configuration file', 'A file name.', 'Names the XML file with the return configuration, which sets how ORE derives the shift of each risk factor from the historical scenarios, for example as an absolute difference or as a relative or log return. Use it when a risk factor needs another return type than the standard one. Without the file ORE uses its standard return calculation.', 'None. ORE uses its standard return calculation.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '67938efd-d0ac-5d47-aeb3-7f2fc89c910b', 0, 'analytic', 'amc', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''amc'']/Parameter[@name=''active'']', 432, 'boolean', false, 'AMC block active', 'A flag. ORE ignores the amc block.', 'ORE has no analytic of the type amc and does not read this block. Example files of an older layout carry it. The switch for American Monte Carlo is the parameter AMC in the simulation analytic.', 'None. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4dae689d-e89b-52b0-bd57-2576d1a0139e', 0, 'analytic', 'amc', 'pricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''amc'']/Parameter[@name=''pricingEnginesFile'']', 433, 'string', false, 'Pricing engines file in the amc block', 'A file name. ORE ignores the amc block.', 'ORE has no analytic of the type amc and does not read this block. The pricing engines for American Monte Carlo are set in the simulation analytic, with the parameter Pricing engines file for AMC.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9350cf59-65c5-573f-87a8-13d251903df3', 0, 'analytic', 'amc', 'amcTradeTypes', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''amc'']/Parameter[@name=''amcTradeTypes'']', 434, 'string', false, 'Trade types in the amc block', 'A comma-separated list of trade types. ORE ignores the amc block.', 'ORE has no analytic of the type amc and does not read this block. The trade types that American Monte Carlo covers are set in the simulation analytic, with the parameter AMC trade types.', 'None. ORE ignores the parameter, so a value has no effect.', 'A comma-separated list of trade type names.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7af3dfb7-2b2b-59d0-b470-1c33ecf82bc0', 0, 'analytic', 'scenarioGeneration', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''active'']', 435, 'boolean', true, 'Run scenario generation', 'A flag. Y runs the analytic.', 'Switches the scenario generation on or off. When it is on, the run generates market scenarios and writes statistics and distributions of them. Use it to check the scenarios of a simulation market, a stress test or a sensitivity run.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '167b73d8-4576-5c2d-b5a0-52a0cab76691', 0, 'analytic', 'scenarioGeneration', 'simulationConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''simulationConfigFile'']', 436, 'string', false, 'Simulation configuration file', 'A file name.', 'Names the XML file with the simulation market that the scenarios are for. For an exposure run the file also supplies the model and the scenario generator, unless the parameters Cross asset model file and Scenario generator file name another file. For example, simulation.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9cee28ee-cb2c-5afc-9e76-7ea2e9a5c88d', 0, 'analytic', 'scenarioGeneration', 'scenarioOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''scenarioOutputFile'']', 437, 'string', false, 'Scenario output file', 'A file name.', 'Names the file that holds all scenarios that the analytic generates through the simulation market. Each row is a risk factor on a date and a sample. The file is large for a real simulation market, so use the risk factor filter to limit it. For example, scenariodump.csv writes the scenarios to scenariodump.csv in the output path.', 'scenario.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4382d66d-65e0-5f2f-8bdd-1f668aaeac12', 0, 'analytic', 'scenarioGeneration', 'amcPathDataOutput', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''amcPathDataOutput'']', 438, 'string', false, 'AMC path data output file', 'A file name.', 'Names a file that receives the path data of the generated exposure scenarios, so that an AMC run can read it later with its path data input. The path data is the state of the model on each path and date. For example, amcBuffer.dat. ORE uses it only for the scenario type exposure.', 'None. The analytic does not write path data.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '570b1331-fa89-5410-abdf-f84dd9ebe567', 0, 'analytic', 'scenarioGeneration', 'outputStatistics', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''outputStatistics'']', 439, 'boolean', false, 'Write the statistics report', 'A flag. Y writes the report.', 'Decides whether the analytic writes a report with statistics of the generated scenarios for each risk factor and date: the minimum, the mean, the maximum, the standard deviation, the skewness and the kurtosis. Use it to check that the simulated market has the mean and the spread that the model implies. The default is Yes.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f092a55c-1a12-55b8-ac75-756a8c50b901', 0, 'analytic', 'scenarioGeneration', 'outputDistributions', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''outputDistributions'']', 440, 'boolean', false, 'Write the distribution report', 'A flag. Y writes the report.', 'Decides whether the analytic writes a report with the distribution histogram of the generated scenarios for each risk factor and date. Use it to check that the simulated distribution has the shape that the model implies. The parameter Distribution buckets sets its resolution. The default is Yes.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e6bea08d-bb1b-581a-8880-ac19a3f665df', 0, 'analytic', 'scenarioGeneration', 'scenarioType', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''scenarioType'']', 441, 'string', false, 'Scenario type', 'stress, sensitivity or exposure.', 'Selects which scenarios the analytic generates. exposure takes them from the simulation model. stress takes them from a stress test configuration. sensitivity is accepted, but release 1.8.17.0 has no scenario generation for it. The run stops if the value is none of the three.', 'exposure', 'stress, sensitivity or exposure.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2e51559d-35fa-522b-8b40-faab452368be', 0, 'analytic', 'scenarioGeneration', 'stressConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''stressConfigFile'']', 442, 'string', false, 'Stress configuration file', 'A file name.', 'Names the XML file with the stress scenarios to generate. Each scenario in the file shifts the market, and the analytic writes the shifted market as a scenario. ORE uses the file only when the scenario type is stress. For example, stresstest.xml. The same file also decides whether the stress is in the raw domain or in the par domain.', 'None. A stress run needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '34db6d6a-d55c-5bb8-8a7b-88f8e8f41041', 0, 'analytic', 'scenarioGeneration', 'scenarioPrecision', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''scenarioPrecision'']', 443, 'integer', false, 'Scenario precision', 'A whole number of decimal places.', 'Sets the number of decimal places of the numbers in the scenario output. A higher number shows more of each value and makes the file larger. The default is 8. Lower it to make the file smaller when the exact value does not matter, and raise it when you compare two runs to the last digit.', '8', 'A whole number of zero or more.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd925a459-ecff-55f5-a82a-ae5da0f0758f', 0, 'analytic', 'scenarioGeneration', 'distributionBuckets', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''distributionBuckets'']', 444, 'integer', false, 'Distribution buckets', 'A whole number.', 'Sets the number of buckets of the distribution histogram of the generated scenarios. A higher number gives a finer histogram and needs more scenarios to be stable, because each bucket must hold enough samples. The default is 20. For example, 50 gives a finer picture for a run of 10,000 samples.', '20', 'A whole number of zero or more.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c8b9001e-5882-55fe-829d-f7863dbcc422', 0, 'analytic', 'scenarioGeneration', 'outputZeroRate', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''outputZeroRate'']', 445, 'boolean', false, 'Report zero rates', 'A flag. Y reports zero rates, N reports discount factors.', 'Decides whether the statistics report and the distribution report show zero rates or discount factors for the yield curves. Zero rates are easier to compare between dates, because a discount factor falls with time and a zero rate does not. The default is No, so the reports show discount factors.', 'No. The reports show discount factors.', 'A flag, written Y or N, or true or false.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '593f06e7-1157-576a-8bf0-aed369781e6e', 0, 'analytic', 'scenarioGeneration', 'filterRiskKeys', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''filterRiskKeys'']', 446, 'string', false, 'Risk factor types in the output', 'A comma-separated list of risk factor types.', 'Limits the scenario output to the listed types of risk factor. Without it the output holds every risk factor of the simulation market and can be very large. Write the types as a comma-separated list. For example, DiscountCurve writes the discount curves only, and DiscountCurve,FXSpot adds the spot rates of the currencies.', 'None. The output holds all risk factors.', 'A comma-separated list of risk factor key types such as DiscountCurve.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ca3254e6-78b6-5821-bff4-7f5377066050', 0, 'analytic', 'scenarioGeneration', 'crossAssetModelData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''crossAssetModelData'']', 447, 'string', false, 'Cross asset model file', 'A file name.', 'Names the XML file with the cross asset model, if it sits in another file than the simulation configuration file. Use it to run one simulation setup with different models, for example a model from another calibration. ORE uses it only when the scenario type is exposure. Without the parameter ORE reads the model from the simulation configuration file.', 'The simulation configuration file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b0d01517-cd9b-5db4-bd28-09d746f6469f', 0, 'analytic', 'scenarioGeneration', 'scenarioGeneratorData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''scenarioGeneration'']/Parameter[@name=''scenarioGeneratorData'']', 448, 'string', false, 'Scenario generator file', 'A file name.', 'Names the XML file with the scenario generator, if it sits in another file than the simulation configuration file. The generator sets the time grid, the number of samples and the sequence type. ORE uses it only when the scenario type is exposure. Without the parameter ORE reads the generator from the simulation configuration file.', 'The simulation configuration file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bff253e4-28b8-5a98-9cf2-b6859826a5f2', 0, 'analytic', 'parStressConversion', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''active'']', 449, 'boolean', true, 'Run the par stress conversion', 'A flag. Y runs the analytic.', 'Switches the par stress conversion on or off. The analytic does not run a stress test. It turns a stress test definition in the par domain into one in the raw domain, so that you can apply the result again and again.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7ab5994c-f5aa-553a-bce0-2da6ea576014', 0, 'analytic', 'parStressConversion', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''marketConfigFile'']', 450, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market under which the analytic computes its results. The simulation market lists the risk factors that ORE can shift, for example the discount curves, the FX spots and the volatility surfaces, and the tenors of each. The analytic needs only the part under Market and ignores the model and the scenario generator. A risk factor that this file leaves out cannot be shifted. For example, simulation.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c54055ac-f371-5255-89c4-43249bc79113', 0, 'analytic', 'parStressConversion', 'stressConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''stressConfigFile'']', 451, 'string', false, 'Stress configuration file', 'A file name.', 'Names the XML file with the stress scenarios. Each scenario lists the shifts of the risk factors, for example a parallel move of a yield curve by 100 basis points. The same file also decides whether the stress is in the raw domain, which shifts the zero rates, or in the par domain, which shifts the par rates. For example, stresstest.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd1f5a0d7-04d5-50ee-b879-6d8fdc7377ee', 0, 'analytic', 'parStressConversion', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''sensitivityConfigFile'']', 452, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file with the sensitivity setup, in particular the par conversion sections that the conversion needs. The sections list the par instruments that define each curve, so the conversion can map a par shift to the zero rates. For example, sensitivity.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eff3b737-1b42-57cb-b308-66e2b1a3f7fd', 0, 'analytic', 'parStressConversion', 'pricingEnginesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''pricingEnginesFile'']', 453, 'string', false, 'Pricing engines file', 'A file name.', 'Names the XML file that sets the pricing engines for the analytic. The file says which model and which engine price each product, so a change here changes the NPVs behind the results. When it is missing, ORE uses the pricing engines file of the Setup block. Use it to run the analytic with other engines than the rest of the run. For example, pricingengine.xml.', 'The pricing engines file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5522571e-b7b8-5932-8d82-e909c062033b', 0, 'analytic', 'parStressConversion', 'scenarioOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''scenarioOutputFile'']', 454, 'string', false, 'Scenario output file', 'A file name. ORE ignores it.', 'ORE does not read this parameter for the par stress conversion. Example files carry it.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd1830e8b-2086-5628-b27a-3e39738a1986', 0, 'analytic', 'parStressConversion', 'outputThreshold', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''outputThreshold'']', 455, 'double', false, 'Output threshold', 'A number. ORE ignores it.', 'ORE does not read this parameter for the par stress conversion. Example files carry it.', 'None. ORE ignores the parameter, so a value has no effect.', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '23a74b80-2c84-5d13-9bf6-76ccc829f43d', 0, 'analytic', 'parStressConversion', 'stressZeroScenarioDataFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''stressZeroScenarioDataFile'']', 456, 'string', false, 'Raw domain stress file', 'A file name.', 'Names the file that receives the stress test definition in the raw domain, that is the result of the conversion. A later stress analytic can read the file and run the stress test in the zero domain. The default is parStress_ZeroStressData.xml, written in the output path. For example, results.xml.', 'parStress_ZeroStressData.xml', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a252f5e9-a1f0-5ef9-8fbe-825b18d97d7e', 0, 'analytic', 'parStressConversion', 'lowerBoundCapVols', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''lowerBoundCapVols'']', 457, 'double', false, 'Lower bound of cap volatilities', 'A number.', 'Is meant to set the lowest cap and floor volatility that the par to raw conversion tries. The conversion uses the bound 1e-8. ORE reads the value for the par stress conversion analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '1e-8', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3b9d599a-c3d4-5d63-aad2-05e1e34289ff', 0, 'analytic', 'parStressConversion', 'upperBoundCapVols', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''upperBoundCapVols'']', 458, 'double', false, 'Upper bound of cap volatilities', 'A number.', 'Is meant to set the highest cap and floor volatility that the par to raw conversion tries, as a multiple of the base volatility. The conversion uses the bound 10. ORE reads the value for the par stress conversion analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '10', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '129eebe8-bbd9-5b47-9756-d6909040a063', 0, 'analytic', 'parStressConversion', 'lowerBoundDiscountFactors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''lowerBoundDiscountFactors'']', 459, 'double', false, 'Lower bound of discount factors', 'A number.', 'Is meant to set the lowest discount factor that the par to raw conversion tries. The conversion uses the bound 1e-8. ORE reads the value for the par stress conversion analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '1e-8', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ff2c56d1-45d5-5e26-9b6a-47210fe9cc41', 0, 'analytic', 'parStressConversion', 'upperBoundDiscountFactors', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''upperBoundDiscountFactors'']', 460, 'double', false, 'Upper bound of discount factors', 'A number.', 'Is meant to set the highest discount factor that the par to raw conversion tries. The conversion uses the bound 10. ORE reads the value for the par stress conversion analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '10', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ebe2d3c5-235f-5da6-95d0-2be82cab628d', 0, 'analytic', 'parStressConversion', 'lowerBoundSurvivalProb', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''lowerBoundSurvivalProb'']', 461, 'double', false, 'Lower bound of survival probabilities', 'A number.', 'Is meant to set the lowest survival probability that the par to raw conversion tries. The conversion treats survival probabilities like discount factors and uses the bound 1e-8. ORE reads the value for the par stress conversion analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '1e-8', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cc431063-8a82-5a26-b6ed-ef18c11e36d2', 0, 'analytic', 'parStressConversion', 'upperBoundSurvivalProb', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''upperBoundSurvivalProb'']', 462, 'double', false, 'Upper bound of survival probabilities', 'A number.', 'Is meant to set the highest survival probability that the par to raw conversion tries. The conversion treats survival probabilities like discount factors and uses the bound 10. ORE reads the value for the par stress conversion analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '10', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dc7d3c60-1a67-53d2-9cad-3c5c17d6b07d', 0, 'analytic', 'parStressConversion', 'accuracy', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''parStressConversion'']/Parameter[@name=''accuracy'']', 463, 'double', false, 'Accuracy of the conversion', 'A number.', 'Is meant to set the accuracy of the root search that turns a par shift into a raw shift. The conversion uses the accuracy 1e-8. ORE reads the value for the par stress conversion analytic. The conversion of release 1.8.17.0 uses its own fixed bounds and does not take the value.', '1e-8', 'A number, written with a decimal point.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd972313d-2c60-5153-805e-4f7c62575559', 0, 'analytic', 'pfe', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''active'']', 464, 'boolean', true, 'Run the PFE analytic', 'A flag. Y runs the analytic.', 'Switches the PFE analytic on or off. When it is on, the run post-processes an NPV cube: it nets the trades, applies the collateral agreement and computes the exposure profiles and the potential future exposure. The cube comes from the simulation analytic of the same run or from a file.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7f5f87d8-4ccc-5d7f-b041-dbd8ada465b1', 0, 'analytic', 'pfe', 'csaFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''csaFile'']', 465, 'string', false, 'Netting set definitions file', 'A file name.', 'Names the XML file with the netting set definitions: the CSA details such as the margining frequency, the thresholds, the minimum transfer amounts and the margin period of risk. The post-processing reads the file, so you can change the CSA terms and see their effect on the results without a new simulation. ORE looks for the file name in the xva block, then in the pfe block and last in the Setup block. For example, netting.xml.', 'The netting set definitions file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0677186a-d6ac-53a8-b985-b0c65cb0cbce', 0, 'analytic', 'pfe', 'cubeFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''cubeFile'']', 466, 'string', false, 'Cube file', 'A file name.', 'Names the NPV cube file that the PFE analytic reads, if the run has no simulation. The file is usually the cube that an earlier simulation wrote, so you can run the post-processing again without a new simulation. ORE looks for the file in the output path of the Setup block. For example, cube.csv.gz.', 'None. When the run has a simulation, the analytic uses its cube.', 'A file name. ORE looks for the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '429e0e57-3242-522d-bbab-4515bcac7397', 0, 'analytic', 'pfe', 'scenarioFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''scenarioFile'']', 467, 'string', false, 'Scenario data file', 'A file name.', 'Names the file with the scenario data that the simulation wrote for the post-processing, such as simulated index fixings and FX rates. Variation margin and dynamic initial margin need it, because they must recompute a margin amount on each path and date. Use it when the post-processing runs apart from the simulation, together with the cube file. For example, scenariodata.csv.gz.', 'None. When the run has a simulation, the analytic uses its scenario data.', 'A file name. ORE looks for the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '921d0b7c-a38f-55bf-956c-3ee3bb51dce9', 0, 'analytic', 'pfe', 'baseCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''baseCurrency'']', 468, 'string', false, 'Base currency', 'A currency code, for example EUR.', 'Names the currency in which the analytic states every NPV, exposure and value adjustment. ORE converts an amount in another currency at the spot rate of the valuation date. Use the currency in which the desk or the capital report measures its risk. For example, EUR states all values in euro. The Setup block has a parameter of the same name, which this one overrides for this analytic.', 'The base currency of the Setup block.', 'A currency code of three letters, for example EUR.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '02c83b71-1dd0-573d-9352-0d689567d151', 0, 'analytic', 'pfe', 'exposureProfiles', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''exposureProfiles'']', 469, 'boolean', false, 'Write exposure profiles', 'A flag. Y writes the profiles for each netting set.', 'Decides whether the analytic writes an exposure report for each netting set: the expected positive and negative exposure and the potential future exposure, for each date. The profiles show how the exposure builds up and runs off over the life of the trades, so they are the main result to read for a credit limit or a capital check. The XVA analytic has the same parameter.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f09e1e99-1c38-5ca1-be4d-798f159852f7', 0, 'analytic', 'pfe', 'exposureProfilesByTrade', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''exposureProfilesByTrade'']', 470, 'boolean', false, 'Write exposure profiles by trade', 'A flag. Y writes the stand-alone profiles for each trade.', 'Decides whether the analytic writes an exposure report for each trade on its own, without the netting. With many trades this makes many files, unless Write individual exposure reports is off. The XVA analytic has the same parameter.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '65f1d3ed-7804-5a6b-801f-7362459063fb', 0, 'analytic', 'pfe', 'quantile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''quantile'']', 471, 'double', false, 'PFE confidence level', 'A number between 0 and 1.', 'Sets the confidence level of the potential future exposure (PFE) in the exposure reports. The PFE is the quantile of the positive exposure distribution on each date, so a higher level gives a larger number. For example, 0.95 reports the 95th percentile, and 0.99 reports the 99th, which a limit system often uses. The XVA analytic has the same parameter.', '0.95', 'A number, written with a decimal point.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '66536c79-5368-5cf4-b6cc-508cbe4422f7', 0, 'analytic', 'pfe', 'calculationType', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''calculationType'']', 472, 'string', false, 'Margin settlement type', 'NoLag, Symmetric, AsymmetricCVA or AsymmetricDVA.', 'Decides how ORE settles margin calls. Symmetric settles the margin of both parties after the margin period of risk. AsymmetricCVA settles the margin that we request from the counterparty with the delay and the margin that the counterparty requests from us at once. AsymmetricDVA is the reverse. NoLag turns the delay off and works together with a close-out grid in the simulation. Without a close-out grid, use one of the three others. With one, use NoLag. When there is no close-out grid, the results are correct only if the simulation grid is equally spaced with steps equal to the margin period of risk. The XVA analytic has the same parameter.', 'NoLag', 'One of NoLag, Symmetric, AsymmetricCVA or AsymmetricDVA.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '885d3306-7bfd-5dec-8910-664cc6aaf553', 0, 'analytic', 'pfe', 'allocationMethod', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''allocationMethod'']', 473, 'string', false, 'Exposure allocation method', 'None, Marginal, RelativeXVA, RelativeFairValueGross or RelativeFairValueNet.', 'Selects how ORE allocates the netting set exposure and the value adjustments to the trades in the netting set. None gives no allocation. Marginal uses the marginal method of Pykhtin and Rosen. The other three split the amount in proportion to the XVA of the trade, to its gross fair value or to its net fair value. The XVA analytic has the same parameter.', 'None', 'One of None, Marginal, RelativeXVA, RelativeFairValueGross or RelativeFairValueNet.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '684223d8-dea3-5dce-8b0b-0931e4e67e03', 0, 'analytic', 'pfe', 'marginalAllocationLimit', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''marginalAllocationLimit'']', 474, 'double', false, 'Marginal allocation limit', 'A number.', 'Sets a cutoff for the marginal allocation. The marginal method breaks down when the value of the netting set is close to zero while its exposure is not. Below this absolute value, ORE splits the exposure equally among the trades. The parameter has an effect only when the allocation method is Marginal. The XVA analytic has the same parameter.', '1.0', 'A number, written with a decimal point.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5aab0cbd-26ef-570a-9e54-3ef1b641bf5e', 0, 'analytic', 'pfe', 'exerciseNextBreak', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''exerciseNextBreak'']', 475, 'boolean', false, 'Exercise at the next break', 'A flag. Y ends each trade at its next break date.', 'Decides whether ORE ends all trades at their next break date before it aggregates them. Use it to model a counterparty relationship in which each party can end a trade at its break dates. A trade that ends early adds no exposure after its break, so the profiles are lower than with the full maturity. The default is No, so every trade runs to maturity. The XVA analytic has the same parameter.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '305e02ad-7369-50d2-b2aa-511e63bc5c29', 0, 'analytic', 'pfe', 'rawCubeOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''rawCubeOutputFile'']', 476, 'string', false, 'Raw cube report file', 'A file name.', 'Names the file for the trade NPV cube as a text file with one row for each trade, date and sample. Setting it switches the report on. Leave it out to skip the file. The file is for further analysis and can be very large. The XVA analytic has the same parameter.', 'None. The analytic does not write the file.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '254681f8-484c-53b4-a488-2bfde7f7feef', 0, 'analytic', 'pfe', 'netCubeOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''netCubeOutputFile'']', 477, 'string', false, 'Net cube report file', 'A file name.', 'Names the file for the aggregated NPV cube as a text file with one row for each netting set, date and sample, after the collateral. Setting it switches the report on. Leave it out to skip the file. The XVA analytic has the same parameter.', 'None. The analytic does not write the file.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '346c4972-6850-5bb1-b83b-d0dbdabba325', 0, 'analytic', 'pfe', 'useDoublePrecisionCubes', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''useDoublePrecisionCubes'']', 478, 'boolean', false, 'Double precision cubes', 'A flag. ORE ignores it in the pfe block.', 'The user guide shows this parameter in the pfe block, but ORE reads it only from the xva block. A value in the pfe block has no effect in release 1.8.17.0.', 'No. ORE ignores the parameter, so a value has no effect.', 'A flag, written Y or N, or true or false.', '1.8.13.1', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4d2ed971-b19a-5a92-9529-84b71eef3cda', 0, 'analytic', 'pfe', 'exposureProfilesUseCloseOutValues', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''exposureProfilesUseCloseOutValues'']', 479, 'boolean', false, 'Exposure profiles use close-out values', 'A flag. Y uses the close-out values.', 'Decides whether the exposure profiles use the close-out value of a trade, which is its value at the end of the margin period of risk, instead of its value at the default date. It needs a simulation with a close-out grid. The XVA analytic has the same parameter.', 'No. The profiles use the values at the default date.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '988bf07d-3da2-578b-8518-7a21e35908b4', 0, 'analytic', 'pfe', 'writeIndividualExposureReports', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''writeIndividualExposureReports'']', 480, 'boolean', false, 'Write individual exposure reports', 'A flag. Y writes one report for each trade and netting set.', 'Decides whether the analytic writes one exposure report for each trade and for each netting set. When it is N, the analytic writes one report for all trades and one for all netting sets. Switch it off for a large portfolio to avoid a very large number of files. The XVA analytic has the same parameter.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.15.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5abfb3aa-6fbf-5f6e-b38b-87284ca828ec', 0, 'analytic', 'pfe', 'collateralBalancesFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''pfe'']/Parameter[@name=''collateralBalancesFile'']', 481, 'string', false, 'Collateral balances file', 'A file name.', 'Names the XML file with the current variation margin and initial margin balances for each netting set. The analytic uses them as the margin at the valuation date. ORE looks for the file name in the xva block, then in the pfe block and last in the Setup block. For example, collateralbalances.xml.', 'The collateral balances file of the Setup block.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '507e3e52-4eea-50d0-b52a-d12d90a6432f', 0, 'analytic', 'crif', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''active'']', 482, 'boolean', true, 'Run the CRIF generation', 'A flag. Y runs the analytic.', 'Switches the CRIF generation on or off. The analytic writes a CRIF file, the input for the SIMM. It is based on a par sensitivity analysis with a SIMM-specific sensitivity configuration, and then labels the sensitivities so that the file has the CRIF format of ISDA. The generation covers interest rate and FX risk only.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9089aa76-eebb-575e-a528-ee9d194f868b', 0, 'analytic', 'crif', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''marketConfigFile'']', 483, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market for the sensitivity analysis. The analytic uses the same market and sensitivity settings as the sensitivity analytic and overwrites its settings. For example, crifmarket.xml.', 'None. The analytic needs the file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a6e0fdf0-b621-5d2c-94da-a153f7d25ff8', 0, 'analytic', 'crif', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''sensitivityConfigFile'']', 484, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file with the SIMM sensitivity configuration: the risk factors, the shift types and sizes. The CRIF generation computes the sensitivities with this setup and then writes them in the CRIF format. For example, sensitivity.xml. The analytic needs this file.', 'None. The analytic needs the file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f000ffbc-b438-523f-927f-a6fe70197ff0', 0, 'analytic', 'crif', 'baseCurrency', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''baseCurrency'']', 485, 'string', false, 'Base currency', 'A currency code. ORE ignores it in the crif block.', 'ORE does not read this parameter in the crif block. The base currency of the Setup block applies.', 'None. ORE ignores the parameter, so a value has no effect.', 'A currency code of three letters, for example EUR.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '88885b6a-5381-5c8c-a8ce-95a04a5bebcb', 0, 'analytic', 'crif', 'simmVersion', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''simmVersion'']', 486, 'string', false, 'SIMM version', 'A SIMM version, for example 2.7.', 'Selects the SIMM version for the CRIF. ORE reads it from the first of the blocks crif, saccr, simm (parameter version) and portfolioDetails (parameter version) that has a value. The run stops if none of them has one.', 'None. The parameter is mandatory.', 'A SIMM version such as 2.6.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0d2f6a93-dc06-5988-af2e-ac603105bd1d', 0, 'analytic', 'crif', 'crifOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''crifOutputFile'']', 487, 'string', false, 'CRIF output file', 'A file name. ORE ignores it.', 'ORE does not read this parameter in any release. Example files carry it. The CRIF analytic writes its result as a report with a fixed name.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e833d09a-f7ee-57d5-9e47-69032769030e', 0, 'analytic', 'crif', 'nameMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''nameMappingInputFile'']', 488, 'string', false, 'Name mapping file', 'A file name.', 'Names the file that maps the names in the portfolio to the names of the CRIF. Without it ORE uses the names as they are. ORE reads it from the first of the blocks crif, saccr, simm, npv and Setup that has a value.', 'None. ORE uses the names as they are.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd161b330-7697-5504-8b8e-ac68d4a20965', 0, 'analytic', 'crif', 'bucketMappingInputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''bucketMappingInputFile'']', 489, 'string', false, 'Bucket mapping file', 'A file name.', 'Names the file that maps risk factors to the SIMM buckets of the CRIF. Without it ORE uses the standard buckets. ORE reads it from the first of the blocks crif, saccr, simm, npv and Setup that has a value.', 'None. ORE uses the standard SIMM buckets.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd51e68a8-5705-51b4-bd89-77c281f5436c', 0, 'analytic', 'crif', 'applySimmExemptions', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''applySimmExemptions'']', 490, 'boolean', false, 'Apply SIMM exemptions', 'A flag. Y applies the exemptions.', 'Decides whether the CRIF generation applies the SIMM exemptions and writes a report of what it exempted. Some products or risk factors are exempt from the SIMM under the rules of ISDA, for example certain FX products. With Yes, the CRIF leaves out the exempt sensitivities. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7feee120-7688-50a1-9c27-3d88357396f8', 0, 'analytic', 'crif', 'computeTheta', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crif'']/Parameter[@name=''computeTheta'']', 491, 'boolean', false, 'Compute theta', 'A flag. Y computes the theta.', 'Decides whether the sensitivity calculation behind the CRIF also computes the theta. ORE reads the parameter from the sensitivity block, the simm block or the crif block, in this order, and one value serves all three analytics.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '72af28e9-a0dd-510b-ad99-5e8c6761b3da', 0, 'analytic', 'cashflownpv', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''cashflownpv'']/Parameter[@name=''active'']', 492, 'boolean', true, 'Run the cash flow NPV analytic', 'A flag. Y runs the analytic.', 'Switches the cash flow NPV analytic on or off. When it is on, the run builds the cash flow report and adds up, for each trade, the present value of the cash flows up to the horizon. The result is one row for each trade with its NPV in the base currency.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3ac4997b-f44b-59b7-a3e8-5cafd1aa47ab', 0, 'analytic', 'cashflownpv', 'cashFlowHorizon', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''cashflownpv'']/Parameter[@name=''cashFlowHorizon'']', 493, 'date', false, 'Cash flow horizon', 'A date.', 'Sets the last pay date that the report counts. ORE adds up the present value of the cash flows of each trade that pay after the valuation date and on or before this date. For example, 2027-12-31 counts the cash flows up to the end of 2027. The cash flow analytic has a parameter of the same name.', 'None. Without a horizon the report counts no cash flow, so every present value is 0.', 'A date, written as YYYY-MM-DD or YYYYMMDD.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '47b3927c-f793-5085-aec1-ad3bf95c651f', 0, 'analytic', 'sensitivityStress', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivityStress'']/Parameter[@name=''active'']', 494, 'boolean', true, 'Run the stressed sensitivity analytic', 'A flag. Y runs the analytic.', 'Switches the stressed sensitivity analytic on or off. It combines the stress test and the sensitivity analysis. For each stress scenario, it replaces the market of the valuation date with the simulation market shifted by the scenario, and runs the sensitivity calculation on it.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '59ff5753-c8b5-538a-bc6b-b24a20b11a59', 0, 'analytic', 'sensitivityStress', 'marketConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivityStress'']/Parameter[@name=''marketConfigFile'']', 495, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market under which the analytic computes its results. The simulation market lists the risk factors that ORE can shift, for example the discount curves, the FX spots and the volatility surfaces, and the tenors of each. The analytic needs only the part under Market and ignores the model and the scenario generator. A risk factor that this file leaves out cannot be shifted. For example, simulation.xml. For each stress scenario the analytic replaces the market of the valuation date with this simulation market, shifted by the scenario, and runs the sensitivity calculation on it.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b55b129f-c8ad-5f6a-a5d3-1c21efbeb097', 0, 'analytic', 'sensitivityStress', 'stressConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivityStress'']/Parameter[@name=''stressConfigFile'']', 496, 'string', false, 'Stress configuration file', 'A file name.', 'Names the XML file with the stress scenarios. Each scenario lists the shifts of the risk factors, for example a parallel move of a yield curve by 100 basis points. The same file also decides whether the stress is in the raw domain, which shifts the zero rates, or in the par domain, which shifts the par rates. For example, stresstest.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fb27e1c9-078f-5280-b434-795c77bbd113', 0, 'analytic', 'sensitivityStress', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivityStress'']/Parameter[@name=''sensitivityConfigFile'']', 497, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file that sets the sensitivity calculation, as for the sensitivity analytic. The analytic runs the calculation once for each stress scenario, so the cost is the cost of one sensitivity run times the number of scenarios. For example, sensitivity.xml.', 'None. The analytic needs this file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8ba8748e-66af-5686-b3c7-c9b9b69708eb', 0, 'analytic', 'sensitivityStress', 'calcBaseScenario', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivityStress'']/Parameter[@name=''calcBaseScenario'']', 498, 'boolean', false, 'Compute the base scenario', 'A flag. Y also computes the unshifted scenario.', 'Decides whether the analytic also computes the sensitivities of the unshifted base scenario, next to those of the stress scenarios. Use it to compare the sensitivities before and after a stress in one file. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a4ca6e8d-2bfc-5aa6-bd30-d8f14a389ffd', 0, 'analytic', 'sensitivityStress', 'scenarioOutputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''sensitivityStress'']/Parameter[@name=''scenarioOutputFile'']', 499, 'string', false, 'Stressed sensitivity result file', 'A file name.', 'Names the file with the result of the stressed sensitivity calculation: the sensitivities of each trade under each stress scenario. The default is sensitivity_stress.csv, written in the output path.', 'sensitivity_stress.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cdb92d3c-ee23-5eea-bea6-20d26decc54d', 0, 'analytic', 'correlation', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''active'']', 500, 'boolean', true, 'Run the correlation analytic', 'A flag. Y runs the analytic.', 'Switches the correlation analytic on or off. It computes a correlation matrix of the risk factors from historical scenarios, as the correlation of the moves over the horizon. The XVA analytic can run it to get the correlations of its model. Use N to keep the entry in the document without running it.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '89f3c323-5dfb-56bf-ac0e-cdfcafede940', 0, 'analytic', 'correlation', 'correlation_method', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''correlation_method'']', 501, 'string', false, 'Correlation method', 'Pearson or Kendall-Rank.', 'Selects the method for the correlation matrix. Pearson is the standard linear correlation, which reacts strongly to outliers. Kendall-Rank is a rank correlation, which depends on the order of the moves and not on their size, so it is steadier when the data has outliers. The default is Pearson. The name correlationMethod is another name for the same parameter.', 'Pearson', 'Pearson or Kendall-Rank.', '1.8.14.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7b72c08b-ccf6-51fb-8a15-f42224a4a71e', 0, 'analytic', 'correlation', 'scenarioCorrSimulation', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''scenarioCorrSimulation'']', 502, 'string', false, 'Simulation market file', 'A file name.', 'Names the XML file with the simulation market for the correlation calculation. The market lists the risk factors, so the file decides which factors the matrix covers. The name scenarioSimulationUri is another name for the same parameter. For example, simulation.xml. The analytic needs this file.', 'None. The analytic needs the file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bc629ea9-f313-5237-8690-b41f7ec74d55', 0, 'analytic', 'correlation', 'historicalScenarioFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''historicalScenarioFile'']', 503, 'string', false, 'Historical scenario file', 'A file name.', 'Names the CSV file with the market scenarios for every date of the observation period. The granularity of the scenarios must match the simulation market, and each yield curve tenor is a discount factor. The name scenarioFile is another name for the same parameter. For example, scenarios.csv.', 'None. The analytic needs the file.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5232487b-9b09-580a-a1bd-1cc545f1940a', 0, 'analytic', 'correlation', 'sensitivityConfigFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''sensitivityConfigFile'']', 504, 'string', false, 'Sensitivity configuration file', 'A file name.', 'Names the XML file with the sensitivity setup for the analysis at the valuation date. The file lists the risk factors and the shift sizes. For example, sensitivity.xml. It is optional, and the analytic uses it only for the analysis at the valuation date.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ffd8613c-8059-57f5-b461-cc7798cf7b5c', 0, 'analytic', 'correlation', 'historicalPeriod', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''historicalPeriod'']', 505, 'string', false, 'Historical period', 'Two dates.', 'A comma-separated list of dates with an even number of entries, for example 2017-01-17,2019-12-30. Each pair of dates is the start and the end of one observation period. The correlation analytic needs one contiguous period. The names lookbackPeriod, benchmarkVarPeriod and benchmarkPeriod are other names for the same parameter. The run stops if the period is missing.', 'None. The parameter is mandatory.', 'A comma-separated list of dates.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fe142caa-51c7-51b6-8489-53541f703efd', 0, 'analytic', 'correlation', 'mporDays', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''mporDays'']', 506, 'integer', false, 'Horizon in days', 'A whole number of days.', 'Sets the length of the horizon over which the analytic measures the moves of the risk factors, in days on the calendar. The correlation is the correlation of the moves over this horizon, so a longer horizon smooths daily noise and gives fewer observations. The default is 10. The name horizonDays is another name for the same parameter.', '10', 'A whole number of zero or more.', '1.8.11.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ebedad80-da23-5209-b58a-16c38498a90b', 0, 'analytic', 'correlation', 'mporCalendar', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''mporCalendar'']', 507, 'string', false, 'Horizon calendar', 'A calendar name.', 'Names the calendar that ORE uses to count the days of the horizon. Use the calendar of the market of the risk factors. For example, TARGET. The name horizonCalendar is another name for the same parameter. Without a value ORE takes the calendar of the base currency.', 'The calendar of the base currency.', 'A calendar name such as TARGET, USD or UK.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dd6ee847-0f2a-5639-b88a-d4c03fab8967', 0, 'analytic', 'correlation', 'filterCamCorrelationScenarioTenor', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''filterCamCorrelationScenarioTenor'']', 508, 'string', false, 'Tenor filter for the output', 'A JSON object.', 'Limits the tenors of the correlation output. The value is a JSON object that maps regular expressions to tenors. ORE matches the expressions against the risk factor keys, written as KeyType/Name, in reverse order, so the last entry has the highest priority. A risk factor without a match keeps all tenors. For example, {"DiscountCurve/.*":"5Y", "DiscountCurve/USD/.*":"3Y", "IndexCurve/USD-FedFunds":"10Y"}.', 'None. All tenors are included.', 'A JSON object of regular expressions and tenors.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '626bde43-c548-549e-b0b3-530eafb772e6', 0, 'analytic', 'correlation', 'outputFile', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''outputFile'']', 509, 'string', false, 'Correlation report file (older name)', 'A file name. ORE ignores it.', 'ORE reads the file name from the parameter outputFileName and does not read this one. The user guide and the examples use this name, so a document with this name still writes correlation.csv.', 'None. ORE ignores the parameter, so a value has no effect.', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '17b79f73-866d-56dd-a8c8-bfa0f0c96946', 0, 'analytic', 'correlation', 'outputFileName', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''outputFileName'']', 510, 'string', false, 'Correlation report file', 'A file name.', 'Names the file with the correlation matrix: one row for each pair of risk factors with their correlation. The default is correlation.csv, written in the output path. For example, correlation.csv.', 'correlation.csv', 'A file name, written without a directory. ORE writes the file in the output path of the Setup block.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7752deef-a8ec-53a4-adb1-278ed24eae30', 0, 'analytic', 'correlation', 'mporOverlappingPeriods', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''mporOverlappingPeriods'']', 511, 'boolean', false, 'Overlapping horizons', 'A flag. Y uses overlapping horizons.', 'Decides whether the horizons overlap. The name horizonOverlappingPeriods is another name for the same parameter. With overlapping horizons each observation starts one day after the one before, which gives many observations from a short history. The observations are then not independent. The default is Yes.', 'Yes.', 'A flag, written Y or N, or true or false.', '1.8.12.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eee10550-976a-5667-b281-8ebbfbceadde', 0, 'analytic', 'correlation', 'allowPartialScenarios', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''correlation'']/Parameter[@name=''allowPartialScenarios'']', 512, 'boolean', false, 'Allow partial scenarios', 'A flag. Y accepts scenarios that touch only part of the market.', 'Decides whether the simulated market accepts scenarios that do not set every risk factor. Historical data often lacks a few risk factors on some dates. With Yes, the market accepts such a scenario. With No, it accepts only scenarios that set every risk factor. The default is No.', 'No.', 'A flag, written Y or N, or true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ddd504b5-bacd-57b5-9d14-7c872da699b3', 0, 'analytic', 'stressedSimm', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stressedSimm'']/Parameter[@name=''active'']', 513, 'boolean', true, 'Run the stressed SIMM analytic', 'A flag. Y runs the analytic.', 'Switches the stressed SIMM analytic on or off. It computes the SIMM under stress scenarios, as the margin that the firm would owe in a stressed market. It reads the other SIMM settings from the simm block, so the version and the calibration are those of the plain SIMM. Use N to keep the entry in the document without running it.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'de6031ff-431f-5821-8a87-3fc6354178c1', 0, 'analytic', 'stressedSimm', 'stressedSimmScenarioData', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stressedSimm'']/Parameter[@name=''stressedSimmScenarioData'']', 514, 'string', false, 'Stress scenario file', 'A file name.', 'Names the XML file with the stress scenarios for the stressed SIMM. Each scenario shifts the market, and the analytic recomputes the sensitivities and the margin under it. The run stops if the file is missing. For example, stressedsimm.xml.', 'None. The parameter is mandatory.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7855ee38-5f16-5899-ace3-93814946eb41', 0, 'analytic', 'stressedSimm', 'version', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''stressedSimm'']/Parameter[@name=''version'']', 515, 'string', false, 'SIMM version', 'A SIMM version, for example 2.6.', 'Selects the SIMM version for the stressed SIMM. Use the same version as for the plain SIMM, so that the two margins are comparable. The run stops if no version is set. ORE supports the SIMM versions 1.0, 1.1, 1.2, 1.3, 1.3.38, 2.0, 2.1, 2.2, 2.3, 2.4, 2.5, 2.5A, 2.6 and 2.6.5.', 'None. The parameter is mandatory.', 'A SIMM version such as 2.6.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5abf6173-275e-5343-b08c-9280e5642864', 0, 'analytic', 'simmBacktest', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simmBacktest'']/Parameter[@name=''active'']', 516, 'boolean', true, 'Run the SIMM backtest', 'A flag. Y runs the analytic.', 'Switches the SIMM backtest on or off. In release 1.8.17.0 ORE reads the switch, but the open source release has no analytic of this name, so a run with Y fails with the error Invalid analytic name, unless an extension library provides the analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6b9a637c-ffe9-5f12-ae91-ecbbb3490ce9', 0, 'analytic', 'simmBacktest', 'crif', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simmBacktest'']/Parameter[@name=''crif'']', 517, 'string', false, 'CRIF file', 'A file name.', 'Names the CRIF file for the SIMM backtest. ORE reads the parameter, and the open source release has no analytic of this type, so a value has no effect there. Another build can use the file to compare the margin that the SIMM implies with the realised moves.', 'None.', 'A file name. ORE looks for the file in the input path of the Setup block.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0084242e-600f-531c-8658-35ce582004a1', 0, 'analytic', 'simmOptimization', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''simmOptimization'']/Parameter[@name=''active'']', 518, 'boolean', true, 'Run the SIMM optimisation analytic', 'A flag. Y runs the analytic.', 'Switches the SIMM optimisation analytic on or off. ORE 1.8.17.0 reads the switch, but the open source release has no analytic of this name, so a run with Y fails with the error Invalid analytic name, unless an extension library provides the analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ab163733-0dd0-5cfd-b611-99bc14d4cfe4', 0, 'analytic', 'totalIM', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''totalIM'']/Parameter[@name=''active'']', 519, 'boolean', true, 'Run the total initial margin analytic', 'A flag. Y runs the analytic.', 'Switches the total initial margin analytic on or off. ORE 1.8.17.0 reads the switch, but the open source release has no analytic of this name, so a run with Y fails with the error Invalid analytic name, unless an extension library provides the analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '30e45737-9fb6-5d5b-a265-f472ad73f258', 0, 'analytic', 'imImpact', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''imImpact'']/Parameter[@name=''active'']', 520, 'boolean', true, 'Run the initial margin impact analytic', 'A flag. Y runs the analytic.', 'Switches the initial margin impact analytic on or off. ORE 1.8.17.0 reads the switch, but the open source release has no analytic of this name, so a run with Y fails with the error Invalid analytic name, unless an extension library provides the analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9bd8376b-c10c-501e-9bea-af6d01238420', 0, 'analytic', 'crifToTrade', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''crifToTrade'']/Parameter[@name=''active'']', 521, 'boolean', true, 'Run the CRIF to trade analytic', 'A flag. Y runs the analytic.', 'Switches the CRIF to trade analytic on or off. ORE 1.8.17.0 reads the switch, but the open source release has no analytic of this name, so a run with Y fails with the error Invalid analytic name, unless an extension library provides the analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c152a98d-27f9-5657-a741-c381c7b5088d', 0, 'analytic', 'frtb', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''frtb'']/Parameter[@name=''active'']', 522, 'boolean', true, 'Run the FRTB analytic', 'A flag. Y runs the analytic.', 'Switches the FRTB analytic on or off. ORE 1.8.17.0 reads the switch, but the open source release has no analytic of this name, so a run with Y fails with the error Invalid analytic name, unless an extension library provides the analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ddb34ce0-e517-56ad-85ad-420b6a1483eb', 0, 'analytic', 'frtbCrif', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''frtbCrif'']/Parameter[@name=''active'']', 523, 'boolean', true, 'Run the FRTB CRIF analytic', 'A flag. Y runs the analytic.', 'Switches the FRTB CRIF analytic on or off. ORE 1.8.17.0 reads the switch, but the open source release has no analytic of this name, so a run with Y fails with the error Invalid analytic name, unless an extension library provides the analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd0ade288-1a17-525c-b403-23728502f2d6', 0, 'analytic', 'npvLagged', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''npvLagged'']/Parameter[@name=''active'']', 524, 'boolean', true, 'Run the lagged NPV analytic', 'A flag. Y runs the analytic.', 'Switches the lagged NPV analytic on or off. ORE 1.8.17.0 reads the switch, but the open source release has no analytic of this name, so a run with Y fails with the error Invalid analytic name, unless an extension library provides the analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c9b9351e-faa9-564d-8d57-6dc4b7c1799b', 0, 'analytic', 'fixingEstimate', 'active', 'ore.xsd', '/ORE/Analytics/Analytic[@type=''fixingEstimate'']/Parameter[@name=''active'']', 525, 'boolean', true, 'Run the fixing estimate analytic', 'A flag. Y runs the analytic.', 'Switches the fixing estimate analytic on or off. ORE 1.8.17.0 reads the switch, but the open source release has no analytic of this name, so a run with Y fails with the error Invalid analytic name, unless an extension library provides the analytic.', 'No. The analytic does not run.', 'A flag, written Y or N, or true or false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cdf362e6-ec17-5641-aa73-5173b0f443ae', 0, 'EngineParameters', 'AmericanSwaption', 'BrownianBridgeOrdering', 'ore.xsd', '/PricingEngines/Product[@type=''AmericanSwaption'']/EngineParameters/Parameter[@name=''BrownianBridgeOrdering'']', 1, 'string', true, 'Brownian bridge ordering', 'Variate ordering for Brownian bridges, can be Steps+, Factors+, Diagonal+.', 'Variate ordering for Brownian bridges, can be Steps+, Factors+, Diagonal+.', 'Steps', 'One of: Factors, Steps, Diagonal.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ebc71ab8-1e41-5b23-a383-aef910827992', 0, 'EngineParameters', 'AmericanSwaption', 'MesherEpsilon', 'ore.xsd', '/PricingEngines/Product[@type=''AmericanSwaption'']/EngineParameters/Parameter[@name=''MesherEpsilon'']', 2, 'double', true, 'Mesher epsilon', 'Determines the covered probability mass, mass outside state grid is Phi^-1(1-2epsilon).', 'Determines the covered probability mass, mass outside state grid is Phi^-1(1-2epsilon).', '1E-4', 'A number.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f3725dd4-a310-54d7-bbcc-dc8b57017ec4', 0, 'EngineParameters', 'AmericanSwaption', 'MinObsDate', 'ore.xsd', '/PricingEngines/Product[@type=''AmericanSwaption'']/EngineParameters/Parameter[@name=''MinObsDate'']', 3, 'boolean', true, 'Min obs date', 'If true the conditional expectation of each cashflow is taken from the minimum possible observation date (i.e.', 'If true the conditional expectation of each cashflow is taken from the minimum possible observation date (i.e. the latest exercise or simulation date before the cashflow''s event date); recommended setting is true+.', 'true', 'One of: true, false.', '1.8.9.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fe08697b-4e30-5703-9bc7-d3dbe5cea7b0', 0, 'EngineParameters', 'AmericanSwaption', 'Pricing.Samples', 'ore.xsd', '/PricingEngines/Product[@type=''AmericanSwaption'']/EngineParameters/Parameter[@name=''Pricing.Samples'']', 4, 'integer', true, 'Pricing samples', 'The number of samples to be used for the pricing phase.', 'The number of samples to be used for the pricing phase. If this number is zero, no pricing run is performed, instead the (T0) NPV is estimated from the training phase (this result is used to fill the T0 slice of the NPV cube).', '0', 'A number.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b8057b22-5627-5952-be21-15d988e72927', 0, 'EngineParameters', 'AmericanSwaption', 'Pricing.Seed', 'ore.xsd', '/PricingEngines/Product[@type=''AmericanSwaption'']/EngineParameters/Parameter[@name=''Pricing.Seed'']', 5, 'integer', true, 'Pricing seed', 'The seed for the random number generation in the pricing.', 'The seed for the random number generation in the pricing.', '17', 'A number.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '75ec23b1-9f48-50f2-a224-696379f25561', 0, 'EngineParameters', 'AmericanSwaption', 'Pricing.Sequence', 'ore.xsd', '/PricingEngines/Product[@type=''AmericanSwaption'']/EngineParameters/Parameter[@name=''Pricing.Sequence'']', 6, 'string', true, 'Pricing sequence', 'The sequence type for the pricing phase, same values allowed as for training.', 'The sequence type for the pricing phase, same values allowed as for training.', 'SobolBrownianBridge', 'One of: MersenneTwister, MersenneTwisterAntithetic, Sobol, SobolBrownianBridge, Burley2020SobolBrownianBridge.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0ef35418-c0cd-55f7-bf00-9ea69406ec98', 0, 'EngineParameters', 'AmericanSwaption', 'RegressorModel', 'ore.xsd', '/PricingEngines/Product[@type=''AmericanSwaption'']/EngineParameters/Parameter[@name=''RegressorModel'']', 7, 'string', false, 'Regressor model', 'Simple, LaggedFX.', 'Simple, LaggedFX. If not given, it defaults to Simple. Depending on the choice the regressor is built as follows: beginitemize.', 'Simple', 'One of: Simple, Lagged, LaggedIR, LaggedFX, LaggedEQ.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c94f3ef6-a6b3-5ed9-932c-c1cd3994ccc6', 0, 'EngineParameters', 'AmericanSwaption', 'Scheme', 'ore.xsd', '/PricingEngines/Product[@type=''AmericanSwaption'']/EngineParameters/Parameter[@name=''Scheme'']', 8, 'string', true, 'Scheme', 'The finite difference scheme to use.', 'The finite difference scheme to use.', 'Douglas', 'One of: CrankNicolson, Hundsdorfer, Douglas, CraigSneyd, ModifiedCraigSneyd, ImplicitEuler, ExplicitEuler, MethodOfLines, TrBDF2.', '1.8.7.0', null),
