        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eb8e004a-c029-5261-bf93-4e92328c3362', 0, 'EngineParameters', 'BondFutureOption', 'SensitivityTemplate', 'ore.xsd', '/PricingEngines/Product[@type=''BondFutureOption'']/EngineParameters/Parameter[@name=''SensitivityTemplate'']', 189, 'string', false, 'Sensitivity template', 'The sensitivity template of the product.', 'The sensitivity template of the product. The sensitivity configuration sets shift sizes and schemes for each template.', 'Not set in the examples.', 'The code of a sensitivity template.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8d623adb-cf81-5575-923e-9f6749bbdcfe', 0, 'EngineParameters', 'BondFutureOption', 'SeparateCallPutVols', 'ore.xsd', '/PricingEngines/Product[@type=''BondFutureOption'']/EngineParameters/Parameter[@name=''SeparateCallPutVols'']', 190, 'string', false, 'Separate call put vols', 'This parameter can be set to true or false or to a regex inclusion pattern.', 'This parameter can be set to true or false or to a regex inclusion pattern. If set to false, the default, the same volatility surface is used for puts and calls. If set to true, there will be a separate volatility surface used to price puts and calls on the same underlying bond future contract. Which surface is picked depends on the option type of the trade. If set to a regex pattern, all bond future option trades where the underlying contract name matches the regex will use a volatility surface for puts if the option type is a put and a volatility surface for calls if the option type is a call. Obviously, the bond future volatility structures need to be configured in a way that matches the setting here. See the bond future volatility curve configuration for details on how to set these up. The convention is generally to use the underlying bond future contract name as the curve ID of the bond future volatility curve where only one surface is needed for that contract. Where a separate call and put surface is needed for the contract, the bond future contract name should be suffixed with _CALL and _PUT respectively.', 'true', 'One of: true, false.', '1.8.17.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '772ad10d-c9ab-5533-ad15-05b37f84ad37', 0, 'EngineParameters', 'BondFutureOptionAmerican', 'DampingSteps', 'ore.xsd', '/PricingEngines/Product[@type=''BondFutureOptionAmerican'']/EngineParameters/Parameter[@name=''DampingSteps'']', 191, 'integer', true, 'Damping steps', 'Number of damping steps taken by FD solver.', 'Number of damping steps taken by FD solver.', '0', 'A number.', '1.8.7.0', null),
