        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f74e9a90-9968-5085-b60b-f3653602d1ae', 0, 'EngineParameters', 'IborRangeAccrualLeg', 'ByCallSpread', 'ore.xsd', '/PricingEngines/Product[@type=''IborRangeAccrualLeg'']/EngineParameters/Parameter[@name=''ByCallSpread'']', 559, 'boolean', false, 'By call spread', 'If true, the range accrual condition is priced using a call-spread approximation, which naturally incorporates the volatility smile (each spread leg is priced at its own strike vol).', 'If true, the range accrual condition is priced using a call-spread approximation, which naturally incorporates the volatility smile (each spread leg is priced at its own strike vol). If false, a Black--Scholes digital pricing is used: the digital value is computed analytically using the volatility at the strike, without accounting for the slope of the smile. Defaults to true if omitted. Allowable values: true, false.', 'true', 'One of: true, false.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1eee5226-29c3-516e-9e9a-88e79b7e5a64', 0, 'EngineParameters', 'IborRangeAccrualLeg', 'CallSpreadEps', 'ore.xsd', '/PricingEngines/Product[@type=''IborRangeAccrualLeg'']/EngineParameters/Parameter[@name=''CallSpreadEps'']', 560, 'double', false, 'Call spread eps', 'The width of the call-spread in rate terms.', 'The width of the call-spread in rate terms. Smaller values approach the analytical digital; larger values smooth the replication. Defaults to 1E-4 (1 basis point) if omitted. Allowable values: Any positive real number.', '1E-4', 'A number.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0178aa09-cf8e-57d3-8566-1bc5c8e3621e', 0, 'EngineParameters', 'IborRangeAccrualLeg', 'Correlation', 'ore.xsd', '/PricingEngines/Product[@type=''IborRangeAccrualLeg'']/EngineParameters/Parameter[@name=''Correlation'']', 561, 'double', false, 'Correlation', 'The correlation parameter used by the BGM range accrual pricer.', 'The correlation parameter used by the BGM range accrual pricer. Defaults to 1.0 if omitted. Allowable values: Any real number.', '1.0', 'A number.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3e328cad-dc56-5135-8932-8cb12b4f772d', 0, 'EngineParameters', 'IborRangeAccrualLeg', 'FlatVol', 'ore.xsd', '/PricingEngines/Product[@type=''IborRangeAccrualLeg'']/EngineParameters/Parameter[@name=''FlatVol'']', 562, 'double', false, 'Flat vol', 'The flat volatility value used when withFlatVol is set to true.', 'The flat volatility value used when withFlatVol is set to true. Defaults to 1E-6 if omitted. Allowable values: Any non-negative real number.', 'Not set in the examples.', 'Text.', '1.8.16.0', null),
