        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2ae5204c-4dec-5d99-9a72-ddda91c3a39b', 0, 'GlobalParameters', '', 'StrikeSpread', 'ore.xsd', '/PricingEngines/GlobalParameters/Parameter[@name=''StrikeSpread'']', 653, 'double', false, 'Strike spread', 'The strike spread that replication engines use.', 'It overrides the default value a replication engine uses to compute the strike spread of a replication portfolio.', '0.1', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9fcc8945-8ed4-5249-b3fb-f380ecebce98', 0, 'GlobalParameters', '', 'BondFutureAmericanAsEuropean', 'ore.xsd', '/PricingEngines/GlobalParameters/Parameter[@name=''BondFutureAmericanAsEuropean'']', 654, 'string', false, 'American bond future as European', 'Whether an American bond future option is priced as European.', 'It takes true, false or a regular expression. When it is true, every American bond future option is priced as though its exercise were European. When it is a regular expression, only the options whose underlying contract name matches it are. When it is false, the default, it has no effect.', 'false', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5efe90f4-e0ce-5900-afd2-d3b267ae8a23', 0, 'GlobalParameters', '', 'PseudoCurrency.TreatAsFX', 'ore.xsd', '/PricingEngines/GlobalParameters/Parameter[@name=''PseudoCurrency.TreatAsFX'']', 655, 'boolean', false, 'Pseudo-currency: treat as FX', 'Whether the pseudo-currency market is treated as an FX market.', 'It passes through to the pure FX handling of the pseudo-currency. With no global parameters, ORE treats the pseudo-currency as FX.', 'true', 'A flag, written true or false.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '273b07cd-8305-572f-8071-acae311d6f55', 0, 'GlobalParameters', '', 'PseudoCurrency.BaseCurrency', 'ore.xsd', '/PricingEngines/GlobalParameters/Parameter[@name=''PseudoCurrency.BaseCurrency'']', 656, 'string', false, 'Pseudo-currency base currency', 'The currency the pseudo-currency quotes against.', 'It names the base currency of the pseudo-currency market, usually USD.', 'USD', 'Text.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ae890ed0-0572-5e63-9ccd-809111ab1932', 0, 'GlobalParameters', '', 'PseudoCurrency.FXIndexTag', 'ore.xsd', '/PricingEngines/GlobalParameters/Parameter[@name=''PseudoCurrency.FXIndexTag'']', 657, 'string', false, 'Pseudo-currency FX index tag', 'The tag ORE uses when it asks for an FX correlation.', 'It is the tag of the FX index, such as GENERIC, so ORE requests a correlation named FX-GENERIC-USD-EUR rather than one named for a real currency pair.', 'GENERIC', 'Text.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eae4e774-2ab7-561b-bfdb-961454d50ca4', 0, 'GlobalParameters', '', 'PseudoCurrency.Curve.XAU', 'ore.xsd', '/PricingEngines/GlobalParameters/Parameter[@name=''PseudoCurrency.Curve.XAU'']', 658, 'string', false, 'Pseudo-currency curve for gold', 'The curve that prices the pseudo-currency XAU.', 'It maps the three-letter code XAU to the curve that prices it, such as PM:XAUUSD.', 'PM:XAUUSD', 'Text.', '1.8.13.0', null),
