        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f68b5879-5d1f-5882-a52f-26ad9d228693', 0, 'Pairs', 'FxEuropeanBarrierOption', 'ScriptedTrade|ScriptedTrade', 'ore.xsd', '/PricingEngines/Product[@type=''FxEuropeanBarrierOption'']/Model[@name=''ScriptedTrade'']/Engine[@name=''ScriptedTrade'']', 928, 'string', false, 'ScriptedTrade / ScriptedTrade', 'Delegates to the scripted trade engine and the associated pricing engine configuration for Product Type ScriptedTrade, see there for details.', 'Delegates to the scripted trade engine and the associated pricing engine configuration for Product Type ScriptedTrade, see there for details. A sample configuration is given in listing. Only FxBarrierOptions are supported at the moment. Typical use case for this pricing engine config would XVA calculation within the AMC framework.', 'The usual pair.', 'The model and engine that price FxEuropeanBarrierOption together.', '1.8.8.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '14453934-131d-51a0-9486-d0228ec2476a', 0, 'Pairs', 'FxForward', 'CrossAssetModel|AMC', 'ore.xsd', '/PricingEngines/Product[@type=''FxForward'']/Model[@name=''CrossAssetModel'']/Engine[@name=''AMC'']', 929, 'string', false, 'CrossAssetModel / AMC', 'Builds a McCamFxForwardEngine for use in AMC simulations.', 'Builds a McCamFxForwardEngine for use in AMC simulations. We refer to the AMC module documentation for further details. Parameter IncludeSettlementDateFlows is set to false by default, i.e. cash flows on the maturity date of the trade are not taken into account when pricing as of maturity date so that the trade has zero value on maturity. In case of true we do take the final flows into account while the trade is "maturing".', 'Not the usual pair.', 'The model and engine that price FxForward together.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e123fd2b-2471-533e-bd8f-6e51c68ed3d1', 0, 'Pairs', 'FxForward', 'DiscountedCashflows|DiscountingFxForwardEngine', 'ore.xsd', '/PricingEngines/Product[@type=''FxForward'']/Model[@name=''DiscountedCashflows'']/Engine[@name=''DiscountingFxForwardEngine'']', 930, 'string', false, 'DiscountedCashflows / DiscountingFxForwardEngine', 'Builds a DiscountingFxForwardEngine.', 'Builds a DiscountingFxForwardEngine.', 'The usual pair.', 'The model and engine that price FxForward together.', '1.8.7.0', null),
