        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3380c6eb-1461-5b9b-8255-924064e057d7', 0, 'Pairs', 'SyntheticCDO', 'GaussCopula|Bucketing', 'ore.xsd', '/PricingEngines/Product[@type=''SyntheticCDO'']/Model[@name=''GaussCopula'']/Engine[@name=''Bucketing'']', 954, 'string', false, 'GaussCopula / Bucketing', 'Builds a IndexCdsTrancheEngine.It uses a Bucketing Algorithm to compute the expected tranche loss.', 'Builds a IndexCdsTrancheEngine.It uses a Bucketing Algorithm to compute the expected tranche loss.', 'The usual pair.', 'The model and engine that price SyntheticCDO together.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5662c5ce-2d3e-5981-bf30-8c1996e4a593', 0, 'Pairs', 'SyntheticCDO', 'GaussCopula|MonteCarlo', 'ore.xsd', '/PricingEngines/Product[@type=''SyntheticCDO'']/Model[@name=''GaussCopula'']/Engine[@name=''MonteCarlo'']', 955, 'string', false, 'GaussCopula / MonteCarlo', 'Builds a IndexCdsTrancheEngine.', 'Builds a IndexCdsTrancheEngine. The expected tranche loss is computed using a Monte Carlo simulation.', 'Not the usual pair.', 'The model and engine that price SyntheticCDO together.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '372bffa1-d659-5269-aa78-e70099560938', 0, 'Pairs', 'YYCapFloor', 'YYCapModel|YYCapEngine', 'ore.xsd', '/PricingEngines/Product[@type=''YYCapFloor'']/Model[@name=''YYCapModel'']/Engine[@name=''YYCapEngine'']', 956, 'string', false, 'YYCapModel / YYCapEngine', 'Builds a YoYInflationBlackCapFloorEngine, YoYInflationUnitDisplacedBlackCapFloorEngine, YoYInflationBachelierCapFloorEngine depending on the volatility type of the market surface.', 'Builds a YoYInflationBlackCapFloorEngine, YoYInflationUnitDisplacedBlackCapFloorEngine, YoYInflationBachelierCapFloorEngine depending on the volatility type of the market surface.', 'The usual pair.', 'The model and engine that price YYCapFloor together.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e4715fe3-9f09-5071-b7fb-fe06b60ec068', 0, 'Types', '', 'BalanceGuaranteedSwap', 'ore.xsd', '/PricingEngines/Product[@type=''BalanceGuaranteedSwap'']', 957, 'string', false, 'Balance guaranteed swap', 'A swap whose notional follows a guaranteed balance rather than the actual outstanding.', 'A swap whose notional follows a guaranteed balance rather than the actual outstanding. It is used where amortisation is promised against a schedule.', 'The product type code.', 'The product type code of an ORE pricing engine.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd96de1e6-bfc5-5e43-8c3e-473980235812', 0, 'Types', '', 'CPICapFloor', 'ore.xsd', '/PricingEngines/Product[@type=''CPICapFloor'']', 958, 'string', false, 'CPI cap floor', 'An alternative product code for a CPI cap or floor, kept for trades and configurations that use the older spelling.', 'An alternative product code for a CPI cap or floor, kept for trades and configurations that use the older spelling.', 'The product type code.', 'The product type code of an ORE pricing engine.', '1.8.0.7 or earlier', null),
